// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 행운
// ==========================================
//
// 노름꾼 · 행상 · 점술가 · 수집가 · 거지
// 호러 · 공포 — 누가 보고 있고, 누가 부르고, 누가 끌고 간다.
// 행운의 몫은 여기서도 같다. 더 좋은 것을 줍는다. 다만 줍는 손을 무엇이 같이 쥔다.

// ==========================================
// 🎲 노름꾼 (gambler) · 자원 없음
// ==========================================
kJob('gambler', 'A', [

{ at:'A', t:'복도 — 세 개의 문',
  x:`복도 끝에 문이 셋 있다. 똑같은 철문이다. 번호도 손잡이 색도 같다.<br><br>
    천장 스피커에서 목소리가 난다. 다정하다. 셋 중 하나만 계단으로 이어진다고 한다. 나머지 둘 뒤에서는 무엇이 기다린다고.<br>
    고르라고 한다. 가운데 문에 손을 얹었다.<br><br>
    그러자 왼쪽 문이 저절로 열린다. 방 한가운데 무엇이 벽을 보고 서 있다. 문이 도로 조용히 닫힌다.<br>
    목소리가 묻는다. 바꾸겠느냐고.`,
  o:[
    { l:'① 바꾼다.', k:'luck', dc:22, wake:1,
      ok:`바꿨다. 오른쪽 문. 손잡이가 차다.<br><br>판을 연 쪽이 패 한 장을 보여 줄 때는 이유가 있다. 아무 패나 보여 주지 않는다. 처음 고른 문이 셋 중 하나였다면, 남은 문은 셋 중 둘이다.<br>열었다. 내려가는 계단이다. 등 뒤 가운데 문 안쪽에서 손톱이 문을 긁는다. 아주 천천히, 위에서 아래로.<br><br>셈은 손이 먼저 했다. 겁은 그 뒤에 왔다. 겁보다 셈이 먼저 오는 손이 됐다.`,
      ng:`바꿨다. 오른쪽 문을 열었다. 빈 방이 아니다.<br><br>방 한가운데 무엇이 벽을 보고 서 있다. 아까 왼쪽 방에 있던 것과 똑같다. 아니, 같은 것이다. 문 셋이 방 하나로 이어져 있었다.<br>문을 닫고 등으로 막았다. 문 너머에서 이쪽 숨에 맞춰 무엇이 숨을 쉰다. 한참 그러다 그쳤다.<br><br>판이 셋인 줄 알았는데 하나였다. 셈이 맞아도 판이 틀리면 진다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 바꾸지 않는다.', k:'steady', dc:22,
      ok:`가운데 문에서 손을 떼지 않았다.<br><br>목소리가 한 번 더 묻는다. 정말이냐고. 다정하게. 두 번 묻는 건 바꾸게 하고 싶어서다. 판을 연 쪽이 바라는 수는 두지 않는 법이다.<br>열었다. 계단이다. 스피커가 짧게 지직거리고 꺼졌다.<br><br>셈으로는 틀린 수였다. 상대를 읽어서 이겼다. 둘 다 패다.`,
      ng:`버텼다. 목소리가 세 번 묻는다. 네 번. 물을 때마다 다정함이 조금씩 빠진다.<br><br>열었다. 문 바로 뒤에 무엇이 서 있다. 코가 닿을 거리다. 얼굴 높이에 아무것도 없다.<br>문을 닫는 데 어깨를 다 썼다. 문틈으로 손가락 끝 하나가 나왔다가 들어갔다. 그 손가락 길이를 한동안 잊지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'③ 문 말고 스피커를 본다.', k:'sense', dc:22,
      ok:`올려다봤다. 목소리가 나올 때 스피커 둘레 먼지가 떤다. 문마다 스피커가 하나씩이다. 오른쪽 문 위 스피커만 안 떤다.<br><br>그 문 위에서는 아무도 말하지 않는다. 기다리는 것이 없는 쪽은 할 말도 없다.<br>오른쪽을 열었다. 계단이다.<br><br>패를 안 보고 패 돌리는 입을 봤다.`,
      ng:`오래 올려다봤다. 스피커 셋이 다 떤다. 목소리가 이쪽 이름을 부른다. 처음 듣는 목소리인데 이름은 맞다.<br><br>목덜미가 굳었다. 누가 고른 것도 아닌데 문 하나가 열렸다. 그 안을 안 본 채로 뒷걸음질했다.<br>한참 뒤에야 발이 계단을 찾았다. 이름 불린 귀가 오래 먹먹했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'A', t:'계단참 — 엎어 둔 패',
  x:`계단참마다 카드가 한 장씩 엎어져 있다. 바닥 한가운데, 반듯하게.<br><br>
    첫 장은 그냥 지나쳤다. 둘째 장도. 셋째 계단참에서 알았다. 카드가 층마다 조금씩 돌아앉는다. 귀퉁이가 이쪽 발끝을 향한다.<br>
    누가 이쪽에게 패를 돌리고 있다.<br><br>
    넷째 장은 반쯤 들려 있다. 그림 귀퉁이가 보인다. 신발 끈이다. 이쪽 신발과 같은 색이다.`,
  o:[
    { l:'① 뒤집어 본다.', k:'gaze', dc:23,
      doom:{ title:'넷째 장', what:'카드 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`뒤집었다. 그림이다. 계단참이 그려져 있다. 이 계단참이다. 가운데 사람이 하나 엎드려 있다. 신발 끈 색이 같다.<br><br>그림 속 사람이 고개를 든다. 이쪽 얼굴이다. 손을 뻗는다. 카드 밖으로.<br>손목을 잡혔다. 종이가 살에 착 붙는다. 당긴다. 카드는 손바닥만 한데 팔이 팔꿈치까지 들어간다.<br><br>처음부터 이쪽에게 패를 돌린 게 아니었다. 이쪽을 패로 돌렸다.`,
        dieText:`계단참 바닥에 카드가 한 장 엎어져 있다. 반듯하게.<br><br>다음에 올라오는 사람 발끝 쪽으로 귀퉁이가 조금 돌아앉아 있다.<br>뒷면 무늬 사이에 신발 끈 한 가닥이 끼어 있다.` },
      ok:`손끝으로 귀퉁이만 들어 그림을 봤다. 계단참이 그려져 있다. 비어 있다.<br><br>아직 아무도 안 그려졌다. 다음 장에 그려질 것이다. 카드를 도로 엎지 않고 반으로 접었다. 접힌 카드는 패가 아니다.<br>다섯째 계단참에는 카드가 없었다. 돌릴 패가 끊긴 것이다.<br><br>판을 깨는 법은 많다. 패를 못 쓰게 만드는 게 제일 조용하다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 안 보고 발끝으로 밀어 엎는다.', k:'steady', dc:22,
      ok:`보지 않았다. 발끝으로 밀어 완전히 엎고 귀퉁이를 벽 쪽으로 돌려놓았다.<br><br>남이 돌린 패는 안 받는다. 받지 않은 패는 이쪽 패가 아니다. 다섯째, 여섯째 계단참에서도 똑같이 했다. 카드는 층마다 조금씩 덜 돌아앉았다.<br>마지막 장은 벽을 보고 있었다. 돌리던 쪽이 그만둔 것이다.`,
      ng:`미는데 카드가 신발 밑에 붙는다.<br><br>발을 털었다. 안 떨어진다. 다음 계단참까지 카드를 밟고 올라갔다. 걸을 때마다 신발 밑에서 무엇이 바스락거리며 그림을 그린다.<br>계단참에서 겨우 떼어 냈다. 뒷면이 이쪽 발바닥 모양으로 젖어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 한 손 더',
  x:`쉬는 자리에서 먹을 것을 나눴다. 패 돌리듯이. 노름꾼 손이 제일 고르다고 다들 그에게 맡긴다.<br><br>
    한 바퀴 돌렸다. 말린 고기가 한 줄 모자란다. 셈이 틀릴 리 없다. 다시 돌렸다. 또 한 줄 모자란다.<br>
    일행을 셌다. 맞다. 손을 셌다. 하나가 더 있다.<br><br>
    등불이 닿지 않는 자리에서 손 하나가 손바닥을 위로 하고 기다린다. 받을 차례인 것처럼.`,
  o:[
    { l:'① 패를 돌리며 손의 버릇을 본다.', k:'luck', dc:22, wake:1,
      ok:`아무 말 없이 한 바퀴 더 돌렸다. 이번엔 일부러 느리게.<br><br>산 사람 손은 좋은 패가 오면 조금 일찍 나온다. 그 손은 아니다. 어떤 줄이 가도 같은 박자로 나온다. 제일 두꺼운 줄 차례에 그 손을 건너뛰었다. 손이 잠시 허공에 머물다 거둬졌다.<br>다음 바퀴부터 셈이 맞았다. 건너뛴 두꺼운 줄이 이쪽 무릎 위에 남았다.<br><br>패를 돌리며 손을 읽는다. 사람 손이든 아니든. 판 위의 손 하나하나가 이제 저마다 다른 말을 한다.`,
      ng:`느리게 돌리는데 그 손이 일찍 나온다. 제일 두꺼운 줄 차례에.<br><br>줄을 낚아채 어둠 속으로 들어간다. 씹는 소리가 아주 작게 난다.<br>그 뒤로 누구도 제 몫을 다 먹지 못했다. 다들 어둠을 등지고 앉았다. 등이 내내 시렸다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-16 } },
    { l:'② 그 손 몫까지 돌린다.', k:'bond', dc:21,
      ok:`한 줄 떼어 그 손바닥에 얹었다. 남은 것을 다시 나눴다. 다들 조금씩 덜 먹었다.<br><br>손이 줄을 쥐고 어둠 속으로 들어간다. 조용하다. 다시는 안 나온다.<br>판에 끼워 준 손은 판을 엎지 않는다. 오래전에 판에서 배운 셈이다.`,
      ng:`얹었는데 손이 안 거둬진다. 다음 줄을 기다린다.<br><br>또 얹었다. 또 기다린다. 다들 제 몫을 꼭 쥐었다.<br>그만 주자 손이 등불 쪽으로 한 뼘 다가왔다. 손목이 길다. 일행이 자리를 옮겼다. 짐 반을 두고.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-15, spirit:-18 } },
    { l:'③ 판을 걷는다.', k:'fix', dc:22,
      ok:`"오늘은 판 접자." 먹을 것을 한데 모았다. 각자 품에 직접 넣게 했다. 손에서 손으로, 아는 손끼리만.<br><br>돌리는 판이 없으면 받을 차례도 없다. 그 손이 한참 손바닥을 펴고 있다가 오므렸다.<br>셈이 맞았다.`,
      ng:`모으는데 누가 제 몫을 안 내놓는다. 겁이 나서다.<br><br>실랑이 사이에 꾸러미 하나가 바닥에 떨어져 어둠 쪽으로 굴러갔다. 아무도 주우러 가지 않았다.<br>꾸러미가 끌려가는 소리가 들렸다. 천천히. 다 끌려갈 때까지 아무도 말을 안 했다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'A', t:'방 — 술래의 버릇',
  x:`어두운 방에 들어서자 문이 닫힌다. 방 저쪽에서 아이 목소리가 숫자를 센다.<br><br>
    하나. 둘. 숨으라는 것이다. 열까지 센다고 한다.<br>
    숨을 데는 셋이다. 커튼 뒤, 옷장 안, 침대 밑. 이런 판은 안다. 술래도 사람처럼 버릇이 있다.<br><br>
    여섯. 일곱. 술래는 늘 제일 가까운 데부터 본다. 아니면 늘 제일 먼 데부터.`,
  o:[
    { l:'① 술래가 거를 자리에 건다.', k:'luck', dc:23,
      doom:{ title:'술래', what:'술래에게 발목을 잡혀 끌려갑니다', dc:18, sec:50,
        text:`커튼 뒤에 섰다. 너무 뻔해서 술래가 거를 자리다.<br><br>열. 발소리가 온다. 옷장을 연다. 침대 밑을 본다. 커튼은 안 본다. 됐다.<br>발소리가 멈췄다. 커튼 밑자락 틈으로 작은 손이 들어온다. 발목을 잡는다. 아주 차다.<br><br>찾았다. 목소리가 웃는다. 여기 술래는 찾은 사람을 다음 술래로 만들지 않는다. 데려간다.`,
        dieText:`방에서 아이 목소리가 숫자를 센다.<br><br>하나. 둘. 목소리가 둘이다. 하나는 조금 낮다. 아직 서툴다.<br>커튼 밑자락이 조금 더 길어졌다.` },
      ok:`커튼 뒤에 섰다. 숨을 반으로 줄였다.<br><br>열. 발소리가 옷장을 연다. 침대 밑을 본다. 그리고 커튼 앞에서 오래 선다. 커튼 자락이 숨결에 조금 흔들린다. 이쪽 숨이 아니다.<br>발소리가 돌아섰다. 다시 센다. 하나. 둘. 그 사이에 문을 열고 나왔다.<br><br>판은 뻔한 데서 진다. 뻔해 보이는 데서 이긴다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 숨지 않고 술래 등 뒤에 붙는다.', k:'hide', dc:22,
      ok:`숨지 않았다. 목소리 나는 쪽으로 소리 없이 다가가 그 등 뒤에 붙었다.<br><br>열. 술래가 돌아선다. 이쪽도 같이 돌아선다. 늘 등 뒤에. 술래는 옷장을, 침대 밑을, 커튼을 본다. 아무도 없다.<br>술래가 문을 열고 다음 방으로 간다. 등 뒤에 붙은 채 같이 나왔다. 복도에서 떨어졌다.<br><br>술래는 제 등 뒤는 안 센다.`,
      ng:`다가가는데 마룻바닥이 운다.<br><br>숫자가 일곱에서 멈췄다. 목소리가 바로 앞에서 숨을 들이쉰다.<br>뒤로 물러나 옷장 안으로 뛰어들었다. 문틈으로 작은 눈이 한참 들여다봤다. 술래는 열까지 세지 않으면 못 연다. 그 규칙 하나로 버텼다. 문고리를 쥔 손가락이 하얗게 굳었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-24 } }
  ] },

{ at:'A', t:'어둠 — 머릿수 내기',
  x:`등불이 꺼졌다. 다시 켜지지 않는다.<br><br>
    어둠 속에서 목소리가 묻는다. 지금 이 방에 몇이 있는지. 맞히면 불을 켜 주겠다고 한다. 틀리면 하나를 데려가겠다고.<br>
    일행 수는 안다. 들어올 때 셌다.<br><br>
    숨소리를 셌다. 하나가 더 많다. 그 하나는 숨을 아주 천천히 쉰다.`,
  o:[
    { l:'① 숨소리를 끝까지 센다.', k:'sense', dc:22,
      ok:`숨을 죽이고 셌다. 들숨, 날숨. 하나는 다른 숨보다 길다. 그 숨은 들이쉬기만 한다.<br><br>그건 숨이 아니다. 냄새를 맡는 소리다.<br>그것까지 넣어 말했다. 목소리가 한참 말이 없다. 불이 켜졌다. 방 구석은 비었다. 바닥에 젖은 자국만 동그랗게 남았다.`,
      ng:`세는데 숨이 자꾸 겹친다. 일행이 겁에 질려 숨을 몰아쉰다.<br><br>일행 수만 말했다. 목소리가 틀렸다고 한다. 다정하게.<br>불이 켜졌다. 다들 있다. 그런데 일행 하나 어깨에 손자국이 있다. 데려가다 만 것처럼. 그 사람은 그 뒤로 말을 잘 안 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 하나를 더 불러 허세를 친다.', k:'luck', dc:23, wake:1,
      ok:`숫자를 말했다. 숨소리보다도 하나 더.<br><br>목소리가 멈춘다. 이 방에 저쪽도 모르는 것이 하나 더 있다고 말한 셈이다. 모르는 패를 상대가 쥐었다고 믿게 하면 판은 이쪽으로 기운다.<br>오래 조용하다. 불이 켜졌다. 목소리는 더 묻지 않았다.<br><br>쥔 것 없이 건 판을 이겼다. 허세가 손짓이 아니라 셈이 됐다. 몇 장을 더 불러야 상대가 접는지 이제 손이 잰다.`,
      ng:`하나 더 불렀다. 목소리가 웃는다. 맞다고 한다.<br><br>불이 켜졌다. 방 구석에 그것이 서 있다. 이쪽이 부른 그 하나다. 아까는 없었다. 불러서 생긴 것이다.<br>방을 나오는 동안 그것은 일행 맨 뒤에 섰다. 계단에서 떨어졌다. 떨어질 때까지 목덜미에 숨이 닿았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A', t:'복도 끝 — 쌓인 판돈',
  x:`복도 끝에 물건이 쌓여 있다.<br><br>
    신발, 장갑, 머리끈, 등불, 손목시계. 하나같이 누가 지니고 다니던 것이다. 더미 맨 위에 낯익은 것이 있다.<br>
    늘 지니고 다니던 주사위다. 주머니를 더듬었다. 없다. 언제 잃었는지 모른다.<br><br>
    잃은 판을 쫓는 사람이 어떻게 되는지는 안다. 더미가 그걸 보여 준다.`,
  o:[
    { l:'① 두고 간다.', k:'steady', dc:22, wake:1,
      ok:`주사위를 보지 않았다. 더미 앞을 지나쳤다.<br><br>등 뒤에서 무엇이 굴러온다. 주사위다. 발뒤꿈치에 와 닿는다. 주워 가라고. 안 주웠다. 계단을 내려갔다. 굴러오는 소리가 계단 첫 칸에서 멈췄다.<br>주머니가 가볍다. 마음은 조금 더 가볍다.<br><br>잃은 것을 쫓지 않으면 잃은 것도 사람을 못 쫓는다. 그 셈이 이제 버릇이 아니라 뼈가 됐다.`,
      ng:`지나치는데 더미에서 주사위가 굴러 떨어진다. 여섯.<br><br>여섯이 나오면 손이 저절로 간다. 반쯤 허리를 굽혔다가 멈췄다. 그 사이 더미 속에서 무엇이 손목시계 줄을 잡아당겼다.<br>줄이 끊기며 시계가 더미로 들어갔다. 이제 판돈이 둘이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 주사위를 되찾는다.', k:'luck', dc:24,
      doom:{ title:'잃은 판돈', what:'판돈 더미 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`손을 뻗어 주사위를 집었다. 따뜻하다.<br><br>집는 순간 더미가 손을 문다. 신발 끈이 손가락에 감기고 장갑 손가락이 손목을 쥔다. 다 같은 쪽으로 당긴다. 더미 속으로.<br>어깨까지 들어갔다. 안쪽이 넓다. 손이 많다. 잃은 것을 찾으러 들어온 손들이다.<br><br>판돈을 되찾으러 판에 다시 앉는 사람들을 노름꾼은 수없이 봤다. 다 이렇게 들어갔다.`,
        dieText:`복도 끝 더미가 조금 높아졌다.<br><br>맨 위에 주사위가 하나 얹혀 있다. 여섯이 위를 본다.<br>다음에 오는 사람 주머니에서 무엇인가 하나가 빠질 것이다.` },
      ok:`손등으로 쳐서 주사위만 쳐냈다. 집지 않았다.<br><br>주사위가 더미에서 굴러 나와 바닥에서 돈다. 더미 속 손들이 늦게 움켜쥔다. 빈 데를.<br>바닥에 멈춘 주사위를 그제야 주웠다. 더미 밖에서 주운 것은 더미 것이 아니다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'창 — 먼저 눈을 감는 쪽',
  x:`창밖에 얼굴이 있다.<br><br>
    유리에 코를 대고 이쪽을 본다. 눈을 깜빡이지 않는다. 입김도 없다.<br>
    이런 판은 안다. 먼저 눈을 돌리는 쪽이 진다. 판에서도 그렇다.<br><br>
    다만 저쪽은 눈꺼풀이 없다.`,
  o:[
    { l:'① 얼굴을 지운 채 버틴다.', k:'steady', dc:23,
      ok:`표정을 다 지웠다. 패를 쥔 얼굴로.<br><br>눈이 시리다. 눈물이 고인다. 그래도 안 감았다. 판에서는 상대도 시리다고 믿어야 한다. 눈꺼풀이 없어도.<br>얼굴이 유리에서 떨어졌다. 천천히 뒤로, 어둠 속으로.<br><br>이쪽이 이긴 게 아니다. 저쪽이 다른 판을 찾으러 갔다.`,
      ng:`버티는데 일행 하나가 이쪽 어깨를 친다. 무슨 일이냐고.<br><br>눈이 감겼다. 아주 잠깐. 눈을 떴을 때 얼굴은 유리 이쪽에 있었다.<br>뒷걸음질 쳤다. 얼굴이 따라오지 않는다. 그 자리에 그대로 떠 있다. 이제 이쪽이 유리 밖에 서 있는 것 같았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 눈 대신 유리를 본다.', k:'gaze', dc:22,
      ok:`얼굴 말고 유리를 봤다. 얼굴 둘레에만 성에가 낀다. 바깥이 찬 게 아니다. 그것이 차다.<br><br>성에가 손자국 모양으로 번져 있다. 유리 이쪽에서 누가 짚은 자국이다. 이쪽 키 높이다. 얼굴은 그 손자국 자리에서만 이쪽을 볼 수 있다.<br>몸을 낮춰 손자국 아래로 창을 지났다. 얼굴은 끝까지 따라 내려오지 못했다.`,
      ng:`유리를 보는데 시야 귀퉁이에서 얼굴이 웃는다.<br><br>입꼬리가 귀까지 간다. 보지 않으려 해도 귀퉁이가 그걸 본다. 고개가 돌아갔다. 정면으로 봤다.<br>그 뒤로 한참, 눈을 감으면 그 웃음이 보였다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-15, spirit:-20 } }
  ] },

{ at:'A', t:'계단 — 올라갈 때만 있는 칸',
  x:`계단을 내려가며 셌다. 열세 칸이다.<br><br>
    수를 세는 건 버릇이다. 층계참에 무엇을 두고 온 것 같아 다시 올라갔다. 열네 칸이다.<br>
    다시 내려갔다. 열세 칸. 올라갔다. 열네 칸.<br><br>
    올라갈 때만 있는 한 칸이 어디 있는지 모른다.`,
  o:[
    { l:'① 셈을 맞춰 그 칸을 찾는다.', k:'luck', dc:22,
      ok:`칸마다 숫자를 소리 내 불렀다. 일곱에서 발이 조금 깊이 내려앉는다. 다른 칸보다 손가락 한 마디쯤.<br><br>그 칸을 밟지 않고 건넜다. 올라갈 때도 건넜다. 열세 칸, 열세 칸.<br>셈이 맞자 계단 아래가 조용해졌다. 일곱째 칸 밑에서 무엇이 한숨 같은 것을 쉬었다.`,
      ng:`소리 내 불렀는데 일곱이 두 번 들린다. 이쪽 목소리가 아니다. 계단 밑에서 따라 부른다.<br><br>멈췄다. 따라 부르던 목소리가 여덟을 혼자 부른다. 아홉. 열. 이쪽 발은 아직 일곱에 있다.<br>달려 내려갔다. 몇 칸이었는지는 이제 모른다. 무릎이 계단 모서리에 몇 번이나 찍혔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 세지 않고 난간을 타고 내려간다.', k:'evade', dc:22,
      ok:`세지 않았다. 난간을 잡고 몸을 띄워 층계참까지 미끄러졌다.<br><br>안 밟으면 몇 칸이든 상관없다. 손바닥이 쓸렸지만 그뿐이다.<br>세는 버릇이 늘 이롭지는 않다.`,
      ng:`난간이 젖어 있다. 손이 미끄러졌다.<br><br>계단으로 떨어졌다. 구르는 동안 몸이 칸을 셌다. 열넷. 열다섯. 열여섯.<br>층계참에 닿았을 때 갈비가 쑤셨다. 계단 위에서 누가 손뼉을 한 번 쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'A', t:'불 꺼진 방 — 멈추지 않는 동전',
  x:`불 꺼진 방에서 동전 소리가 난다.<br><br>
    바닥에서 동전이 돈다. 모로 서서. 한참을 돌아도 느려지지 않는다.<br>
    동전이 쓰러질 때는 소리로 안다. 소리가 낮아지고 떨림이 길어진다. 이 동전은 소리가 안 변한다.<br><br>
    누가 손가락으로 계속 튕기고 있다. 동전 옆 어둠에서.`,
  o:[
    { l:'① 쓰러질 쪽을 부른다.', k:'luck', dc:22,
      ok:`"앞." 크게 말했다.<br><br>동전이 기울었다. 앞면이 위로. 어둠 속 손가락이 멈칫한다. 판에 건 사람이 생겼으니 판을 끝내야 한다.<br>동전 옆에 꿈결 몇 알이 놓여 있다. 판돈이다. 손가락이 그걸 이쪽으로 민다. 집어 들고 방을 나왔다.<br><br>걸어 주는 사람이 있어야 판은 끝난다.`,
      ng:`"앞." 말했는데 동전이 뒷면으로 눕는다.<br><br>손가락이 동전을 집어 간다. 그리고 이쪽 손등을 툭 친다. 다음 판돈을 내라고.<br>손등이 차갑게 저리다. 저린 데가 오래 남았다. 무엇을 냈는지는 모른다.`,
      win:{ exp:18, dream:4 }, lose:{ mind:-15, spirit:-22 } },
    { l:'② 동전을 밟아 판을 멈춘다.', k:'break', dc:22,
      ok:`발로 동전을 밟았다. 소리가 끊긴다.<br><br>신발 밑에서 손가락이 동전을 빼내려 한다. 힘을 줬다. 손가락이 물러났다.<br>동전을 주웠다. 앞면도 뒷면도 그림이 없다. 미끄럽다. 주머니에 넣지 않고 멀리 던졌다.`,
      ng:`밟았는데 신발 밑에서 동전이 계속 돈다. 발바닥이 떨린다.<br><br>떨림이 발목을, 무릎을 타고 올라온다. 이가 딱딱 맞부딪쳤다.<br>발을 떼자 동전이 멈췄다. 이쪽 무릎이 대신 떨렸다. 한참.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 판을 등지지 않고 문까지 물러난다.', k:'evade', dc:21,
      ok:`얼굴을 동전 쪽에 둔 채 뒷걸음질했다. 판이 돌아가는 동안 판을 등지면 안 된다.<br><br>문고리가 손에 닿았다. 동전 소리는 끝까지 같았다.<br>문을 닫자 문 너머에서 동전이 쓰러지는 소리가 났다. 아무도 안 걸었다.`,
      ng:`물러나는데 동전이 이쪽으로 굴러온다. 모로 선 채로. 발끝까지 따라온다.<br><br>문을 열고 뛰었다. 복도 끝까지 동전 소리가 따라왔다. 계단 앞에서 끊겼다.<br>발목에 동그란 멍이 남았다. 동전만 한 크기다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'A', t:'내려가는 길 — 한 판 더',
  x:`계단 앞에 상이 차려져 있다.<br><br>
    나무 상 위에 패가 한 벌. 의자 둘. 맞은편 의자에 그림자가 앉아 있다. 몸은 없고 그림자만.<br>
    그림자가 패를 섞는다. 그리고 이쪽 주머니를 가리킨다. 여기까지 주운 것들을 안다는 듯이.<br><br>
    한 판만 하자고 한다. 이기면 배로 준다고. 노름꾼은 이 말을 평생 들었다.`,
  o:[
    { l:'① 판을 접는다.', k:'steady', dc:22, wake:1,
      ok:`의자를 밀어 상 밑에 넣었다. 앉지 않겠다는 뜻이다.<br><br>그림자가 패를 한 장 뒤집어 보인다. 좋은 패다. 또 한 장. 더 좋은 패다. 보여 주는 패는 늘 좋다.<br>등을 돌려 계단을 내려갔다. 등 뒤에서 패 섞는 소리가 한참 났다. 다음 사람을 위해 섞는 소리다.<br><br>딴 채로 일어서는 것. 판에서 제일 어려운 수가 손에 붙었다. 앉고 싶은 마음까지 세는 셈이 손가락 끝에 생겼다.`,
      ng:`의자를 밀었는데 그림자가 패를 한 장 뒤집는다. 이쪽 이름이 적혀 있다.<br><br>그 패를 보느라 한참 서 있었다. 다리가 굳는다. 계단을 내려갈 때 무릎이 접혔다.<br>내려가는 내내 주머니가 가벼워지는 것 같았다. 실제로 하나가 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 제일 시시한 판돈으로 한 판만 한다.', k:'luck', dc:24,
      ok:`앉았다. 패가 왔다. 보지 않았다. 판돈으로 제일 쓸모없는 것을 냈다. 부러진 끈 한 토막.<br><br>그림자가 패를 깐다. 이쪽도 깠다. 이겼다. 그림자가 배로 내민다. 부러진 끈 두 토막. 그리고 그 밑에 말린 고기 한 줄.<br>바로 일어섰다. 그림자가 붙잡지 않았다. 판돈이 시시하면 판도 사람을 시시하게 놓아준다.`,
      ng:`앉았다. 첫 판을 땄다. 두 번째 판도. 그림자가 계속 배로 준다.<br><br>세 번째 패를 받는데 손이 이쪽 손 같지 않다. 손등이 그림자처럼 얇다. 일어나려고 상을 밀었다. 일행이 의자째 끌어냈다.<br>딴 것은 다 상 위에 두고 왔다. 손등이 오래 얇았다. 등불에 비추면 뼈가 보였다.`,
      win:{ exp:20, dream:4, item:'말린 고기' }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A1', t:'퀴즈 코너 — 돌림판',
  x:`무대 옆 세트에 커다란 돌림판이 서 있다. 칸마다 색이 다르고, 칸 안에 그림이 있다.<br><br>
    사탕. 풍선. 꽝. 그리고 웃는 해 얼굴 한 칸. 그 칸만 다른 칸보다 조금 넓다.<br>
    바늘 옆에 글씨가 붙어 있다. 착한 어린이는 한 번씩. 스피커에서 박수가 난다. 돌려 보라는 박수다.<br><br>
    돌림판이라면 잘 안다. 넓은 칸 옆 못이 다른 못보다 반짝인다. 바늘이 자주 걸린 못이다.`,
  o:[
    { l:'① 바늘 소리를 세며 돌린다.', k:'luck', dc:22, wake:1,
      ok:`손잡이를 쥐고 힘을 쟀다. 바늘이 못 하나를 넘을 때마다 딱 소리가 난다. 반짝이는 못까지 서른한 번.<br><br>스물아홉 번이 될 만큼만 밀었다. 딱. 딱. 바늘이 느려진다. 해 얼굴 칸 바로 앞, 사탕 칸에서 섰다.<br>세트 뒤에서 상자가 밀려 나온다. 꿀을 굳힌 알사탕이 들었다. 포장지마다 웃는 해가 찍혀 있다.<br><br>돌림판은 한 번도 공평한 적이 없다. 그 기울기를 손목이 잰다. 바늘 소리가 이제 셈으로 들린다.`,
      ng:`서른한 번을 세는데 박수가 세는 소리를 덮는다. 몇 번째 딱인지 놓쳤다.<br><br>바늘이 넓은 칸에 서려다 겨우 넘어갔다. 꽝.<br>꽝 칸이 열리며 물이 쏟아졌다. 무대 바닥이 젖는다. 미끄러져 세트 모서리에 머리를 찧었다. 박수가 웃음소리로 바뀌었다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 세게 돌린다.', k:'luck', dc:24,
      doom:{ title:'해님 칸', what:'하얀 장갑들에게 무대로 끌려 나갑니다', dc:18, sec:50,
        text:`세게 돌렸다. 바늘이 따르르 운다. 세게 돌린 판은 운이 정한다고 믿었다.<br><br>바늘이 넓은 칸에서 멈춘다. 반짝이는 못에 걸려서. 웃는 해 얼굴. 스피커에서 팡파르가 터진다.<br>무대 위에서 하얀 장갑들이 내려온다. 손가락이 넷이다. 어깨를, 손목을, 허리를 잡는다. 축하한다는 손짓으로. 무대 가운데로 끌고 간다.<br><br>운에 맡긴 판은 판을 짠 쪽이 이긴다. 노름꾼은 그걸 알면서 세게 돌렸다.`,
        dieText:`돌림판이 다시 천천히 돈다. 아무도 안 돌렸는데.<br><br>해 얼굴 칸이 조금 더 넓어졌다. 칸 안 그림에 아이가 하나 늘었다. 손을 흔든다.<br>스피커에서 박수가 났다. 다음 착한 어린이를 부르는 박수다.` },
      ok:`세게 돌리고 손을 놓자마자 바늘 밑에 신발 한 짝을 끼웠다.<br><br>바늘이 신발에 걸려 엉뚱한 칸에서 섰다. 풍선. 판이 운으로 굴러가는 척할 때 이쪽은 손으로 굴렸다.<br>세트 위에서 풍선 하나가 내려온다. 끈에 꿈결 주머니가 매달렸다. 장갑들은 내려오지 않았다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 돌리지 않고 돌림판 뒤를 본다.', k:'sense', dc:22,
      ok:`돌림판 뒤로 돌아갔다. 판 뒷면에 줄이 하나 달렸다. 줄은 천장으로 간다. 넓은 칸에 바늘이 서면 줄이 당겨지는 장치다.<br><br>당겨지면 무엇이 내려오는지는 안 봤다. 줄을 칼로 끊었다.<br>앞으로 돌아오자 돌림판이 혼자 돌다 꽝에 섰다. 스피커가 조용하다. 박수 칠 데가 없다.`,
      ng:`세트 뒤로 돌아가는데 세트 뒤도 무대다.<br><br>조명이 이쪽에 꽂힌다. 빈 방청석에서 박수가 쏟아진다. 무대 뒤가 아니라 무대 앞으로 나온 것이다.<br>허리를 숙이고 조명 밖으로 기어 나왔다. 조명이 끝까지 따라왔다. 눈앞이 한참 하얬다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'A1', t:'방청석 — 가위바위보 시간',
  x:`방청석 앞 화면에 방글이가 나온다. 노란 해 얼굴. 그려 넣은 입이 웃는다.<br><br>
    친구들, 가위바위보 하자. 진 친구는 일어나세요. 화면 속 하얀 장갑이 주먹을 쥐고 흔든다.<br>
    벽에 방청 규칙이 붙어 있다. 둘, 자리에서 일어나지 않기.<br><br>
    손을 봤다. 장갑이 주먹을 흔들 때 손가락 하나가 먼저 꿈틀한다. 무엇을 낼지 그 손가락이 먼저 안다.`,
  o:[
    { l:'① 꿈틀하는 손가락을 읽고 낸다.', k:'gaze', dc:22,
      ok:`가위. 바위. 보. 장갑 둘째 손가락이 먼저 펴지려 한다. 가위다.<br><br>바위를 냈다. 이겼다. 화면 속 입이 잠깐 멈춘다. 그려 넣은 입이 멈추는 걸 처음 봤다.<br>다음 판, 다음 판. 손가락은 매번 먼저 말했다. 다섯 판을 내리 이기자 화면이 바뀌었다. 상품 시간. 의자 밑에서 상자가 밀려 나왔다.<br><br>말린 고기 꾸러미다. 웃는 해 스티커가 붙었다. 스티커 뒷면에 적혀 있다. 다음 주에도 와 줘.`,
      ng:`손가락을 보는데 장갑 손가락이 넷이다. 어느 것이 먼저 움직일 손가락인지 모른다.<br><br>찍었다. 졌다. 화면 속 입이 크게 벌어진다. 일어나세요.<br>엉덩이가 의자에서 들린다. 이쪽이 든 게 아니다. 팔걸이를 붙잡고 버텼다. 손톱이 들렸다. 진 판이 끝날 때까지 몸이 한 뼘 떠 있었다.`,
      win:{ exp:20, dream:3, item:'말린 고기' }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 손을 허벅지 밑에 깔고 앉는다.', k:'steady', dc:23,
      ok:`두 손을 허벅지 밑에 깔았다. 안 낸 손은 진 손이 아니다.<br><br>화면 속 손이 한참 이쪽을 향해 흔든다. 가위. 바위. 보. 가위. 바위. 보.<br>계속 안 냈다. 화면이 다른 줄로 돌아갔다. 판에 안 끼는 손님은 손님 대접을 못 받는다. 여기서는 그게 살 길이다.`,
      ng:`깔고 앉았는데 손이 저절로 빠져나온다. 손가락이 펴진다. 보.<br><br>화면 속 손은 가위다. 졌다. 일어나세요.<br>무릎이 펴졌다. 일행이 허리를 잡아 앉혔다. 둘이 함께 의자에 매달렸다. 그사이 의자 다리가 바닥에서 반쯤 뽑혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A1', t:'부조정실 — 같은 회차',
  x:`모니터 벽에 같은 화면이 몇십 개 떠 있다.<br><br>
    방글 동산. 오늘 회차다. 그런데 모니터마다 반 박자씩 다르다. 한쪽 끝 화면에서 방글이가 손을 흔들면 반대쪽 끝 화면에서는 이제 막 팔을 든다.<br>
    패가 도는 순서라면 외우는 게 일이다. 같은 회차라면 같은 순서다.<br><br>
    맨 앞선 화면 속 방글이가 고개를 돌린다. 부조정실 문 쪽을. 이 방 문이다.`,
  o:[
    { l:'① 앞서가는 화면으로 다음 수를 읽는다.', k:'luck', dc:22, wake:1,
      ok:`제일 앞선 화면만 봤다. 방글이가 고개를 돌리고, 손을 흔들고, 카메라를 본다. 그다음 등을 돌린다. 열을 셀 동안.<br><br>뒤처진 화면들이 차례로 따라온다. 이 방 문밖의 것이 등을 돌릴 때를 미리 알았다. 그때 문을 나섰다. 복도 끝에서 노란 것이 등을 돌린 채 서 있었다. 열을 세는 동안 지나갔다.<br><br>같은 판이 몇 번 돌아도 손님은 처음 보는 줄 안다. 판을 미리 보는 눈이 화면 하나만큼 앞에 서게 됐다.`,
      ng:`앞선 화면을 따라 세는데 화면 하나가 갑자기 멈춘다. 다른 회차가 섞였다.<br><br>그 화면 속 방글이는 고개를 안 돌린다. 이쪽을 본다. 모니터 너머에서. 셈이 엉켰다.<br>문을 나서다 복도에서 노란 것과 마주쳤다. 등을 안 돌린 쪽이었다. 반대로 뛰었다. 계단 난간에 갈비를 찧었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 모니터를 하나씩 끈다.', k:'fix', dc:23,
      ok:`조정판 스위치를 하나씩 내렸다. 화면이 하나씩 꺼진다.<br><br>꺼진 화면에 이 방이 비친다. 까만 유리에. 스위치를 내리는 이쪽 모습. 그 뒤에 아무도 없다.<br>마지막 화면만 안 꺼진다. 그건 보지 않고 방을 나왔다.`,
      ng:`내리는데 꺼진 화면마다 이 방이 비친다. 이쪽 뒤에 노란 것이 서 있다. 화면마다 조금씩 가까이.<br><br>돌아봤다. 없다. 다시 화면을 봤다. 바로 등 뒤다.<br>스위치를 다 올렸다. 손이 떨려 한참 걸렸다. 화면이 켜지자 등 뒤가 비었다. 목덜미에 털 하나가 붙어 있었다. 노란 털이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-17, spirit:-24 } },
    { l:'③ 화면을 안 보고 귀로 센다.', k:'sense', dc:22,
      ok:`눈을 감았다. 스피커마다 같은 노래가 반 박자씩 늦다. 돌림노래처럼.<br><br>노래 끝 박자를 셌다. 마지막 스피커까지 다 끝나면 조용한 틈이 다섯 박자 있다. 그 틈에 방을 나왔다.<br>복도는 조용했다. 등 뒤에서 노래가 처음부터 다시 시작됐다.`,
      ng:`세는데 노래 하나가 박자를 어긴다. 이쪽 귀 바로 옆에서 부른다. 녹음이 아니다.<br><br>눈을 떴다. 아무도 없다. 노래는 계속 귀 옆에서 난다. 방을 나와도 따라온다.<br>한 층을 내려가서야 멀어졌다. 그 뒤로 한참 그 노래가 입안에서 맴돌았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'A1', t:'매점 — 뽑기 기계',
  x:`매점 구석에 뽑기 기계가 있다. 동그란 통 안에 캡슐이 가득하다.<br><br>
    투입구 옆에 동전 한 닢이 놓여 있다. 먼저 온 아이가 두고 간 것처럼.<br>
    캡슐은 색이 셋이다. 노랑, 파랑, 빨강. 빨강은 셋뿐이다. 맨 아래, 나오는 구멍 바로 위에 몰려 있다.<br><br>
    뽑기라면 안다. 귀한 것은 위에 보이게 두고, 흔한 것을 나오는 데 둔다. 여긴 거꾸로다.`,
  o:[
    { l:'① 손잡이를 반 바퀴만 돌린다.', k:'luck', dc:22,
      ok:`한 바퀴 돌리면 맨 아래 것이 나온다. 반 바퀴만 돌리면 통이 흔들려 순서가 섞인다.<br><br>반 바퀴 돌리고 멈췄다. 빨강이 위로 밀려 올라가고 노랑 하나가 구멍으로 떨어졌다. 열어 보니 꿀을 굳힌 사탕 한 줌이다.<br>통 안에서 빨강 셋이 다시 아래로 굴러 내려온다. 천천히. 저 혼자.`,
      ng:`반 바퀴 돌렸는데 손잡이가 저절로 마저 돈다. 빨강이 떨어졌다.<br><br>캡슐이 바닥에서 저절로 열린다. 안에 도장이 들어 있다. 웃는 해. 손등에 찍혀 있다. 찍은 기억 없이.<br>문질러도 안 지워진다. 도장 찍힌 손등이 그 뒤로 내내 따뜻했다. 누가 잡고 있는 것처럼.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ mind:-15, spirit:-22 } },
    { l:'② 기계를 기울여 빨강 속을 본다.', k:'gaze', dc:23,
      ok:`기계를 기울여 빨강 캡슐을 유리에 붙였다. 등불을 댔다.<br><br>속이 비쳐 보인다. 접힌 종이다. 방청권이다. 오늘 날짜. 이름 칸이 비었다.<br>빨강 셋을 그대로 두고 기계 전원을 뽑았다. 통 안 불이 꺼진다. 빨강이 안 보인다. 안 보이면 아무도 안 뽑는다.`,
      ng:`기울이는데 유리 안쪽에서 무엇이 캡슐을 밀어 유리에 붙인다. 이쪽 얼굴 높이로.<br><br>빨강 캡슐 안 종이에 이쪽 이름이 적혀 있다. 크레용 글씨다.<br>기계를 놓쳤다. 넘어지는 기계에 정강이를 찍혔다. 유리에 금이 갔는데 캡슐은 하나도 안 쏟아졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'A1', t:'스튜디오 — 빨간 불 셋',
  x:`스튜디오에 카메라 세 대가 있다. 사람은 없다. 카메라 위 빨간 불이 하나씩 돌아가며 켜진다.<br><br>
    불이 켜진 카메라가 지금 방송에 나가는 눈이다. 그 앞에 서면 무대에 선 것이다.<br>
    세 대 사이를 지나야 문이 있다. 불은 왼쪽, 가운데, 오른쪽, 다시 가운데.<br><br>
    노름꾼은 야바위를 안다. 컵 셋에 콩 하나. 손이 눈보다 빠르면 콩은 늘 없는 데 있다.`,
  o:[
    { l:'① 불이 옮겨 가는 손을 읽는다.', k:'luck', dc:23, wake:1,
      ok:`빨간 불만 보지 않았다. 불이 꺼지기 직전 다음 카메라 렌즈가 아주 조금 돌아간다. 콩을 옮기기 전 컵이 들썩이는 것과 같다.<br><br>렌즈가 들썩이는 쪽 반대로만 디뎠다. 왼쪽, 오른쪽, 멈춤, 가운데. 한 번도 빨간 불 앞에 서지 않았다.<br>문에 닿았다. 등 뒤에서 세 카메라가 동시에 이쪽을 향했다. 늦었다.<br><br>야바위꾼 손을 읽던 눈이 기계 손도 읽는다. 판을 돌리는 것이 무엇이든 돌리기 직전의 들썩임은 같다.`,
      ng:`렌즈를 보는데 셋이 한꺼번에 들썩인다. 컵 셋을 동시에 드는 판이다.<br><br>멈칫한 사이 빨간 불이 이쪽 앞 카메라에 켜졌다. 스피커에서 박수가 터진다. 발밑 무대 조명이 켜진다.<br>바닥에 엎드려 조명 밖까지 기었다. 팔꿈치가 다 까졌다. 박수가 끝날 때까지 엎드려 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16, spirit:-16 } },
    { l:'② 방금 불이 꺼진 카메라 앞에 선다.', k:'luck', dc:24,
      doom:{ title:'라이브', what:'회전 무대에 실려 카메라 앞으로 끌려 나갑니다', dc:19, sec:45,
        text:`불이 방금 꺼진 카메라 앞으로 갔다. 방금 비운 컵에는 콩이 없다. 늘 그랬다.<br><br>렌즈가 돌아온다. 빨간 불이 다시 켜진다. 같은 카메라에. 야바위꾼이 제일 좋아하는 수다. 같은 컵에 두 번.<br>스피커에서 언니 목소리가 난다. 오늘의 친구가 나왔어요. 조명이 쏟아진다. 발밑 바닥이 앞으로 미끄러진다. 회전 무대다. 한가운데로 실려 간다.<br><br>같은 컵에 두 번 넣는 손을 수없이 잡아냈다. 오늘은 못 잡았다.`,
        dieText:`방송 중 등이 켜진 채 그대로다.<br><br>카메라 세 대가 무대 한가운데를 본다. 의자가 하나 놓였다. 누가 앉아 손을 흔든다. 박자가 맞다.<br>빨간 불은 다시 하나씩 돌아가며 켜진다. 왼쪽, 가운데, 오른쪽.` },
      ok:`방금 꺼진 카메라 앞으로 갔다. 그리고 바로 한 걸음 옆으로 비켰다.<br><br>렌즈가 돌아오며 빨간 불이 같은 자리에 다시 켜진다. 같은 컵에 두 번. 이쪽은 이미 그 앞에 없다.<br>조명이 빈자리를 비춘다. 스피커가 어, 하고 끊겼다. 그 틈에 문을 열고 나갔다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 카메라 선을 한데 꼬아 놓는다.', k:'break', dc:22,
      ok:`바닥의 굵은 선 셋을 끌어 모아 발로 꼬았다.<br><br>빨간 불이 셋 다 켜졌다가 셋 다 꺼진다. 어느 컵에도 콩이 없다. 판이 깨졌다.<br>어두운 스튜디오를 가로질렀다. 렌즈 셋이 다 허공을 본다.`,
      ng:`꼬는데 선이 손목에 감긴다. 선이 당겨진다. 카메라 쪽으로.<br><br>선을 풀며 뒤로 버텼다. 카메라 한 대가 쓰러지며 정강이를 쳤다. 렌즈가 깨졌다.<br>깨진 렌즈 너머에서 무엇이 눈을 깜빡였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'A2', t:'기숙사 — 침대 밑 판',
  x:`기숙사 침대 밑을 들여다봤다. 물이 침대 다리 반까지 찼다.<br><br>
    물속 마룻바닥에 판이 벌어져 있다. 공깃돌, 딱지, 구슬. 아이들이 사감 몰래 하던 판이다.<br>
    판돈은 명찰이다. 판 가운데 명찰이 수북하다. 물에 불어 글씨가 번졌다.<br><br>
    옆 침대 밑에서 하얀 손이 공깃돌을 집는다. 이쪽 차례를 기다린다.`,
  o:[
    { l:'① 한 판 하고 바로 엎는다.', k:'luck', dc:23,
      doom:{ title:'침대 밑 판', what:'침대 밑 물속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`공깃돌을 집었다. 물속이라 돌이 느리게 뜬다. 다섯 알을 다 받았다. 이겼다.<br><br>하얀 손이 명찰 하나를 밀어 준다. 이쪽 이름이다. 학년과 반이 적혀 있다. 이 학교에 다닌 적이 없는데.<br>명찰을 쥐자 손목을 잡힌다. 판을 딴 아이는 다음 판에도 앉아야 한다. 침대 밑으로 당긴다. 몸이 납작하게 밀려 들어간다. 물이 귀를 막는다.<br><br>딴 판에서 일어서는 법은 안다. 이 판은 일어설 자리가 없다. 위가 침대다.`,
        dieText:`침대 밑 판이 한 바퀴 돈다.<br><br>공깃돌이 물속에서 느리게 뜬다. 손이 하나 늘었다. 아직 서툴러 돌을 자꾸 놓친다.<br>판돈 명찰 하나에 이름이 새로 수놓였다.` },
      ok:`다섯 알을 받았다. 이겼다. 하얀 손이 명찰 하나를 밀어 준다.<br><br>안 받았다. 대신 판을 손바닥으로 쓸어 엎었다. 공깃돌, 딱지, 명찰이 물속으로 흩어진다. 판이 엎어지면 딴 사람도 잃은 사람도 없다.<br>하얀 손이 흩어진 것을 주우러 더듬는다. 그 틈에 침대에서 떨어져 물 밖으로 머리를 들었다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 판 말고 판돈 쌓인 모양을 본다.', k:'gaze', dc:22, wake:1,
      ok:`명찰이 몇 장인지, 어느 침대 쪽으로 쌓였는지 봤다.<br><br>명찰이 제일 적게 쌓인 쪽 침대가 제일 오래 잃은 아이 자리다. 그 침대 밑 손은 이제 판에 안 낀다. 판돈이 없으니까. 그 침대 밑으로 지나 반대편 복도로 나왔다. 아무것도 따라오지 않았다.<br><br>판돈 쌓인 모양을 보면 누가 언제부터 지는지 보인다. 판 하나를 보면 그 판에 앉았던 사람 모두가 보이기 시작했다.`,
      ng:`명찰을 세는데 한 장씩 늘어난다. 물에 젖은 명찰이 떠올라 판돈 위에 얹힌다.<br><br>세다 숨이 모자랐다. 고개를 들다 침대 틀에 뒤통수를 찧었다. 물이 코로 들어갔다.<br>기침하는 동안 하얀 손이 이쪽 셔츠 단추 하나를 떼어 갔다. 판돈이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14, spirit:-16 } }
  ] },

{ at:'A2', t:'복도 — 빈 번호',
  x:`복도 스피커에서 점호가 시작된다. 사감 목소리다. 번호를 부른다.<br><br>
    일, 이, 삼. 물에 잠긴 복도 여기저기서 대답이 난다. 네. 네. 거품이 올라오며.<br>
    수라면 셀 줄 안다. 패 한 벌에서 몇 장이 나갔는지 늘 안다.<br><br>
    대답이 하나 빈다. 백사십칠. 사감이 그 번호를 다시 부른다. 백사십칠.`,
  o:[
    { l:'① 다들 한 번호를 기다리는 틈에 건넌다.', k:'luck', dc:23,
      ok:`다들 백사십칠을 기다린다. 사감도, 물 밑 대답들도. 판 전체가 한 장을 기다릴 때 나머지 패는 아무도 안 본다.<br><br>그 틈에 복도를 건넜다. 물 가르는 소리를 부르는 소리 사이에 숨겼다. 백사십칠. 백사십칠. 세 번째 부를 때 계단에 닿았다.<br>등 뒤에서 대답이 났다. 네. 아주 작게. 늦게.`,
      ng:`건너는데 세 번째 부르기 전에 대답이 난다. 네. 이쪽 바로 옆 물속에서.<br><br>점호가 다시 흘러간다. 백사십팔. 판이 다시 움직인다. 이쪽은 복도 한가운데 서 있다.<br>입을 꼭 다물고 물속에 쪼그려 숨을 참았다. 숨이 끝날 때쯤에야 번호가 계단 쪽으로 멀어졌다. 폐가 타는 것 같았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-16, spirit:-18 } },
    { l:'② 물속에 쪼그려 점호가 끝나길 기다린다.', k:'steady', dc:22,
      ok:`숨을 크게 쉬고 물속에 쪼그렸다. 번호가 물 위로 지나간다. 물속에서 들으면 멀다.<br><br>숨이 차오를 때마다 코끝만 내밀었다. 대답 사이, 거품 사이에.<br>마지막 번호가 불렸다. 이백십이. 네. 스피커가 꺼졌다. 다들 물에서 일어섰다. 손끝이 다 쭈글쭈글했다.`,
      ng:`쪼그렸는데 옆에 누가 같이 쪼그려 있다. 물속에서. 교복을 입었다.<br><br>그 아이가 이쪽 귀에 번호 하나를 속삭인다. 거품으로. 이쪽에게 번호가 있다는 걸 처음 알았다.<br>물 밖으로 튀어 올랐다. 점호는 계속됐다. 그 번호에서 스피커가 아주 잠깐 멈췄다가 넘어갔다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-18 } }
  ] },

{ at:'A2', t:'식당 — 당번 제비',
  x:`배식대 위에 컵이 하나 놓여 있다. 젓가락이 열 개쯤 꽂혀 있다.<br><br>
    옆에 당번표가 붙었다. 저장고 당번 — 제비로 정함. 짧은 것을 뽑은 사람이 내려간다.<br>
    물이 가슴까지 찼다. 저장고는 물 밑 한 층 더 아래다.<br><br>
    젓가락 끝이 다 물에 잠겨 길이가 안 보인다. 컵 둘레에 젖은 손자국이 있다. 먼저 뽑은 손들이다.`,
  o:[
    { l:'① 손끝으로 길이를 훑고 뽑는다.', k:'luck', dc:22,
      ok:`컵을 쥐는 척하며 손가락 둘로 다발을 훑었다. 끝이 닿는 높이가 다르다.<br><br>제일 긴 것을 뽑았다. 짧은 것 하나가 컵 안에서 저 혼자 떠오른다. 누가 뽑아 간 것처럼. 배식대 밑 물속으로 내려간다.<br>당번은 정해졌다. 이쪽이 아니다. 배식대 위에 말린 고기 한 접시가 남아 있었다. 당번 아닌 아이 몫이다.`,
      ng:`훑는데 젓가락 하나가 손가락을 잡는다. 젓가락이 아니다. 손가락이다. 차고 가늘다.<br><br>뿌리치며 하나를 뽑았다. 짧다.<br>배식대 밑 물속에서 무엇이 발목을 톡톡 친다. 당번이 내려갈 차례라고. 뛰어서 식당을 나왔다. 발목에 손가락 자국이 다섯 줄 남았다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 컵째 엎는다.', k:'break', dc:22,
      ok:`컵을 쳐서 엎었다. 젓가락이 물 위로 흩어진다. 다 같은 길이로 떠 있다. 길이를 정한 건 젓가락이 아니라 컵 밑의 무엇이었다.<br><br>제비가 없으면 당번도 없다. 배식대 밑 물이 한참 일렁이다 잔잔해졌다.`,
      ng:`엎었는데 젓가락이 안 뜬다. 가라앉는다. 하나만 떠오른다. 짧은 것.<br><br>그 젓가락이 물살을 타고 이쪽 가슴께로 와서 셔츠 주머니에 꽂힌다.<br>뽑아 던졌다. 다시 떠온다. 세 번을 던지고서야 안 돌아왔다. 그동안 물이 턱까지 차올랐다가 내려갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14, spirit:-16 } },
    { l:'③ 뽑지 않고 물러난다.', k:'evade', dc:21,
      ok:`뽑지 않았다. 안 뽑은 사람은 판에 안 낀 사람이다.<br><br>배식대에서 뒷걸음질로 멀어졌다. 컵 안에서 젓가락 하나가 들썩였다. 뽑힐 사람을 찾다가 가라앉았다.`,
      ng:`물러나는데 당번표가 물결에 펄럭인다. 이름 칸 글씨가 번져 이쪽 이름이 된다.<br><br>뛰었다. 식당 문에서 물살이 이쪽을 안쪽으로 밀었다. 문틀을 잡고 한참 버텼다. 손바닥이 다 갈렸다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'A2', t:'교실 — 쪽지 시험',
  x:`책상마다 시험지가 한 장씩 놓였다. 물이 허리까지 찼는데 시험지는 젖지 않았다.<br><br>
    문제는 다섯, 보기는 넷. 문제 글씨가 물무늬처럼 흔들려 안 읽힌다. 보기 번호만 또렷하다.<br>
    칠판에 적혀 있다. 다 맞힌 학생만 하교. 틀린 학생은 남습니다.<br><br>
    교실 뒤 의자마다 젖은 교복이 앉아 있다. 남은 학생들이다.`,
  o:[
    { l:'① 문제 대신 낸 사람의 버릇을 찍는다.', k:'luck', dc:23, wake:1,
      ok:`문제를 안 읽었다. 교탁 위에 채점이 끝난 지난 시험지가 쌓여 있다. 답 번호가 늘 같은 버릇으로 돈다. 같은 번호가 셋 연달아 나오는 법이 없고, 넷째 칸은 꼭 둘째 칸을 피한다.<br><br>출제한 손의 버릇을 찍었다. 셋, 하나, 넷, 넷, 둘. 스피커에서 종이 짧게 울린다. 하교.<br>교실 뒤 젖은 교복들이 일제히 이쪽을 본다. 부러운 눈이다.<br><br>패를 몰라도 패를 섞은 손은 안다. 문제를 건너뛰어 문제를 낸 사람을 찍는 눈이 생겼다.`,
      ng:`버릇대로 찍었는데 넷째 답이 물에 번진다. 넷이 하나로 바뀐다. 쓴 적 없는 번호다.<br><br>종이 길게 울린다. 남습니다. 교실 뒤 의자 하나가 저 혼자 빠져나와 이쪽으로 밀려온다.<br>교실 문으로 기어 나왔다. 의자가 문턱까지 따라와 섰다. 한참 그 자리에서 이쪽을 기다렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 이름 칸을 지우고 나온다.', k:'hide', dc:22,
      ok:`시험지 이름 칸에 이미 이름이 적혀 있다. 이쪽 이름이다. 손톱으로 긁어 지웠다.<br><br>이름 없는 시험지는 채점이 안 된다. 채점이 안 되면 남을 사람도 없다.<br>나오며 돌아봤다. 이쪽 자리 시험지가 백지로 펄럭인다. 교실 뒤 교복들이 그 백지를 오래 본다.`,
      ng:`긁는데 안 지워진다. 수놓인 글씨다. 종이에 실로.<br><br>실을 뜯었다. 뜯을수록 셔츠 가슴께가 따끔하다. 거기에도 같은 실이 꿰매지고 있었다.<br>뜯는 것을 멈췄다. 따끔한 데가 오래 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A2', t:'자습실 — 동전 위 손가락',
  x:`자습실 책상 위에 종이가 펼쳐져 물에 떠 있다.<br><br>
    가운데 네, 아니요. 둘레에 숫자와 글자. 그 위에 동전 하나. 아이들이 몰래 하던 놀이다. 동전에 손가락을 얹고 물으면 동전이 대답한다.<br>
    동전 위에 이미 손가락 하나가 얹혀 있다. 하얗고 쭈글쭈글하다. 물에 오래 있던 손가락이다.<br><br>
    종이 귀퉁이에 규칙이 적혀 있다. 끝날 때까지 손가락을 떼지 마세요.`,
  o:[
    { l:'① 손가락을 얹고 미는 힘을 읽는다.', k:'luck', dc:23, wake:1,
      ok:`손가락을 얹었다. 물었다. 나가는 길이 어디냐고.<br><br>동전이 움직인다. 노름꾼은 판에서 남몰래 미는 손을 수없이 잡아냈다. 이 손도 민다. 미는 쪽이 늘 같다. 계단과 먼 쪽 글자로.<br>미는 힘을 거꾸로 읽었다. 동전이 멈춘 자리 맞은편 글자들이 길이 된다. 서쪽 계단. 마지막에 동전이 '안녕'에 섰다. 규칙대로 끝났다. 손가락을 뗐다.<br><br>속이는 손은 속이고 싶은 쪽을 가리킨다. 그걸 뒤집어 읽는 셈이 이제 손끝에 산다.`,
      ng:`얹고 물었다. 동전이 미끄러진다. 미는 힘이 너무 세서 읽을 틈이 없다.<br><br>동전이 숫자를 짚는다. 이쪽 나이. 이쪽 생일. 그리고 오늘 날짜. 손가락이 저려 오는데 뗄 수 없다. 아직 안 끝났다.<br>'안녕'에 설 때까지 한참 걸렸다. 손가락을 떼자 손끝이 하얗게 쭈글쭈글했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 손가락을 떼고 종이를 찢는다.', k:'break', dc:24,
      doom:{ title:'떼지 마세요', what:'손가락을 잡혀 물 밑으로 끌려갑니다', dc:19, sec:45,
        text:`손가락을 떼고 종이를 잡아 반으로 찢었다.<br><br>동전이 물 밑으로 가라앉는다. 하얀 손가락이 따라 내려간다. 그리고 다시 올라온다. 손가락 하나가 아니다. 손이다. 이쪽 검지를 쥔다.<br>끝나지 않았다는 것이다. 손이 당긴다. 책상 밑으로, 물 밑으로. 책상 다리에 이마를 찧으며 끌려 내려간다.<br><br>판을 엎을 때는 안다. 규칙이 판보다 질긴 데서는 엎으면 안 된다는 것도 알았어야 했다.`,
        dieText:`자습실 책상에 종이가 펼쳐져 있다. 찢긴 자리가 실로 꿰매졌다.<br><br>동전 위에 손가락이 둘 얹혀 있다. 하나는 아직 덜 쭈글쭈글하다.<br>귀퉁이 규칙은 그대로다. 끝날 때까지 손가락을 떼지 마세요.` },
      ok:`떼는 동시에 동전을 손바닥으로 덮었다. 다른 손으로 종이를 찢었다.<br><br>덮인 동전은 못 움직인다. 못 움직이면 판은 거기서 선다. 끝나지도 않고 이어지지도 않는다.<br>하얀 손가락이 손등을 한참 두드렸다. 손을 떼지 않고 동전째 쥐어 주머니에 넣었다. 주머니가 내내 차가웠다. 어쨌든 판은 이쪽 주머니 안에 있다.`,
      win:{ exp:22, dream:4 } }
  ] }

]);

// ==========================================
// 🎒 행상 (peddler) · 자원 없음
// ==========================================
kJob('peddler', 'A', [

{ at:'A', t:'입구 — 무거워진 보따리',
  x:`들어서자마자 보따리를 내려 다시 맸다. 버릇이다.<br><br>
    손이 먼저 안다. 쌀 때보다 무겁다. 한 근쯤.<br>
    넣은 것을 하나하나 떠올렸다. 물통, 말린 고기, 끈 타래, 바늘 쌈. 다 맞다. 그런데 한 근이 남는다.<br><br>
    보따리 매듭이 이쪽이 맨 매듭이 아니다. 비슷하다. 아주 비슷하다.`,
  o:[
    { l:'① 풀지 않고 무게로 짚어 남는 것을 찾는다.', k:'luck', dc:22, wake:1,
      ok:`보따리를 풀지 않았다. 바깥에서 손바닥으로 눌러 가며 무게를 짚었다. 물통, 말린 고기, 끈 타래. 바닥 귀퉁이에서 손이 멈춘다. 넣은 적 없는 무게다.<br><br>매듭을 조금만 풀고 손가락 둘로 집어냈다. 아이 신발 한 짝이다. 젖었다. 문턱 밖에 내려놓았다. 다시 매자 보따리가 한 근 가벼워졌다. 매듭은 이쪽 매듭으로 고쳐 맸다.<br><br>무게만으로 안에 든 것을 다 센다. 손바닥이 저울이 아니라 장부처럼 짐을 읽기 시작했다.`,
      ng:`바닥 귀퉁이를 짚는데 무게가 움직인다. 손바닥 밑에서 꿈틀.<br><br>보따리를 내던졌다. 매듭이 저절로 풀린다. 안에서 아무것도 안 나온다. 다시 들어 보니 무게가 맞다.<br>그 한 근이 어디로 갔는지 모른다. 등이 내내 무거웠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 다 풀어 냄새로 가린다.', k:'sense', dc:21,
      ok:`다 풀어 바닥에 늘어놓았다. 하나씩 집어 냄새를 맡았다. 다 이쪽 물건 냄새다. 하나만 물 냄새가 난다. 오래 고인 물.<br><br>젖은 천에 싸인 작고 단단한 것이다. 끝까지 펼쳐 보지 않았다. 그것만 두고 다시 쌌다.<br>보따리는 처음 무게로 돌아왔다.`,
      ng:`늘어놓는데 하나가 모자란다. 물통이다.<br><br>물통은 문턱 밖에 있었다. 둔 적 없는 자리다. 뚜껑이 열려 있고 반이 비었다. 누가 마셨다.<br>남은 물을 마시지 못하고 쏟아 버렸다. 목이 내내 탔다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'A', t:'복도 — 값을 받는 문틈',
  x:`복도를 막은 문에 우편 구멍 같은 틈이 나 있다.<br><br>
    틈으로 손 하나가 나와 있다. 손바닥을 위로 하고. 지나가려면 값을 치르라는 손이다. 장터에서 매일 보던 손짓이다.<br>
    틈 안쪽에서 목소리가 이쪽 물건 값을 하나씩 부른다. 보따리 속까지 다 안다.<br><br>
    끝으로 목소리가 이쪽 손 값을 부른다.`,
  o:[
    { l:'① 흥정한다.', k:'bond', dc:22,
      ok:`부르는 값을 다 듣고 아무 대꾸도 안 했다. 흥정은 먼저 입을 여는 쪽이 진다.<br><br>한참 뒤에 목소리가 값을 깎는다. 또 깎는다. 손 값은 슬그머니 빠졌다. 녹슨 바늘 한 쌈을 손바닥에 올렸다. 손이 거둬지고 문이 열렸다.<br>지나며 보니 틈 안쪽에 바늘 쌈이 수북하다. 같은 업이 여럿 다녀갔다.`,
      ng:`기다렸는데 목소리도 기다린다. 둘 다 입을 안 연다.<br><br>그사이 손이 틈에서 조금씩 나온다. 손목, 팔뚝. 점점 길게. 기다리는 동안 값이 오른다.<br>바늘 쌈을 던지듯 올리고 지나갔다. 팔뚝이 이쪽 어깨를 쓸었다. 쓸린 데가 오래 시렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-20 } },
    { l:'② 안 사고 돌아간다.', k:'steady', dc:21,
      ok:`보따리를 고쳐 메고 돌아섰다. 안 사는 것도 장사다.<br><br>목소리가 등 뒤에서 값을 낮춘다. 반값. 또 반. 끝내 공짜라고 한다. 공짜는 제일 비싸다. 돌아보지 않았다.<br>다른 길로 돌아가는 데 한나절이 걸렸다. 손은 둘 다 그대로다.`,
      ng:`돌아서는데 목소리가 이쪽 이름 값을 부른다. 걸음이 저절로 멈췄다.<br><br>제 이름이 얼마인지 끝까지 듣고 싶어진다. 장사하는 사람의 병이다. 일행이 팔을 잡아끌었다.<br>그 값이 귀에 오래 남았다. 생각보다 쌌다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-18, spirit:-16 } },
    { l:'③ 제일 값진 것을 내고 지난다.', k:'luck', dc:23,
      doom:{ title:'문틈 값', what:'문틈으로 팔을 잡혀 끌려 들어갑니다', dc:18, sec:50,
        text:`보따리에서 제일 값나가는 것을 꺼내 손바닥에 놓았다. 깎을 것 없이.<br><br>손이 그것을 쥔다. 쥔 채로 이쪽 손목도 쥔다. 값을 치른 손까지가 값이라는 듯이.<br>당긴다. 팔이 틈으로 들어간다. 팔꿈치, 어깨. 틈은 손바닥만 한데 끝이 없다. 얼굴이 문짝에 눌린다.<br><br>값을 안 깎는 손님이 제일 위험하다는 걸 행상은 안다. 이쪽이 그 손님이 됐다.`,
        dieText:`복도를 막은 문이 열려 있다. 아무도 안 지나간다.<br><br>틈 안쪽에 물건이 하나 늘었다. 제일 값나가는 것이 둘.<br>틈으로 손 하나가 나와 있다. 손바닥을 위로. 손목에 낯익은 소매가 감겨 있다.` },
      ok:`제일 값나가는 것을 손바닥에 놓자마자 손을 뺐다. 쥐기 전에.<br><br>손이 물건을 쥐고 잠깐 이쪽 손을 더듬는다. 허공이다. 문이 열렸다.<br>값은 비쌌다. 손 값보다는 쌌다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 저울',
  x:`쉬는 자리에서 먹을 것을 나눴다. 늘 작은 저울로 몫을 단다. 다툼은 저울 앞에서 사라진다.<br><br>
    한 몫씩 접시에 올렸다. 다 같다. 바늘이 같은 자리에 선다.<br>
    마지막 한 몫만 바늘이 안 움직인다. 말린 고기 두 줄이 접시에 얹혀 있는데 무게가 없다.<br><br>
    그 몫은 누가 보따리에 넣었는지 모른다. 제일 먹음직스럽다.`,
  o:[
    { l:'① 저울을 믿는다.', k:'luck', dc:22, wake:1,
      ok:`무게 없는 몫을 접시째 들어 멀리 던졌다. 어둠 속으로.<br><br>떨어지는 소리가 안 났다. 대신 무엇이 그것을 받아 무는 소리가 났다. 미끼였다. 먹은 사람을 데려갈.<br>남은 몫을 다시 나눴다. 다들 조금씩 덜 먹었다. 대신 다 먹었다.<br><br>눈은 속아도 저울은 안 속는다. 이제 저울 없이도 손이 무게 없는 것을 가려낸다.`,
      ng:`던지려는데 일행 하나가 이미 한 줄을 입에 넣었다.<br><br>씹는다. 맛이 없다고 한다. 씹을수록 얼굴이 하얘진다. 뱉게 했다. 뱉은 것이 바닥에서 꿈틀거렸다.<br>그 사람은 한동안 등불 쪽을 보지 못했다. 다들 남은 것을 반만 먹었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 저울을 치우고 눈대중으로 나눈다.', k:'fix', dc:21,
      ok:`저울을 치우고 손으로 다시 나눴다. 수상한 몫은 섞지 않고 따로 뒀다.<br><br>다들 눈으로 보고 고개를 끄덕였다. 저울보다 사람 눈이 다툼을 더 잘 막을 때도 있다.<br>떠날 때 보니 따로 둔 몫이 없어졌다. 바닥에 젖은 자국만 남았다.`,
      ng:`손으로 나누다 그 몫이 다른 몫에 섞였다. 어느 것인지 이제 모른다.<br><br>다들 제 몫을 들고 한참 망설였다. 결국 아무도 다 먹지 못했다.<br>배고픈 채로 일어섰다. 배고픈 것보다 의심이 더 무거웠다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A', t:'방 — 가격표',
  x:`방 안 물건마다 가격표가 붙어 있다. 의자, 등불, 거울, 의자에 걸친 외투들.<br><br>
    가격표를 보면 손이 먼저 간다. 뒤집어 봤다. 값이 아니라 날짜가 적혀 있다. 팔린 날이다.<br>
    외투가 의자에 앉은 모양으로 걸쳐져 있다. 속이 비었는데 어깨가 둥글다.<br><br>
    이쪽 소매 끝에도 가격표 하나가 달려 있다. 언제 달렸는지 모른다.`,
  o:[
    { l:'① 가격표를 읽는다.', k:'gaze', dc:22,
      ok:`소매 가격표를 뒤집었다. 날짜 칸이 비었다. 아직 안 팔렸다.<br><br>외투들 가격표는 다 날짜가 있다. 날짜가 오래된 외투일수록 어깨가 더 둥글다. 안에 무엇이 차오르는 중이다.<br>소매 가격표 날짜 칸에 줄 하나를 그었다. 장날에 안 파는 물건에 긋는 줄이다. 방을 나올 때 외투들이 어깨를 아주 조금 움츠렸다.`,
      ng:`뒤집었다. 날짜가 적혀 있다. 오늘이다. 글씨가 아직 젖었다.<br><br>의자 하나가 이쪽을 향해 돌아앉는다. 빈 외투가 일어서서 팔을 벌린다. 입혀 주려는 것이다.<br>가격표를 뜯어 던지고 뛰었다. 소매 끝이 찢어졌다. 찢긴 데가 차갑게 젖어 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 제일 오래된 외투 주머니를 턴다.', k:'luck', dc:23,
      ok:`날짜가 제일 오래된 외투 주머니에 손을 넣었다. 오래된 물건은 손님도 잊었다.<br><br>말린 약초 한 다발과 꿈결 몇 알이 나왔다. 외투는 움직이지 않았다. 어깨만 둥글다.<br>주머니를 털고 단추 하나를 채워 주었다. 장사하는 손은 남의 옷매무새를 그냥 못 본다.`,
      ng:`손을 넣었는데 주머니 안이 따뜻하다. 안쪽에서 손 하나가 이쪽 손을 쥔다.<br><br>빼냈다. 외투가 의자째 따라 넘어진다. 바닥에 엎어진 외투가 소매로 기어 온다.<br>문을 닫고 등으로 막았다. 문 너머에서 단추가 문짝을 긁었다. 오래.`,
      win:{ exp:18, dream:3, item:'약초 뭉치' }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A', t:'계단참 — 홑이불 쓴 좌판',
  x:`계단참에 좌판이 펼쳐져 있다. 돗자리 위에 물건이 가지런하다.<br><br>
    등잔 기름, 성냥, 끈, 소금, 아이 신발 몇 켤레. 주인은 좌판 뒤에 앉아 있다. 머리부터 홑이불을 썼다. 이불이 숨 쉬듯 오르내린다.<br>
    좌판 앞에 서면 저절로 쪼그려 앉게 된다. 손님 자리다.<br><br>
    홑이불 밑에서 손가락 하나가 나와 소금 덩이를 가리킨다. 그리고 이쪽 보따리를 가리킨다.`,
  o:[
    { l:'① 제일 싼 것을 귀하게 내민다.', k:'luck', dc:22, wake:1,
      ok:`보따리에서 녹슨 단추 하나를 꺼냈다. 두 손으로, 아주 귀한 것처럼. 천천히 돗자리에 내려놓았다.<br><br>손가락이 단추를 오래 만진다. 그러다 소금 덩이를 이쪽으로 민다. 덤으로 성냥 한 갑도.<br>일어서는데 홑이불이 고개 숙이듯 접힌다. 거래가 끝났다는 인사다.<br><br>물건 값은 물건이 아니라 내미는 손이 정한다. 그 손이 이제 손님이 무엇이든 같은 무게로 내민다.`,
      ng:`단추를 내려놓았는데 손가락이 단추를 튕겨 낸다. 값을 너무 낮게 봤다.<br><br>손가락이 다시 이쪽을 가리킨다. 보따리가 아니라 이쪽 눈을.<br>일어서서 물러났다. 홑이불이 이쪽 쪽으로 기운다. 계단을 다 내려갈 때까지 기울어 있었다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 제값을 치른다.', k:'bond', dc:21,
      ok:`여기서 소금이 얼마인지는 모르지만 장날 값은 안다. 그만큼을 보따리에서 골라 냈다. 끈 한 타래와 말린 고기 한 줄.<br><br>손가락이 끈만 가져가고 고기는 밀어 돌려준다. 제값보다 싸게 쳐 준 것이다.<br>제값을 치르는 손님은 어디서나 드물다. 드문 손님에게는 어디서나 덤이 붙는다.`,
      ng:`제값을 쳤는데 손가락이 더 달라고 한다. 또. 또.<br><br>보따리 반이 돗자리로 넘어갔다. 소금 한 덩이 값으로.<br>일어서는데 다리가 저렸다. 오래 쪼그려 있었다. 그만큼 오래 흥정에 진 것이다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-22, mind:-16 } },
    { l:'③ 홑이불이 졸 때 집어 간다.', k:'hide', dc:23,
      doom:{ title:'홑이불 좌판', what:'홑이불 밑으로 끌려 들어갑니다', dc:18, sec:50,
        text:`홑이불 오르내림이 느려졌다. 잠든 숨이다. 손을 뻗어 소금 덩이를 집었다.<br><br>오르내림이 멈췄다. 홑이불 자락이 손목 위로 덮인다. 가볍다. 그런데 안 걷힌다.<br>자락이 팔을 타고 어깨까지 덮는다. 이불 밑이 따뜻하다. 많은 손이 이쪽을 안으로 당긴다. 이불 밑이 좌판보다 넓다.<br><br>좌판에서 훔친 손님을 어떻게 하는지 행상은 안다. 다시는 손님으로 안 받는다. 물건으로 받는다.`,
        dieText:`계단참 좌판에 물건이 가지런하다.<br><br>등잔 기름, 성냥, 끈, 소금. 신발이 한 켤레 늘었다. 끈이 가지런히 묶였다.<br>홑이불이 숨 쉬듯 오르내린다. 조금 더 크게.` },
      ok:`오르내림이 느려졌을 때 집었다. 소금 덩이 대신 그 옆 성냥갑을. 덜 아까운 것을.<br><br>홑이불은 오르내리기를 멈추지 않는다. 덜 아까운 것은 주인도 덜 센다.<br>성냥갑은 반이 찼다. 계단을 내려가며 하나를 그어 불을 켰다. 그 불빛으로 좌판 쪽은 돌아보지 않았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'밤 — 파장 뒤의 손님',
  x:`쉬는 자리에서 보따리를 베고 누웠다. 밤에도 짐은 놓지 않는다.<br><br>
    똑똑. 보따리 옆 바닥을 무엇이 두드린다. 파장 무렵 늦은 손님이 좌판을 두드리던 소리와 같다.<br>
    눈을 뜨지 않았다. 축축한 손이 보따리 끈을 만진다. 동전 소리가 난다. 젖은 동전.<br><br>
    사겠다는 것이다. 무엇을 사려는지는 손이 가리키는 쪽으로 안다. 옆에서 자는 일행 쪽이다.`,
  o:[
    { l:'① 파장했다고 한다.', k:'steady', dc:22, wake:1,
      ok:`눈을 감은 채 말했다. "파장이오."<br><br>장사는 문을 닫으면 끝이다. 문 닫은 가게에 손님은 없다. 평생 지켜 온 규칙이다. 축축한 손이 한참 끈 위에 머문다. 그러다 동전 소리를 거두어 간다.<br>아침에 보니 보따리 옆에 젖은 손자국이 줄지어 있었다. 문밖에서 기다린 줄이다.<br><br>팔지 않는 때를 정해 두는 것. 그 하나가 장사의 뼈가 됐다. 이제 그 한마디에 무게가 실린다.`,
      ng:`"파장이오." 말했는데 손이 동전을 더 꺼낸다. 값을 올린다.<br><br>동전이 손바닥에 쥐여진다. 차다. 펴면 거래가 안 된 것이고, 쥐면 된 것이다. 펴지 못했다.<br>밤새 주먹을 쥔 채 버텼다. 아침에 펴니 동전은 없고 동그란 자국만 남았다. 옆 일행은 무사했다. 얼굴이 몹시 창백했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 안 파는 물건 대신 다른 것을 판다.', k:'luck', dc:23,
      ok:`일어나 앉아 보따리를 풀었다. "그건 안 파는 물건이오. 이건 어떻소."<br><br>낡은 등불 덮개를 내밀었다. 쓰임을 말하고 흠도 말했다. 흠까지 말하니 손이 믿는다. 산다. 젖은 동전 셋이 놓인다.<br>동전은 아침에 보니 꿈결이 되어 있었다. 손님이 무엇이든 셈은 맞게 치른다.`,
      ng:`내밀었는데 손이 고개를 젓듯 흔들린다. 끝내 일행 쪽을 가리킨다.<br><br>이것저것 꺼내 놓는 사이 그 일행이 잠결에 몸을 뒤척인다. 발목에 젖은 손자국이 감긴다. 흔들어 깨웠다.<br>자국은 아침까지 안 지워졌다.`,
      win:{ exp:18, dream:4 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'복도 끝 — 먼저 간 이의 짐',
  x:`복도 끝에 보따리 하나가 놓여 있다. 끈이 행상 매듭으로 묶였다. 같은 업이다.<br><br>
    주인은 없다. 끈 한쪽 고리가 벽 쪽으로 늘어져 어둠 속으로 들어간다. 무엇에 걸린 것처럼 팽팽하다.<br>
    보따리가 부풀어 있다. 좋은 물건이 많다는 건 겉만 봐도 안다.<br><br>
    끈을 만져 보니 따뜻하다. 방금 내려놓은 짐 같다.`,
  o:[
    { l:'① 길 값만큼만 덜어 간다.', k:'luck', dc:22,
      ok:`끈은 안 풀었다. 매듭 옆 틈으로 손을 넣어 한 줌만 덜었다. 같은 업의 짐에서 길 값만큼.<br><br>말린 고기 한 줄과 산나물 한 묶음. 그만큼 덜자 팽팽하던 끈이 조금 느슨해진다. 어둠 속에서 무엇이 한숨을 쉬었다.<br>짐은 주인이 다시 짊어질 무게로 남겨 두었다.`,
      ng:`손을 넣는데 끈이 당겨진다. 보따리가 어둠 쪽으로 한 뼘 끌려간다.<br><br>손이 보따리 속에서 안 빠진다. 같이 끌려갔다. 일행이 허리를 잡았다. 보따리를 놓자 그것만 어둠으로 들어갔다.<br>손등이 끈에 쓸려 시뻘겠다. 덜어 낸 것은 하나도 없었다.`,
      win:{ exp:18, dream:3, item:'산나물' }, lose:{ hp:-24, spirit:-18 } },
    { l:'② 짐째 짊어진다.', k:'steady', dc:23,
      doom:{ title:'남의 짐', what:'짐 끈에 묶여 어둠 속으로 실려 갑니다', dc:18, sec:50,
        text:`짐째 짊어졌다. 무겁다. 좋은 물건은 무겁다. 허리가 그 무게를 반긴다.<br><br>일어서는데 끈이 어깨를 조인다. 가슴을 감는다. 벽 쪽 고리가 팽팽해진다. 짐이 이쪽을 지고 간다. 어둠 쪽으로.<br>발이 끌린다. 같은 업이 지던 짐은 같은 업을 알아본다. 주인을 내려놓은 데로 데려간다.<br><br>어둠 속에 다른 보따리들이 보인다. 줄지어. 다 같은 매듭이다.`,
        dieText:`복도 끝에 보따리 하나가 놓여 있다. 끈이 행상 매듭으로 묶였다.<br><br>끈이 따뜻하다. 방금 내려놓은 짐 같다.<br>보따리가 조금 더 부풀어 있다.` },
      ok:`짐째 졌다. 끈이 어깨를 조이려는 순간 칼로 고리 쪽 끈을 끊었다.<br><br>팽팽하던 끈이 어둠 속으로 휙 빨려 들어간다. 짐은 이쪽 등에 남았다. 무겁다. 좋은 물건이다.<br>먼저 간 사람은 짐을 내려놓지 못하고 끌려갔다. 이쪽은 끈부터 끊었다. 같은 업이라도 끝은 다르다.`,
      win:{ exp:22, dream:4, item:'말린 고기' } }
  ] },

{ at:'A', t:'책상 — 외상 장부',
  x:`빈 책상 위에 장부가 펼쳐져 있다. 외상 장부다.<br><br>
    이름과 날짜와 값. 줄마다 빨간 줄이 그어졌다. 다 갚았다는 줄이다. 갚은 사람 이름 옆에는 손톱만 한 얼룩이 하나씩 있다.<br>
    맨 아래 줄에 이쪽 이름이 있다. 빨간 줄은 없다. 값이 적혀 있다.<br><br>
    외상은 제일 싫다. 받을 것도 줄 것도.`,
  o:[
    { l:'① 셈을 따진다.', k:'gaze', dc:22,
      ok:`이쪽 줄을 짚어 따라갔다. 무엇을 외상으로 받았는지 적혀 있다. 물 한 모금, 불빛 한 번, 계단 열세 칸. 여기까지 오며 쓴 것들이다.<br><br>값을 다시 더했다. 합이 틀렸다. 계단 칸 수를 하나 더 셌다. 장부는 늘 쓰는 쪽에 유리하게 틀린다.<br>틀린 데를 손톱으로 긋고 바른 값을 적었다. 바른 값은 이미 치른 만큼이었다. 빨간 줄은 이쪽이 그었다.`,
      ng:`따지는데 줄이 늘어난다. 지금 이 장부를 읽는 것도 외상이다. 등불 빛 한 번.<br><br>읽을수록 값이 오른다. 장부를 덮었다. 덮는 소리가 크다.<br>책상 밑에서 무엇이 그 소리를 들었다. 서랍이 저절로 한 칸 열렸다. 안을 안 보고 나왔다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 값을 치르고 줄을 긋는다.', k:'luck', dc:23,
      ok:`적힌 값만큼 보따리에서 골라 책상에 올렸다. 끈, 바늘, 녹슨 열쇠.<br><br>장부 위에 빨간 줄이 저절로 그어진다. 이름 옆에 얼룩은 안 생겼다. 값이 맞았다.<br>장부가 다음 장으로 넘어간다. 빈 장이다. 외상 없는 사람에게 장부는 할 말이 없다.`,
      ng:`올렸는데 빨간 줄이 안 그어진다. 값이 모자란다.<br><br>더 올렸다. 줄이 반만 그어진다. 이름 옆에 얼룩이 번지기 시작한다.<br>남은 것을 다 쏟고 뛰었다. 손등에 같은 얼룩이 생겼다. 손톱만 하게. 차갑다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'창고 — 봉한 상자들',
  x:`창고에 나무 상자가 쌓여 있다. 다 못을 쳐서 봉했다. 겉에 아무것도 안 적혀 있다.<br><br>
    상자는 열지 않고도 속을 짐작한다. 모서리를 들어 무게를 보고, 흔들어 소리를 본다.<br>
    하나는 소금 소리가 난다. 하나는 말린 생선 소리. 하나는 아무 소리도 안 난다. 무겁다.<br><br>
    소리 안 나는 상자에서 아주 작게 숨소리가 난다.`,
  o:[
    { l:'① 모서리를 들어 골라 연다.', k:'luck', dc:22,
      ok:`소금 소리 나는 상자를 골랐다. 못을 하나만 빼서 뚜껑을 반쯤 들었다.<br><br>소금 덩이가 기름종이에 싸여 있다. 젖지 않았다. 둘을 챙겼다.<br>숨소리 나는 상자는 건드리지 않았다. 나올 때 보니 그 상자 못 하나가 안쪽에서 조금 밀려 나와 있었다.`,
      ng:`소금 상자를 들려는데 소리가 바뀐다. 상자들이 서로 자리를 바꿨다. 들어 올린 것이 숨소리 나는 상자다.<br><br>못 사이로 손가락 하나가 나와 이쪽 엄지를 건드린다. 상자를 떨궜다. 발등에 떨어졌다.<br>상자 속에서 무엇이 웃었다. 숨소리보다 컸다.`,
      win:{ exp:18, dream:3, item:'소금 덩이' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 숨소리 나는 상자에 못을 더 친다.', k:'break', dc:22,
      ok:`바닥 못을 주워 숨소리 나는 상자 뚜껑에 더 쳤다. 넷. 다섯.<br><br>숨소리가 잦아든다. 안 팔리는 물건은 단단히 묶어 구석에 둔다.<br>다른 상자에서 말린 생선을 꺼냈다. 망치 소리에 다른 것들이 다 조용했다.`,
      ng:`치는데 안쪽에서 못을 밀어낸다. 친 만큼 다시 빠져나온다.<br><br>망치를 놓쳤다. 상자 틈이 손가락 하나만큼 벌어졌다. 그 틈으로 이쪽을 보는 눈이 있다. 오래 봤다.<br>뒷걸음질로 창고를 나왔다. 그 눈이 꿈에 나왔다.`,
      win:{ exp:16, dream:2, item:'민물고기' }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A', t:'내려가는 길 — 마지막 손님',
  x:`계단을 내려가는데 뒤에서 누가 부른다.<br><br>
    "여기요, 얼마예요." 아이 목소리다. 파장 무렵 꼭 하나씩 있는 마지막 손님.<br>
    마지막 손님을 그냥 보낸 적은 없다. 등 뒤에서 작은 손이 보따리 끝을 잡는다.<br><br>
    돌아보면 안 될 것 같다. 돌아보지 않으면 장사꾼이 아니다.`,
  o:[
    { l:'① 돌아보지 않고 덤을 건넨다.', k:'bond', dc:22, wake:1,
      ok:`돌아보지 않았다. 보따리 끝을 풀어 꿀 한 줌을 꺼내 등 뒤로 내밀었다.<br><br>"덤이다. 값은 안 받는다."<br>작은 손이 꿀을 받는다. 손바닥이 차다. 그런데 고맙다는 듯이 이쪽 손가락을 한 번 쥐었다 놓는다. 보따리를 잡은 손이 풀렸다.<br><br>얼굴을 안 보고도 손님을 대한다. 장사는 눈이 아니라 손으로 한다는 것을 그날 손이 배웠다.`,
      ng:`내밀었는데 작은 손이 꿀 말고 이쪽 손목을 잡는다.<br><br>덤이 아니라 파는 사람을 사려는 손님이다. 손목을 비틀어 뺐다. 계단을 뛰어 내려갔다.<br>계단 위에서 아이 목소리가 다시 묻는다. 얼마예요. 이번엔 더 작게.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 파장했다고 하고 내려간다.', k:'steady', dc:22,
      ok:`"오늘 장 끝났다." 걸음을 멈추지 않았다.<br><br>보따리 끝을 잡은 손이 한 칸, 두 칸 따라온다. 그러다 놓는다. 파장한 장꾼을 붙드는 손님은 없다.<br>아래층에 닿아서야 보따리 끝을 봤다. 젖은 손자국이 작게 남아 있었다.`,
      ng:`"끝났다." 말했는데 손이 놓지 않는다. 내려갈수록 보따리가 무거워진다. 손님이 매달렸다.<br><br>아래층에 닿았을 때 어깨가 빠질 것 같았다. 보따리를 내려 보니 아무것도 없다. 무게만 남아 있다.<br>무게는 한참 뒤에야 빠졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A1', t:'매점 — 스티커 계산대',
  x:`방송국 매점 계산대 앞에 섰다. 진열대에 과자와 사탕이 가득하다. 값이 스티커로 적혀 있다.<br><br>
    웃는 해 스티커 세 장. 별 스티커 다섯 장. 돈으로 사는 물건이 아니다. 착한 어린이가 모은 스티커로 산다.<br>
    계산대 뒤 커튼 밑으로 갈색 털 난 발이 보인다. 좀약 냄새가 난다.<br><br>
    계산대 앞에 서면 버릇처럼 값을 맞춰 본다. 스티커 한 장이 무엇과 같은 값인지.`,
  o:[
    { l:'① 이 가게 돈으로 값을 맞춰 치른다.', k:'luck', dc:22, wake:1,
      ok:`스티커는 없다. 대신 벽에 붙은 안내를 다 훑었다. 해 스티커 한 장 — 박수 한 번 잘 친 친구. 사탕 한 봉에 해 스티커 세 장.<br><br>값을 알면 치를 수 있다. 계산대 위 종을 두드리지 않고 손뼉을 세 번 쳤다. 조용히, 고르게. 커튼 밑 발이 움직이지 않는다. 계산대 위로 사탕 봉지 하나가 밀려 나온다. 꿀을 굳힌 사탕이다.<br><br>처음 보는 돈도 값을 매기면 셈이 된다. 어느 장터에서든 그 장터의 돈을 읽는 눈이 생겼다.`,
      ng:`손뼉을 세 번 쳤다. 너무 컸다. 커튼이 걷힌다.<br><br>갈색 털이 문틀을 채운다. 단추 눈 둘. 계산대 너머로 팔이 넘어온다. 안아 주려는 팔이다. 계산대 밑으로 몸을 던졌다.<br>팔이 한참 허공을 안았다. 좀약 냄새가 옷에 배어 며칠 안 빠졌다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ hp:-24, mind:-14, spirit:-16 } },
    { l:'② 물건 값만큼 보따리에서 놓고 간다.', k:'fix', dc:22,
      ok:`과자 한 봉을 집었다. 계산대 위에 끈 한 타래와 성냥 반 갑을 놓았다.<br><br>스티커는 아니지만 장사는 값이 맞으면 된다. 커튼 밑 발이 계산대 위 물건을 오래 본다. 그러다 돌아선다.<br>봉지를 열어 보니 말린 고기 조각이다. 아이 간식치고는 짰다.`,
      ng:`놓았는데 계산대 위 물건이 굴러 떨어진다. 저절로. 안 받는다는 뜻이다.<br><br>집은 과자를 도로 놓으려는데 손바닥에 붙어 안 떨어진다. 커튼 밑 발이 한 걸음 나온다.<br>봉지를 손에 붙인 채 뛰었다. 계단에서야 떨어졌다. 손바닥 살갗이 같이 벗겨졌다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 계산대 뒤 창고에서 몰래 꺼낸다.', k:'hide', dc:23,
      doom:{ title:'계산대 뒤', what:'뭉치에게 안겨 커튼 안으로 끌려갑니다', dc:18, sec:50,
        text:`계산대를 돌아 커튼 옆 창고 문을 열었다. 상자가 쌓여 있다. 손을 넣었다.<br><br>등 뒤에서 좀약 냄새가 확 끼친다. 커튼 걷히는 소리. 팔이 이쪽을 뒤에서 감싼다. 털이 얼굴을 덮는다. 단추 눈이 이쪽 어깨 너머로 창고를 들여다본다.<br>값 안 치른 손님은 안아서 데려간다. 발이 바닥에서 뜬다. 커튼 안쪽으로.<br><br>남의 가게 창고에 손을 넣어 본 적이 없다. 처음 넣은 데가 하필 여기다.`,
        dieText:`매점 계산대 위에 사탕 봉지가 가지런하다.<br><br>커튼 밑으로 큰 발 두 개가 보인다. 그 사이에 보따리 하나가 놓였다. 행상 매듭으로 묶였다.<br>진열대 값표 하나가 바뀌었다. 웃는 해 스티커 한 장.` },
      ok:`창고 상자에 손을 넣었다가 바로 뺐다. 손에 잡힌 것 하나만.<br><br>좀약 냄새가 다가왔을 때는 이미 계산대 밖이다. 커튼이 걷히고 털 난 팔이 창고를 안는다. 빈 데를.<br>쥔 것은 말린 버섯 한 봉지다. 매점에서 팔기엔 어른 간식이다.`,
      win:{ exp:22, dream:3, item:'야생 버섯' } }
  ] },

{ at:'A1', t:'휴게실 — 광고 시간',
  x:`직원 휴게실 텔레비전에서 광고가 나온다. 방글이 과자 광고다.<br><br>
    지금 전화 주시면 선물이 두 배! 화면 밑으로 번호가 지나간다. 벽에 전화기가 걸려 있다.<br>
    광고는 안다. 두 배라고 말할 때는 반값도 안 되는 물건이다. 서두르게 하는 장사는 늘 뒤가 있다.<br><br>
    전화기가 울린다. 아직 아무 번호도 안 눌렀는데.`,
  o:[
    { l:'① 받지 않는다.', k:'steady', dc:22,
      ok:`울리게 뒀다. 먼저 걸려 온 전화는 받지 않는다. 받으면 저쪽 장사다.<br><br>열두 번 울리고 끊겼다. 광고가 처음으로 다른 말을 한다. 아쉬워요. 그리고 다음 광고로 넘어갔다.<br>전화기 밑 서랍에 과자 봉지 몇 개가 그대로 있다. 광고 견본품이다. 꿀 사탕이 들었다.`,
      ng:`울리게 두는데 일행 하나가 버릇처럼 수화기를 든다.<br><br>수화기 너머에서 아이들이 한꺼번에 대답한다. 네에—. 빼앗아 걸었다. 그 일행 귀에서 한동안 박수 소리가 났다고 한다.<br>텔레비전 속 해 얼굴이 이쪽을 보고 웃었다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ mind:-18, spirit:-20 } },
    { l:'② 전화선을 따라 견본품 창고를 찾는다.', k:'sense', dc:22,
      ok:`전화선이 벽을 타고 옆방으로 간다. 광고를 찍은 방이다.<br><br>선반에 견본품 상자가 있다. 하나씩 흔들어 보고 속이 찬 것만 골랐다. 반은 빈 상자다. 광고용은 원래 속이 비었다.<br>찬 것 가운데 말린 버섯 봉지가 있었다. 광고에는 안 나온 물건이다. 팔 데 없는 물건이 제일 정직하다.`,
      ng:`선을 따라가는데 선이 바닥 틈으로 내려간다.<br><br>틈에 귀를 대니 전화벨이 울린다. 아래층 어딘가에서. 수화기 드는 소리. 이쪽 목소리로, 여보세요.<br>귀를 떼고 한참 앉아 있었다. 어느 층에서 받았는지 끝내 몰랐다.`,
      win:{ exp:18, dream:3, item:'야생 버섯' }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A1', t:'소품실 — 진짜 같은 음식',
  x:`소품 선반에 음식이 차려져 있다. 요리 코너에서 쓰던 것이다.<br><br>
    빵, 과일, 구운 고기, 생선. 하나같이 먹음직스럽다. 거의 다 칠한 나무와 굳힌 밀랍이다.<br>
    장터에서 가짜 고기를 파는 사람을 여럿 봤다. 손바닥에 올려 보면 안다.<br><br>
    선반 맨 끝 접시만 냄새가 난다. 진짜 냄새. 접시 옆 의자에 방글이 인형탈이 앉아 있다. 숟가락을 들고.`,
  o:[
    { l:'① 손바닥 무게로 진짜를 가린다.', k:'gaze', dc:22, wake:1,
      ok:`하나씩 손바닥에 올렸다. 나무는 가볍고 밀랍은 차다. 진짜는 무겁고 미지근하다.<br><br>맨 끝 접시까지 갈 것 없었다. 가운데 생선 접시 밑에 진짜가 깔려 있었다. 말린 고기 꾸러미다. 소품 담당이 숨겨 둔 도시락이다.<br>맨 끝 접시는 안 건드렸다. 인형탈이 숟가락을 든 채 고개만 이쪽을 따라 돌렸다.<br><br>눈에 보이는 것 말고 무게로 물건을 안다. 그 손이 이제 가짜 사이에서 진짜를 먼저 찾아간다.`,
      ng:`올리는데 밀랍 사과가 미지근하다. 진짜인가 싶어 쥐었다. 물렁하다.<br><br>사과가 손 안에서 꿈틀한다. 던졌다. 사과가 굴러 인형탈 발밑으로 간다. 인형탈이 숟가락으로 그걸 떠서 그려 넣은 입에 넣는다.<br>이쪽을 보고 맛있다는 듯 고개를 끄덕였다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ mind:-17, spirit:-24 } },
    { l:'② 냄새 나는 접시를 집는다.', k:'luck', dc:23,
      ok:`인형탈이 숟가락을 입으로 가져가는 사이 접시를 집었다. 진짜 구운 고기다. 아직 미지근하다.<br><br>인형탈 숟가락이 빈 접시 자리를 긁는다. 소리가 길다. 긁고 또 긁는다.<br>짐승 고기다. 누가 언제 구웠는지 모른다. 아마 괜찮다.`,
      ng:`집는데 인형탈 손이 접시 가장자리를 잡는다. 장갑 손가락 넷.<br><br>둘이 접시를 당겼다. 고기가 바닥에 떨어진다. 인형탈이 이쪽 손목을 놓지 않는다. 숟가락이 손등을 두드린다. 남의 밥을 탐하지 말라고.<br>빼냈다. 손등이 붉게 부었다. 숟가락 모양으로.`,
      win:{ exp:18, dream:3, item:'짐승 고기' }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A1', t:'방청석 — 경품 추첨권',
  x:`방청석 의자마다 등받이에 추첨권이 꽂혀 있다. 반쪽은 의자에, 반쪽은 손님이 가진다.<br><br>
    이쪽 의자에도 꽂혀 있다. 칠십칠 번. 무대 화면에 적혀 있다. 오늘의 행운 번호를 뽑아요. 당첨된 친구는 무대로!<br>
    빈 의자들 추첨권은 반쪽이 이미 뜯겼다. 누가 가져갔다.<br><br>
    표 장사를 해 본 적이 있다. 표는 바꿔 쥐면 주인이 바뀐다.`,
  o:[
    { l:'① 빈 의자 표와 바꿔 쥔다.', k:'luck', dc:23,
      doom:{ title:'행운 번호', what:'당첨되어 무대로 실려 나갑니다', dc:18, sec:50,
        text:`이쪽 표를 빈 의자에 꽂고 빈 의자 표 반쪽을 뽑아 쥐었다. 십이 번.<br><br>스피커에서 북소리가 울린다. 화면에 번호가 뜬다. 십이. 박수가 쏟아진다.<br>빈 의자들 사이에서 작은 손들이 이쪽을 받친다. 표 쥔 손을 높이 들어 올린다. 당첨자는 표를 쥔 사람이다. 앞으로, 앞으로. 손에서 손으로 무대 쪽으로 실려 간다.<br><br>표는 바꿔 쥐면 주인이 바뀐다. 바꿔 쥔 표가 이미 뽑히기로 된 표였다.`,
        dieText:`무대 위에서 박수가 끝났다.<br><br>칠십칠 번 의자에 추첨권 반쪽이 꽂혀 있다. 십이 번 의자는 비었다.<br>화면에 다음 회차 행운 번호가 미리 떠 있다. 칠십칠.` },
      ok:`이쪽 표와 빈 의자 표를 바꿔 쥐었다. 그리고 다른 빈 의자 표와 또 바꿨다. 또. 또.<br><br>표가 손에서 손으로 돌았다. 장날 표 장사꾼처럼. 북소리가 울리고 번호가 뜬다. 박수가 쏟아진다. 뽑힌 번호의 반쪽은 이제 아무 의자에도, 이쪽 손에도 없다.<br>박수가 허공에서 한참 맴돌다 그쳤다. 쥔 표를 다 의자에 도로 꽂고 나왔다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 표를 찢어 의자 밑에 버린다.', k:'steady', dc:22,
      ok:`표 반쪽을 잘게 찢어 의자 밑에 버렸다. 표가 없으면 손님이 아니다.<br><br>북소리. 번호. 칠십칠. 박수가 터진다. 아무도 일어나지 않는다. 칠십칠 번은 찢긴 표만 남은 빈 의자다.<br>화면이 칠십칠을 오래 띄워 둔다. 아무도 안 나오자 다음 번호를 뽑았다.`,
      ng:`찢는데 안 찢어진다. 표가 질기다. 손톱으로 뜯는 사이 북소리가 울린다.<br><br>칠십칠. 뜯다 만 표가 손바닥에 붙어 있다. 엉덩이가 의자에서 들린다. 팔걸이를 붙잡고 버텼다.<br>번호가 바뀔 때까지 손톱이 팔걸이를 파고들었다. 손톱 둘이 들렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A1', t:'대기실 — 출연료 봉투',
  x:`대기실 책상 위에 봉투가 줄지어 놓여 있다. 출연료 봉투다.<br><br>
    봉투마다 이름이 있다. 노래 언니, 방글이, 뭉치, 삐뚤이. 그리고 오늘의 친구. 맨 끝 봉투에 이쪽 이름이 적혀 있다. 두툼하다.<br>
    돈을 받으면 일을 해야 한다. 미리 받은 돈은 더 그렇다.<br><br>
    봉투 옆에 계약서가 한 장 놓여 있다. 서명 칸이 비었다.`,
  o:[
    { l:'① 봉투는 두고 받을 것 없다고 적는다.', k:'steady', dc:22, wake:1,
      ok:`봉투에 손대지 않았다. 계약서 뒷면에 적었다. "받을 것 없음." 그리고 날짜.<br><br>받을 것이 없다고 적은 사람에게 시킬 일은 없다. 안 받은 돈의 영수증을 쓸 줄 알아야 장사를 오래 한다. 계약서가 뒤집힌 채 조금 들썩이다 가라앉았다.<br>봉투들 가운데 이쪽 이름 봉투만 글씨가 흐려졌다.<br><br>받지 않은 값에도 문서를 남긴다. 셈을 이쪽 손으로 닫는 법이 몸에 붙었다.`,
      ng:`적으려는데 펜이 안 나온다. 꾹 눌러 쓰니 글씨가 앞면으로 배어 나온다. 서명 칸에.<br><br>이쪽 이름이 서명 칸에 박혔다. 스피커에서 언니 목소리가 난다. 오늘의 친구, 준비해 주세요.<br>계약서를 찢었다. 목소리가 잠깐 멈추고 다시 부른다. 대기실을 나오는 동안 세 번 더 불렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 봉투를 챙긴다.', k:'luck', dc:24,
      doom:{ title:'출연료', what:'선불 받은 출연자로 무대에 끌려 나갑니다', dc:19, sec:45,
        text:`봉투를 집었다. 두툼하다. 열어 보니 꿈결이 가득하다. 제값을 쳐 준 것이다.<br><br>스피커에서 언니 목소리가 난다. 오늘의 친구, 출연료 받았으면 무대로 오세요.<br>대기실 문이 열린다. 하얀 장갑 둘이 문틀을 잡고 기다린다. 봉투를 놓으려는데 손바닥에 붙어 안 떨어진다. 장갑이 팔꿈치를 쥔다. 무대 쪽으로 끈다.<br><br>미리 받은 돈이 제일 무겁다는 걸 행상은 안다. 몸이 그 무게로 끌려간다.`,
        dieText:`대기실 책상 위에 봉투가 줄지어 놓였다.<br><br>맨 끝 봉투가 비었다. 이름 칸 글씨가 무대 쪽으로 번져 있다.<br>그 옆에 새 봉투가 하나 놓였다. 이름 칸이 비었다. 두툼하다.` },
      ok:`봉투를 집자마자 계약서를 그 자리에 뒤집어 놓았다. 서명 칸이 바닥으로 가게.<br><br>서명 없는 돈은 품삯이 아니라 주운 돈이다. 스피커가 오늘의 친구를 부른다. 이쪽을 부르는 게 아니다. 서명한 사람이 없다.<br>봉투 속 꿈결을 보따리 맨 밑에 넣었다. 맨 밑에 넣은 돈은 쓰기 전에 한 번 더 생각한다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 다른 봉투들 이름을 읽는다.', k:'bond', dc:22,
      ok:`이름을 하나씩 읽었다. 이름 밑에 날짜가 있다. 받기로 한 날이다. 다 같다. 첫 방송 날이다.<br><br>그날 이후로 아무도 받지 못했다. 다들 아직 무대에 있다. 봉투를 하나씩 바르게 세워 놓았다. 받을 사람 쪽으로.<br>나오는데 스피커가 작게 지직거린다. 고맙다는 말 같았다. 아닐 수도 있다.`,
      ng:`읽는데 오늘의 친구 봉투가 여러 장이다. 이름이 다 다르다. 날짜도. 매일이다.<br><br>맨 앞장 이름을 읽다가 멈췄다. 아는 이름이다. 어디서 아는지 모른다.<br>그 이름이 하루 종일 혀끝에 붙어 있었다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'A2', t:'사감실 — 압수품 상자',
  x:`사감실 선반 위에 상자가 있다. 압수품이라고 적혀 있다.<br><br>
    아이들이 몰래 지니던 것들이다. 사탕, 말린 고기 꾸러미, 만화책, 손전등, 작은 라디오. 물건마다 이름표가 붙었다. 누구에게서 뺏은 것인지.<br>
    사감 책상 위 출석부가 펼쳐져 있다. 압수품 칸에 하나하나 적혀 있다.<br><br>
    이런 상자를 보면 손이 근질거린다. 주인 있는 물건과 주인 없는 물건이 섞였다.`,
  o:[
    { l:'① 이름표 없는 것만 꺼낸다.', k:'luck', dc:22, wake:1,
      ok:`이름표를 하나씩 봤다. 이름이 붙은 것은 주인이 아직 찾으러 온다. 출석부에 적힌 대로.<br><br>이름표가 떨어진 것이 둘 있다. 말린 고기 꾸러미와 꿀 사탕 한 봉. 출석부에도 없다. 주인이 이미 잊은 물건이다. 그 둘만 꺼냈다.<br>상자를 닫는데 상자 안 손전등이 저절로 켜졌다가 꺼졌다. 그건 두고 가라는 것 같았다.<br><br>주인 있는 것과 주인 없는 것을 손이 먼저 가른다. 그 셈이 이제 장부 없이도 맞는다.`,
      ng:`이름표가 떨어진 꾸러미를 집었다. 떨어진 게 아니라 뒤집혀 있었다. 이름이 적혀 있다.<br><br>출석부 압수품 칸에서 그 이름 줄이 저절로 지워진다. 돌려받았다는 표시다. 문밖에서 젖은 발소리가 다가온다. 받으러 온다.<br>꾸러미를 도로 넣고 창문으로 나왔다. 발소리가 사감실 안을 오래 돌았다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-14, spirit:-18 } },
    { l:'② 압수품 칸을 지우고 돌려준다.', k:'bond', dc:22,
      ok:`출석부 압수품 칸 이름들 옆에 줄을 그었다. 돌려줌.<br><br>물건들을 하나씩 창가 물 위에 띄웠다. 물건들이 저절로 흘러간다. 제 주인 침대 쪽으로.<br>상자 바닥에 이름표 없는 꿀 사탕 한 봉이 남았다. 주인 없는 물건은 돌려준 사람 몫이다.`,
      ng:`줄을 긋는데 책상 서랍이 열린다. 빨간 펜이 굴러 나와 이쪽 이름 옆에 무엇을 적는다. 벌점이다.<br><br>펜을 쳐냈다. 벌점 글씨가 번지며 반만 지워진다.<br>나올 때 사감실 문이 쾅 닫혔다. 손가락이 끼였다. 손톱이 검게 죽었다.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-18 } }
  ] },

{ at:'A2', t:'매점 — 젖은 동전',
  x:`매점 유리문이 반쯤 물에 잠겼다. 진열대 빵 봉지들이 물 위에 떠 있다.<br><br>
    계산대 앞 물속에서 작은 손 하나가 올라온다. 손바닥에 동전 두 닢. 젖었다. 다른 손이 빵 봉지 하나를 가리킨다.<br>
    계산대 뒤가 비었다. 주인이 없다. 손이 기다린다. 손님이 기다린다.<br><br>
    계산대 뒤에 서 본 적이 없다. 평생 땅바닥이 가게였다.`,
  o:[
    { l:'① 계산대 뒤에 서서 판다.', k:'bond', dc:22, wake:1,
      ok:`계산대 뒤로 돌아가 섰다. 빵 봉지를 손에 쥐여 주고 동전 두 닢을 받았다. 빵 값은 한 닢 반.<br><br>거스름돈 통에서 반 닢짜리를 찾아 손바닥에 놓아 주었다. 손이 거스름돈을 쥐고 내려간다. 거품이 고맙다고 올라온다.<br>다음 손이 올라온다. 또 다음 손. 줄을 섰다. 한참 팔았다. 마지막 손이 동전 대신 소금 한 덩이를 놓고 갔다.<br><br>손님이 누구든 셈은 같다. 처음으로 땅바닥 아닌 가게에 섰다. 계산대 높이만큼 장사가 넓어진 것 같았다.`,
      ng:`빵을 쥐여 주고 동전을 받았다. 거스름돈을 찾는데 통이 비었다.<br><br>손이 기다린다. 다른 손들도 올라온다. 거스름돈을 기다리는 손이 계산대를 에워싼다. 차가운 손가락들이 소매를 당긴다. 모자란 값을 달라고.<br>단추 한 줌을 뿌렸다. 손들이 줍는 사이 빠져나왔다. 소매가 다 젖어 무거웠다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' }, lose:{ hp:-22, mind:-14, spirit:-16 } },
    { l:'② 동전은 받지 않고 빵만 건넨다.', k:'fix', dc:21,
      ok:`동전 놓을 자리만 계산대 위에 손가락으로 짚어 보였다. 손이 거기 동전을 내려놓는다.<br><br>빵을 쥐여 줬다. 동전은 그대로 뒀다. 값은 치렀고 받은 사람은 없다. 장사가 아니라 셈만 맞았다.<br>손이 빵을 들고 내려간다. 계산대 위 동전 두 닢이 천천히 마른다.`,
      ng:`손이 동전을 놓지 않는다. 받아 줄 때까지 기다린다.<br><br>안 받았더니 계산대를 두드린다. 똑똑. 점점 세게. 물속 다른 손들이 따라 두드린다. 유리문이 흔들린다.<br>결국 받았다. 동전이 손바닥에서 녹아 물이 됐다. 손금마다 물이 고였다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'A2', t:'조리실 — 저장고 상자',
  x:`조리실 바닥 뚜껑 아래가 저장고다. 물이 가득 찼다.<br><br>
    물 밑에 상자들이 쌓여 있다. 겉 글씨가 물에 흔들려 보인다. 소금. 말린 생선. 건나물. 맨 밑 상자에는 글씨가 없다.<br>
    숨 한 번에 상자 하나다. 짐을 지고 숨을 참아 본 적은 없다. 무게는 안다.<br><br>
    맨 밑 상자 뚜껑이 손가락 하나만큼 열려 있다. 안에서 무엇이 이쪽을 올려다본다.`,
  o:[
    { l:'① 무게를 재고 한 번에 건진다.', k:'luck', dc:22,
      ok:`위에서 상자들이 물에 앉은 높이를 봤다. 가벼운 것은 덜 가라앉는다. 소금 상자는 무겁고 생선 상자는 가볍다. 소금이 더 귀하다. 숨 한 번이면 된다.<br><br>내려가 소금 상자 손잡이를 쥐고 차올랐다. 맨 밑 상자 쪽은 안 봤다.<br>뚜껑을 열자 소금 덩이가 기름종이에 싸여 말라 있다.`,
      ng:`소금 상자를 쥐었는데 생각보다 무겁다. 물속 무게를 잘못 쟀다.<br><br>차오르지 못하고 바닥에 발이 닿았다. 맨 밑 상자 옆이다. 열린 틈으로 손가락이 나와 발목을 더듬는다.<br>상자를 놓고 차올랐다. 숨이 터지기 직전이었다. 발목에 차가운 자국이 남았다.`,
      win:{ exp:18, dream:3, item:'소금 덩이' }, lose:{ hp:-26, mind:-16 } },
    { l:'② 끈에 고리를 달아 위에서 끌어올린다.', k:'fix', dc:22,
      ok:`보따리 끈 끝에 쇠고리를 매달아 내렸다. 생선 상자 손잡이에 걸고 당겼다.<br><br>상자가 천천히 올라온다. 물 밖에서 끄는 짐은 물속에서 지는 짐보다 가볍다. 평생 진 짐도 반은 끈이 졌다.<br>말린 생선을 챙겼다. 끈을 걷을 때 끈 끝에 젖은 손자국이 감겨 있었다.`,
      ng:`끈을 내렸는데 끈이 아래로 당겨진다. 무엇이 끝을 잡았다.<br><br>줄다리기가 됐다. 이쪽이 졌다. 끈이 손바닥을 훑고 내려갔다. 살갗이 벗겨졌다.<br>끈은 다시 안 올라왔다. 장꾼이 끈을 잃는 건 손 하나를 잃는 것과 같다.`,
      win:{ exp:18, dream:3, item:'민물고기' }, lose:{ hp:-24, spirit:-18 } },
    { l:'③ 맨 밑 상자를 들여다본다.', k:'gaze', dc:23,
      ok:`숨을 참고 내려가 맨 밑 상자 틈을 들여다봤다. 올려다보던 것은 눈이 아니다. 유리병 바닥이다. 병들이 줄지어 있다. 꿀이 담겼다.<br><br>저장고 맨 밑에 두는 것은 늘 제일 귀한 것이다. 한 병만 꺼냈다. 병 바닥이 물빛을 받아 눈처럼 반짝였다.<br>올라오는데 상자 뚜껑이 저절로 닫혔다.`,
      ng:`틈을 들여다봤다. 눈이 맞다. 진짜 눈이다. 상자 안이 상자보다 깊다.<br><br>뚜껑이 확 열리며 손이 나와 셔츠 깃을 잡는다. 셔츠가 찢기며 빠져나왔다.<br>물 밖에서 숨을 몰아쉬는데 찢긴 셔츠 조각이 끝내 떠오르지 않았다.`,
      win:{ exp:20, dream:3, item:'꿀 한 줌' }, lose:{ hp:-24, mind:-14, spirit:-18 } }
  ] },

{ at:'A2', t:'세탁실 — 마른 앞치마',
  x:`세탁실 빨랫줄에 교복이 줄줄이 걸려 있다. 물 위에. 다 젖었다.<br><br>
    아래층으로 내려가려면 먹을 것을 마르게 싸야 한다. 보따리 맨 밑 기름천으로는 이 물을 못 막는다.<br>
    빨랫줄 맨 끝에 한 장만 마른 천이 걸려 있다. 하얀 앞치마다. 물방울 하나 없다.<br><br>
    앞치마 끈이 묶여 있다. 누가 입고 있는 것처럼 둥글게.`,
  o:[
    { l:'① 앞치마를 걷어 짐을 싼다.', k:'luck', dc:22,
      ok:`끈을 풀지 않고 앞치마를 통째로 걷었다. 둥근 끈 안이 비었다. 다행이다.<br><br>먹을 것을 다 앞치마에 싸고 매듭을 지었다. 물에 담가 봤다. 안이 마른다. 이상한 천이다. 이상한 것이 쓸모 있을 때도 있다.<br>앞치마 주머니에 약초 한 다발이 들어 있었다. 조리실 아주머니 것이었을 것이다.`,
      ng:`걷는데 끈 안이 비어 있지 않다. 무엇이 입고 있다. 안 보인다. 천만 보인다.<br><br>앞치마가 손목을 감싸 쥔다. 천이 손가락이 된다. 놓으라고 했다. 흥정할 때처럼 침착하게. 한참 만에 천이 풀렸다.<br>손목에 주름 같은 자국이 오래 남았다.`,
      win:{ exp:18, dream:3, item:'약초 뭉치' }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 젖은 교복에서 촘촘한 천을 고른다.', k:'sense', dc:22,
      ok:`마른 천은 두고 젖은 교복을 하나씩 만졌다. 두꺼운 것, 촘촘한 것. 겨울 외투가 제일 촘촘하다.<br><br>외투 안감을 뜯어 짐을 싸고 겉감으로 한 번 더 쌌다. 두 겹이면 물이 늦게 든다.<br>외투 주머니에서 명찰이 나왔다. 도로 넣어 빨랫줄에 걸어 두었다. 뜯긴 외투가 고개 숙이듯 처졌다.`,
      ng:`고르는데 교복들이 한꺼번에 이쪽으로 돌아선다. 빨랫줄째.<br><br>소매들이 어깨에 얹힌다. 젖은 손처럼 무겁다. 하나씩 걷어 내며 빠져나왔다. 열두 벌이었다.<br>세탁실을 나오고서야 숨을 쉬었다. 어깨가 내내 젖어 있었다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A2', t:'보일러실 — 불 쬐는 값',
  x:`보일러실 화구에 불이 탄다. 물이 무릎까지 찼는데 꺼지지 않는다.<br><br>
    화구 앞에 화부가 쪼그려 앉아 있다. 작업복을 입었다. 얼굴이 불빛에 가려 안 보인다. 불을 쬐러 오라고 손짓한다.<br>
    물이 차다. 다들 이가 떨린다. 공짜 불은 없다.<br><br>
    화부가 화구 옆 판자에 분필로 적는다. 불 쬐는 값. 숫자는 아직 안 썼다.`,
  o:[
    { l:'① 값을 먼저 정하고 쬔다.', k:'bond', dc:22,
      ok:`불가에 앉기 전에 판자 앞에 섰다. 분필을 받아 적었다. 장작 세 개비. 그만큼만 쬐고 간다.<br><br>화부가 고개를 끄덕인다. 정한 값은 정한 값이다. 일행이 불가에 앉았다. 손발이 풀린다. 장작 세 개비가 다 타자 화부가 일어선다. 일행도 일어섰다.<br>먼저 정한 값은 나중에 오르지 않는다.`,
      ng:`적으려는데 분필이 물기에 녹는다. 숫자가 번진다. 셋이 여덟이 된다.<br><br>화부가 그 값을 받으러 일어선다. 일행 하나 손을 잡는다. 화구 쪽으로. 그 손을 떼어 내느라 다들 불가에서 물러났다.<br>언 몸이 더 굳었다.`,
      win:{ exp:18, dream:3, hp:8 }, lose:{ hp:-24, spirit:-20 } },
    { l:'② 값을 묻지 않고 쬔다.', k:'luck', dc:23,
      doom:{ title:'불 쬐는 값', what:'몸의 온기를 불 값으로 내주고 있습니다', dc:18, sec:50,
        text:`값을 안 묻고 불가에 손을 내밀었다. 따뜻하다. 아주 따뜻하다.<br><br>화부가 판자에 숫자를 쓴다. 쓰고 또 쓴다. 쬐는 만큼 값이 오른다. 불이 커질수록 손끝은 오히려 식는다. 불이 이쪽 온기를 먹고 탄다.<br>손을 거두려는데 손이 불 쪽으로 기운다. 아직 덜 받았다는 듯이. 판자 숫자가 끝없이 길어진다.<br><br>값을 안 묻는 손님이 결국 무엇을 치르는지 행상은 안다. 다 치른다.`,
        dieText:`보일러실 화구에 불이 탄다. 조금 더 밝게.<br><br>화구 앞에 둘이 쪼그려 앉아 있다. 하나는 작업복이 아니다.<br>판자에 분필로 적혀 있다. 불 쬐는 값. 다 받음.` },
      ok:`값을 안 묻고 손을 내밀었다. 대신 손바닥 하나만. 다른 손은 주머니에 넣었다.<br><br>판자에 숫자가 올라간다. 손바닥 하나 값이다. 데워지자 바로 거뒀다.<br>그 손으로 일행 손을 하나씩 잡아 주었다. 데운 손바닥 하나로 다 같이 녹였다. 값은 하나만 치렀다.`,
      win:{ exp:22, dream:4, hp:6 } }
  ] }

]);

// ==========================================
// 🔮 점술가 (fortune) · 마력
// ==========================================
kJob('fortune', 'A', [

{ at:'A', t:'입구 — 문 쪽을 가리키는 괘',
  x:`들어서기 전에 산가지를 던졌다. 문턱 넘기 전 한 괘. 버릇이고 일이다.<br><br>
    다섯 개가 바닥에 흩어진다. 다 같은 쪽을 가리킨다. 등 뒤, 들어온 문.<br>
    다시 던졌다. 또 문 쪽이다. 세 번째도.<br><br>
    괘가 돌아가라고 한다. 문은 이미 닫혔다. 이쪽에는 손잡이가 없다.`,
  o:[
    { l:'① 문이 아니라 문 둘레를 다시 읽는다.', k:'luck', dc:22, wake:1,
      ok:`산가지가 가리키는 끝을 따라 눈을 옮겼다. 문이 아니다. 문 옆 벽 밑, 바닥 틈이다. 거기서 바람이 든다. 괘는 늘 바람 드는 데를 가리킨다.<br><br>틈 옆에 물병 하나가 끼어 있었다. 앞서 들어온 누가 숨겨 둔 것이다. 마개가 성하다.<br>괘는 돌아가라고 한 게 아니다. 들어온 자리에 두고 간 것을 챙기라고 했다.<br><br>같은 괘가 세 번 나오면 겁부터 났었다. 이제는 괘에게 한 번 더 묻는 버릇이 손에 붙었다.`,
      ng:`다시 읽는데 산가지 하나가 저 혼자 굴러 문틈으로 들어간다.<br><br>손잡이 없는 문 너머에서 산가지 굴러가는 소리가 한참 났다. 멀어진다.<br>넷으로 던지는 괘는 하나가 빈다. 그 빈 하나가 계속 마음에 걸렸다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 마력을 실어 괘를 앞으로 세운다.', k:'gaze', dc:22, cost:{ mana:25 },
      ok:`산가지에 마력을 흘리고 던졌다. 다섯 개가 바닥에서 한 바퀴 돈다. 그리고 앞을 가리킨다. 억지로.<br><br>억지로 세운 괘도 괘다. 앞으로 걸었다. 막힌 데가 없었다.<br>다만 걷는 동안 등 뒤 문 쪽에서 산가지 넘어지는 소리가 계속 났다. 다시 문을 가리키는 소리다. 안 돌아봤다.`,
      ng:`마력을 흘리는데 산가지가 손바닥에서 뜨거워진다. 하나가 탄다.<br><br>타는 연기가 문 쪽으로 흘러가 문틈으로 빨려 들어간다. 문 너머에서 누가 그 연기를 들이마시는 소리가 났다.<br>마력만 쓰고 괘는 그대로였다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-15, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 다섯 걸음 앞',
  x:`어두운 복도 앞에서 눈을 감았다. 가끔 몇 걸음 앞이 먼저 보인다.<br><br>
    다섯 걸음이 보인다. 바닥, 벽, 문틀. 다섯째 걸음 자리에 누가 서 있다. 등을 보이고.<br>
    눈을 떴다. 아무도 없다. 다시 감았다. 서 있다. 아까보다 한 걸음 가깝다.<br><br>
    눈을 감을 때마다 가까워진다.`,
  o:[
    { l:'① 감은 눈으로 본 대로 비켜 걷는다.', k:'luck', dc:23, wake:1,
      ok:`눈을 감고 걸었다. 본 것을 따라. 넷째 걸음에서 왼쪽으로 크게 비켰다. 등을 보인 것의 어깨 옆을 지났다. 닿지 않았다.<br><br>여섯째, 일곱째. 감은 눈 앞에 이제 아무도 없다. 눈을 떴다. 복도 끝 계단이다.<br>뒤는 돌아보지 않았다. 감은 눈으로도.<br><br>앞을 보는 눈과 걷는 발이 처음으로 같은 박자로 움직였다. 몇 걸음 앞이 보이면 몸이 먼저 그 자리를 비킨다.`,
      ng:`걷는데 넷째 걸음에서 그것이 돌아선다. 얼굴이 이쪽을 본다. 감은 눈 안에서.<br><br>눈을 번쩍 떴다. 복도는 비었다. 다시 감을 수가 없다. 감으면 그 얼굴이 있다.<br>눈을 뜬 채 더듬어 걸었다. 모서리마다 부딪혔다. 이마와 무릎이 다 깨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16, spirit:-16 } },
    { l:'② 눈을 뜬 채 보이는 것만 믿고 간다.', k:'evade', dc:22,
      ok:`눈을 감지 않았다. 앞을 보는 재주는 쉬게 했다. 보이는 것만 믿고 걸었다.<br><br>감지 않으면 그것도 가까워지지 않는다. 복도는 그냥 복도다. 끝에서 계단을 찾았다.<br>보는 재주를 안 쓰는 것도 재주다.`,
      ng:`걷는데 눈이 시려 깜빡였다. 아주 잠깐.<br><br>그 잠깐에 그것이 코앞에 서 있는 게 보였다. 눈을 떴다. 없다.<br>뒷걸음질 치다 넘어졌다. 등을 바닥에 찧었다. 숨이 한참 안 쉬어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-18 } },
    { l:'③ 마력으로 본 것을 붙들어 얼굴을 본다.', k:'gaze', dc:23, cost:{ mana:28 },
      doom:{ title:'다섯째 걸음', what:'감은 눈 속의 것과 눈이 마주쳤습니다', dc:18, sec:50,
        text:`눈을 감고 마력을 실었다. 본 것을 오래 붙들어 두려고. 등을 보인 것이 또렷해진다.<br><br>그것이 돌아선다. 얼굴이 있다. 이쪽 얼굴이다. 눈만 다르다. 감겨 있다.<br>이쪽 눈이 안 떠진다. 그것의 눈이 대신 떠진다. 감은 눈 속에서 그것이 이쪽을 본다. 몸이 굳는다. 숨이 얕아진다.<br><br>남의 앞날을 보는 사람은 제 앞날과 눈을 맞추면 안 된다. 점술가가 제일 먼저 배우는 말이다.`,
        dieText:`복도 한가운데 누가 서 있다. 눈을 감고, 등을 보이고.<br><br>다섯 걸음 앞이다. 다음 사람이 눈을 감으면 보일 것이다.<br>눈을 뜨면 아무도 없다.` },
      ok:`마력을 실어 본 것을 붙들었다. 그것이 돌아서려 한다. 돌아서기 전에 눈을 떴다. 마력은 거두지 않았다.<br><br>뜬 눈 위에 감은 눈의 그림이 겹친다. 다섯째 걸음 바닥에 젖은 발자국 둘. 그것이 선 자리다. 그 자리만 피해 걸었다.<br>지나고 나서 마력을 거뒀다. 발자국이 바닥에서 지워졌다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'쉬는 자리 — 두 줄 생명선',
  x:`쉬는 자리에서 일행 하나가 손을 내민다. 봐 달라는 것이다. 겁이 나서.<br><br>
    손바닥을 등불에 비췄다. 생명선이 둘이다. 하나는 길고 하나는 짧다. 짧은 쪽이 오늘에서 끊긴다.<br>
    자세히 보니 짧은 선은 손금이 아니다. 손바닥에 눌린 자국이다. 손가락 자국.<br><br>
    누가 그 사람 손을 잡고 있다. 지금도.`,
  o:[
    { l:'① 말없이 자리를 바꿔 앉게 한다.', k:'bond', dc:22,
      ok:`아무 말 하지 않았다. 웃으며 손을 놓고 자리를 바꾸자고 했다. 등불 반대편, 벽을 등지게.<br><br>그 사람이 일어나자 앉았던 자리 바닥에 손바닥 자국이 남아 있었다. 젖은 손. 일행 누구 것도 아니다.<br>다시 손금을 봤다. 짧은 선이 옅어졌다. 생명선 하나만 남았다. 길다.`,
      ng:`바꾸자고 했는데 그 사람이 일어나지 못한다. 엉덩이가 바닥에 붙었다.<br><br>당겨 일으켰다. 일어나면서 그 사람이 비명을 삼킨다. 손바닥에서 무엇이 떨어져 나간다.<br>손바닥에 손톱자국 다섯 개가 남았다. 그 사람은 그 뒤로 늘 주먹을 쥐고 다녔다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 마력을 흘려 짧은 선을 걷어 낸다.', k:'luck', dc:23, wake:1, cost:{ mana:30 },
      ok:`손바닥에 손가락을 대고 마력을 흘렸다. 짧은 선을 따라 천천히 문질렀다.<br><br>손 밑에서 무엇이 버틴다. 차갑고 끈질기다. 문지를수록 손가락 자국이 옅어진다. 마지막 마디에서 툭 끊겼다. 등불이 한 번 흔들렸다.<br>그 사람 손바닥에 생명선 하나만 남았다. 손이 따뜻해졌다고 한다.<br><br>손금을 읽기만 하던 손이 처음으로 손금 위에 얹힌 것을 걷어 냈다. 읽는 일과 바꾸는 일 사이에 손가락 한 마디가 놓였다.`,
      ng:`문지르는데 짧은 선이 이쪽 손가락으로 옮겨 온다. 손가락에 자국이 감긴다.<br><br>손을 뗐다. 늦었다. 손가락 마디에 누가 꽉 쥔 자국이 생겼다. 차갑다.<br>밤새 그 손가락이 저렸다. 누가 계속 쥐고 있는 것처럼.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'방 — 기우는 촛불',
  x:`빈 방에 초를 켰다.<br><br>
    불꽃이 기운다. 바람이 없다. 문도 창도 닫혔다. 그런데 기운다. 한쪽으로, 길게.<br>
    촛불점을 치면 불꽃은 손님 쪽으로 기운다. 지금 불꽃은 일행 쪽이 아니라 방 구석으로 기운다.<br><br>
    구석에는 아무도 없다. 불꽃은 계속 그쪽으로 몸을 늘인다. 반가운 사람을 보는 것처럼.`,
  o:[
    { l:'① 불꽃 떨림으로 그것의 숨을 센다.', k:'luck', dc:22,
      ok:`불꽃 떨림을 셌다. 구석 쪽으로 기울 때마다 세 번 떨고 한 번 쉰다. 쉴 때 구석이 아주 조금 어두워진다.<br><br>그것도 숨을 쉰다. 셋 들이쉬고 하나 내쉰다. 내쉴 때는 이쪽을 못 본다. 그 박자에 맞춰 일행을 하나씩 문밖으로 내보냈다.<br>마지막으로 나오며 초를 껐다. 불꽃이 꺼지기 직전 구석 쪽으로 길게 뻗었다. 아쉬운 듯이.`,
      ng:`세는데 불꽃이 갑자기 이쪽으로 꺾인다. 이쪽 얼굴로.<br><br>구석의 것이 이쪽 뒤로 왔다. 불꽃은 그것을 따라간다. 목덜미가 차가워진다.<br>초를 쳐서 껐다. 어둠 속에서 목덜미에 숨이 한 번 닿고 사라졌다. 소름이 오래 가라앉지 않았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 두 손으로 불꽃을 감싼다.', k:'steady', dc:22,
      ok:`두 손으로 불꽃을 감쌌다. 손바닥이 뜨겁다. 불꽃이 손 안에서 곧게 선다. 기울 데가 없다.<br><br>불꽃이 아무 쪽도 안 가리키면 아무도 안 불린다. 감싼 채로 방을 나왔다. 손바닥이 데었다.<br>문을 닫으며 손을 폈다. 불꽃이 그제야 기울었다. 닫힌 문 쪽으로.`,
      ng:`감싸는데 불꽃이 손가락 사이로 빠져나가 구석 쪽으로 늘어진다.<br><br>손바닥만 데었다. 불꽃이 구석을 밝힌다. 아주 잠깐. 거기 누가 쪼그려 앉아 있었다. 무릎을 끌어안고.<br>초가 꺼졌다. 다시 켤 수 없었다. 손이 떨려서.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A', t:'계단 — 내려갈 시',
  x:`아래로 내려가는 계단 앞이다.<br><br>
    일행이 묻는다. 지금 내려가도 되느냐고. 언제 떠나고 언제 머물지, 그걸 받는 게 일이다.<br>
    여기는 해가 없다. 날이 없다. 시계는 멎었다.<br><br>
    대신 계단 아래에서 무엇이 올라오는 소리가 난다. 한 칸씩. 쉬었다가. 또 한 칸.`,
  o:[
    { l:'① 제 맥으로 시를 짚는다.', k:'luck', dc:22,
      ok:`제 손목을 쥐고 맥을 셌다. 해가 없으면 몸이 해다. 맥 백 번에 계단 소리 세 번. 사이가 일정하다.<br><br>세 번째 소리 다음에 긴 쉼이 있다. 올라오던 것이 숨을 고르는 틈이다. 그 틈이 내려갈 시다.<br>틈에 맞춰 일행을 내려보냈다. 계단 중간에서 아래쪽 소리와 엇갈렸다. 서로 닿지 않았다. 등 뒤 위쪽에서 소리가 다시 시작됐다.`,
      ng:`세는데 맥이 빨라진다. 겁이 나서. 몸이 해라면 오늘 해는 미쳤다.<br><br>시를 잘못 짚었다. 계단 중간에서 올라오던 것과 마주쳤다. 어둠 속에서 몸이 몸을 스쳤다. 차고 축축하다.<br>다들 벽에 붙어 굳어 있었다. 그것이 다 올라갈 때까지. 아주 오래.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-16, spirit:-16 } },
    { l:'② 마력으로 그것의 걸음을 늦춘다.', k:'steady', dc:23, cost:{ mana:30 },
      ok:`계단 첫 칸에 손을 대고 마력을 밀어 넣었다. 올라오는 것의 걸음 사이를 늘였다. 날을 하루 미루듯이.<br><br>소리가 느려진다. 한 칸, 한참 있다가 한 칸. 그 사이에 일행이 다 내려갔다. 마지막에 내려가며 손을 뗐다.<br>등 뒤에서 소리가 한꺼번에 빨라졌다. 늦춘 만큼 몰아서. 이쪽은 이미 아래층 문 안이었다.`,
      ng:`밀어 넣는데 마력이 계단을 타고 내려가 그것에 닿는다. 그것이 마력을 맛본다.<br><br>소리가 빨라진다. 이쪽으로. 마력을 끊고 물러났다. 계단 아래에서 무엇이 쩝 하고 입맛을 다셨다.<br>머리가 하얗게 비었다. 한참 다른 길로 돌았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'거울 — 다르게 떨어지는 산가지',
  x:`복도 벽에 커다란 거울이 걸려 있다.<br><br>
    거울 앞에서 산가지를 던졌다. 거울 속에서도 산가지가 떨어진다. 그런데 다르게 떨어진다. 이쪽은 셋이 눕고 둘이 섰다. 거울 속은 다섯이 다 섰다.<br>
    거울 속 점술가가 그 괘를 읽고 있다. 이쪽보다 먼저.<br><br>
    거울 속 입이 움직인다. 괘를 읽는 입 모양이다.`,
  o:[
    { l:'① 거울 속 괘를 읽는다.', k:'gaze', dc:23,
      doom:{ title:'거울 괘', what:'거울 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`거울 속 산가지를 읽었다. 다섯이 다 선 괘. 그런 괘는 없다. 없는 괘를 읽으려고 거울에 다가갔다.<br><br>거울 속 점술가가 손을 뻗는다. 이쪽 손목을 잡는다. 유리가 없다. 차갑다.<br>당긴다. 몸이 거울 쪽으로 기운다. 거울 속 복도가 이쪽 복도보다 길다. 끝에 산가지 다섯 개가 서 있다. 사람 키만 하게.<br><br>남의 괘는 읽어도 된다. 거울 속 제 괘는 읽는 순간 그쪽 것이 된다.`,
        dieText:`복도 벽 거울 앞에 산가지 다섯 개가 흩어져 있다. 셋이 눕고 둘이 섰다.<br><br>거울 속에는 산가지가 없다. 사람 하나가 거울 안쪽에서 유리를 손바닥으로 짚고 있다.<br>입이 움직인다. 괘를 읽는 입 모양이다.` },
      ok:`거울 속 괘를 곁눈으로만 읽었다. 정면으로 보지 않았다. 다섯이 다 선 괘. 이쪽 괘를 거꾸로 세운 것이다.<br><br>거꾸로 세운 괘는 거꾸로 읽으면 된다. 서지 말라는 괘다. 멈추지 말고 가라는 것이다.<br>멈추지 않고 거울 앞을 지났다. 거울 속 사람은 선 자리에서 고개만 이쪽을 따라 돌렸다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 거울을 덮고 다시 던진다.', k:'luck', dc:22, wake:1,
      ok:`외투를 벗어 거울에 걸었다. 덮인 거울은 괘를 못 읽는다.<br><br>다시 던졌다. 셋이 눕고 둘이 섰다. 아까와 같다. 이쪽 괘는 이쪽에만 떨어진다. 선 둘이 가리키는 쪽으로 걸었다.<br>외투는 걷어 오지 않았다. 덮인 채로 두는 게 나았다.<br><br>남이 먼저 읽으려는 괘는 가리고 친다. 괘를 지키는 손이 괘를 던지는 손만큼 빨라졌다.`,
      ng:`외투를 걸었는데 외투 밑이 볼록하다. 거울 속에서 누가 안쪽에서 밀고 있다.<br><br>외투 소매가 들린다. 이쪽 손을 찾는다. 던지려던 산가지를 떨어뜨렸다. 줍지 못하고 물러났다.<br>산가지 셋만 남았다. 셋으로 치는 괘는 답이 반쪽이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 이름 부르는 목소리',
  x:`어둠 속에서 누가 일행 이름을 부른다. 하나씩.<br><br>
    일행 목소리다. 셋이다. 셋 다 일행 목소리다. 하나는 진짜다. 아까 저쪽 끝으로 물을 길으러 간 사람 것이다.<br>
    나머지 둘은 흉내다. 흉내는 대답한 사람을 데려간다.<br><br>
    손에 쥔 산가지가 저절로 떤다.`,
  o:[
    { l:'① 산가지로 진짜를 가린다.', k:'luck', dc:22, wake:1,
      ok:`목소리마다 한 번씩 산가지를 던졌다. 첫째, 다섯이 다 눕는다. 둘째도. 셋째는 하나가 선다.<br><br>선 산가지는 산 사람이다. 셋째 목소리 쪽으로 대답했다. 물통을 든 일행이 어둠 속에서 걸어 나왔다. 숨이 차 있다.<br>나머지 두 목소리가 그 사람처럼 숨이 찬 척을 했다. 그러다 그쳤다.<br><br>괘가 목소리를 가렸다. 귀로 못 하는 일을 손이 했다. 산가지가 이제 길만이 아니라 사람도 가린다.`,
      ng:`던지는데 셋 다 하나씩 선다. 셋 다 산 사람이다. 아니면 셋 다 아니다.<br><br>망설이는 사이 일행 하나가 첫째 목소리에 대답했다. 어둠 속에서 손이 나와 그 사람 소매를 잡는다. 다 같이 붙들어 당겨 왔다.<br>진짜는 한참 뒤에 혼자 돌아왔다. 아무도 자기를 안 불러서 길을 잃을 뻔했다고 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 다들 귀를 막고 기다리게 한다.', k:'fix', dc:22,
      ok:`손짓으로 다들 귀를 막게 했다. 이쪽도 막았다. 대답하지 않으면 부르는 쪽도 지친다.<br><br>한참 뒤에 누가 어깨를 두드린다. 물통 든 일행이다. 귀를 막은 일행들을 보고 어리둥절해한다.<br>그 사람은 누가 자기 이름을 부르는 걸 들었다고 했다. 이쪽 목소리로.`,
      ng:`귀를 막았는데 목소리가 손바닥 안쪽에서 들린다. 더 가까이.<br><br>일행 하나가 참지 못하고 대답했다. 네. 목소리들이 웃는다. 셋이 같이.<br>그 사람 발목을 다 같이 붙들었다. 어둠 쪽으로 반 걸음 끌려간 뒤였다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 두 번 꾼 꿈',
  x:`쉬는 자리에서 일행 하나가 잠에서 깨어 떨고 있다. 꿈을 꿨다고 한다.<br><br>
    긴 복도를 걸었다. 끝에 문이 있고, 문 너머에서 누가 이름을 불렀다. 문고리를 잡았을 때 깼다. 아까도 같은 꿈이었다.<br>
    같은 꿈을 두 번 꾸면 그건 꿈이 아니라 부름이다.<br><br>
    그 사람이 다시 눈을 감으려 한다. 졸음이 너무 무겁다고.`,
  o:[
    { l:'① 꿈을 거꾸로 풀어 준다.', k:'bond', dc:22,
      ok:`"문고리를 잡은 꿈은 문이 닫히는 꿈이오. 다시는 그 문 앞에 안 서오."<br><br>틀린 풀이는 아니다. 꿈은 푸는 사람이 정한다. 그 사람이 숨을 고르고 다시 잠든다. 이번엔 꿈을 안 꿨다.<br>아침에 보니 그 사람 손바닥에 문고리 같은 둥근 멍이 있었다. 잡기 전에 놓은 자국이다.`,
      ng:`풀어 주는데 그 사람이 이미 잠들었다. 잠든 얼굴이 웃는다. 누가 불렀다.<br><br>흔들어도 안 깬다. 뺨을 쳤다. 깼다. 깨자마자 운다. 문을 열었다고 한다.<br>그 사람 눈동자에 문틀 같은 금이 한동안 남아 있었다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ mind:-17, spirit:-24 } },
    { l:'② 밤새 곁에서 깨워 둔다.', k:'steady', dc:22,
      ok:`그 사람 옆에 앉아 졸 때마다 어깨를 쳤다. 밤새.<br><br>꿈에 못 들어가면 문도 없다. 새벽 무렵 그 사람 졸음이 가벼워졌다. 부르던 것이 그만둔 것이다.<br>한숨도 못 잤다. 눈이 뻑뻑했다. 그래도 둘 다 여기 있다.`,
      ng:`깨우다 이쪽이 졸았다. 아주 잠깐.<br><br>복도를 걸었다. 끝에 문이 있다. 문 너머에서 이쪽 이름을 부른다. 깨어 보니 손이 허공의 무엇을 쥐고 있었다.<br>그 사람과 이쪽, 둘 다 손바닥에 둥근 멍이 생겼다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 마력을 실어 그 꿈에 따라 들어간다.', k:'gaze', dc:23, cost:{ mana:28 },
      doom:{ title:'같은 꿈', what:'남의 꿈속 문 너머로 끌려 들어갑니다', dc:18, sec:50,
        text:`그 사람 이마에 손을 얹고 마력을 실었다. 눈을 감자 복도가 보인다. 그 사람 꿈이다.<br><br>복도 끝 문 앞에 그 사람이 서 있다. 문고리를 잡으려 한다. 그 손을 잡았다. 그 사람이 돌아본다. 얼굴이 없다. 그 사람이 아니다.<br>문이 열린다. 안에서 손들이 나와 손목을, 팔을 잡는다. 꿈에 들어온 손님을 반긴다. 문 안으로 당긴다.<br><br>남의 꿈은 풀어 줄 수는 있어도 들어가면 안 된다. 들어가면 그 꿈 주인이 이쪽이 된다.`,
        dieText:`쉬는 자리에서 둘이 나란히 잠들어 있다.<br><br>둘 다 웃는다. 같은 꿈을 꾼다.<br>아무리 흔들어도 깨지 않는다. 둘 다 무엇을 쥔 모양으로 주먹을 쥐었다.` },
      ok:`이마에 손을 얹고 마력을 실었다. 복도가 보인다. 끝 문 앞에 그 사람이 서 있다. 문고리를 잡으려 한다.<br><br>그 사람을 부르지 않았다. 대신 문에 마력으로 빗장을 그었다. 꿈속 문에 꿈속 빗장. 그 사람 손이 문고리에서 미끄러진다.<br>눈을 떴다. 그 사람이 깊게 잔다. 꿈 없이.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'갈림길 — 쌀점',
  x:`복도가 네 갈래로 갈린다. 다 어둡다.<br><br>
    주머니에 쌀 한 줌이 있다. 쌀점은 오래된 점이다. 쌀알을 흩고 모인 모양을 읽는다.<br>
    흩었다. 쌀알이 바닥에서 저절로 굴러 모인다. 네 갈래 중 하나로. 한 알도 빠짐없이.<br><br>
    쌀이 모인 갈래 앞 바닥이 젖어 있다. 무엇이 방금 거기서 쌀을 먹고 있었던 것처럼.`,
  o:[
    { l:'① 쌀이 안 간 갈래를 읽는다.', k:'luck', dc:22,
      ok:`쌀이 모인 갈래는 무엇이 쌀을 부른 갈래다. 남은 셋 중에서 골라야 한다.<br><br>세 갈래 바닥을 봤다. 하나에 쌀알 한 톨이 가다 말고 멈춰 있다. 거기엔 무엇이 있지만 쌀을 부를 만큼 굶주리진 않았다.<br>나머지 둘 중 바람이 드는 쪽으로 갔다. 계단이 있었다. 계단 옆 틈에 산나물이 자라 있었다.`,
      ng:`쌀이 안 간 갈래를 골랐는데 등 뒤에서 쌀알 굴러오는 소리가 난다. 발뒤꿈치로.<br><br>쌀을 부른 것이 쌀을 따라온다. 뛰었다. 신발 바닥에 쌀알이 박혀 걸음마다 바스락거렸다.<br>한참 뒤에야 쌀알을 다 털었다. 털 때마다 뒤를 돌아봤다.`,
      win:{ exp:18, dream:3, item:'산나물' }, lose:{ hp:-22, mind:-16 } },
    { l:'② 쌀알을 도로 주워 담는다.', k:'sense', dc:22,
      ok:`쌀을 그 자리에 두면 무엇이 와서 먹는다. 먹은 것은 쌀 준 사람을 기억한다. 한 알씩 주워 담았다.<br><br>모인 갈래 앞에서 줍는데 젖은 바닥 너머가 조용하다. 쌀이 사라지자 그쪽 숨소리도 멀어진다.<br>다 주웠다. 어느 갈래도 고르지 않고 다른 길을 찾아 되돌아갔다.`,
      ng:`줍는데 쌀알이 손가락 사이로 자꾸 굴러 간다. 젖은 갈래 쪽으로.<br><br>마지막 한 알을 쫓아 갈래 입구까지 갔다. 어둠 속에서 젖은 손이 그 한 알을 먼저 집었다. 이쪽 손가락도 같이.<br>빼냈다. 손가락 끝이 하얗게 불었다. 물에 오래 담근 것처럼.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'내려가는 길 — 부러진 괘',
  x:`계단 앞에서 산가지를 꺼냈다. 내려가기 전 한 괘.<br><br>
    던졌다. 다섯 개가 다 부러진 채로 떨어진다. 던질 때는 멀쩡했다.<br>
    산가지가 부러지는 괘는 없다. 아니, 있다. 시골 노파가 한 번 말해 준 적이 있다. 점을 그만 치라는 괘라고.<br><br>
    부러진 끝이 다 계단 아래를 가리킨다.`,
  o:[
    { l:'① 한 토막만 품고 더 묻지 않는다.', k:'steady', dc:22, wake:1,
      ok:`더 묻지 않았다. 부러진 한 토막을 주워 품에 넣고 나머지는 계단참에 가지런히 뉘였다.<br><br>점을 그만 치라는 괘는 묻지 말라는 괘다. 아래가 어떤지 모르고 내려갔다. 계단이 짧았다. 아래층 문은 열려 있었다.<br>품 안 토막이 걸을 때마다 가슴을 쿡쿡 찔렀다. 살아 있다는 것처럼.<br><br>볼 수 있는데 안 보는 것. 처음으로 앞을 덮고 걸었다. 덮을 줄 알게 되자 보이는 것이 오히려 또렷해졌다.`,
      ng:`품에 넣으려는데 토막 끝이 손바닥을 찌른다. 피 한 방울이 계단 아래로 굴러간다.<br><br>피 한 방울도 괘다. 그 괘를 아래층이 받았다.<br>내려가는 내내 아래에서 무엇이 기다리는 소리가 났다. 다행히 문 앞에서 그쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 부러진 자리를 끝까지 읽는다.', k:'luck', dc:23,
      ok:`부러진 자리를 맞춰 봤다. 다섯 다 같은 높이에서 부러졌다. 손가락 한 마디쯤. 그 높이에 무엇이 있다는 괘다.<br><br>내려가며 발목 높이를 등불로 비췄다. 셋째 칸에 실 한 가닥이 팽팽하게 걸려 있다. 손가락 한 마디 높이. 넘었다.<br>실 끝은 계단 밑 어둠으로 이어져 있었다. 누가 끝을 쥐고 기다렸다.`,
      ng:`맞춰 보는데 끝들이 이어지지 않는다. 다섯 끝이 다 이쪽을 향한다.<br><br>무엇인지 모른 채 내려갔다. 셋째 칸에서 발목이 무엇에 걸렸다. 굴렀다.<br>계단 밑에서 무엇이 실을 감는 소리가 났다. 발목에 실 자국이 깊다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'A1', t:'방청석 — 불릴 자리',
  x:`방청석에 앉았다. 자리에서 일어나지 않기. 벽에 붙은 규칙이다.<br><br>
    무대 화면에 글씨가 뜬다. 곧 오늘의 친구를 불러요. 의자마다 번호가 있다. 일행은 흩어져 앉았다.<br>
    무릎 위에서 몰래 산가지를 던졌다. 이 판에서 누가 불릴지.<br><br>
    산가지 끝이 일행 하나의 의자를 가리킨다. 다시 던졌다. 같다.`,
  o:[
    { l:'① 괘가 비켜 갈 빈자리를 찾아 그 사람을 옮긴다.', k:'luck', dc:22, wake:1,
      ok:`한 번 더 던졌다. 이번엔 그 사람 말고 빈자리들을 물었다. 어느 빈자리가 안 불릴지.<br><br>산가지가 가리킨 빈자리로 그 사람을 옮겼다. 허리를 숙여, 박수 소리에 걸음을 묻어서. 북소리가 울린다. 화면에 번호가 뜬다. 그 사람 원래 자리다.<br>빈 의자가 들썩였다가 가라앉는다. 아무도 안 일어난다. 박수가 어색하게 길어졌다.<br><br>앞을 보는 데서 그치지 않고 앞을 피해 사람을 옮겼다. 보는 일에 손이 붙었다.`,
      ng:`옮기려는데 그 사람이 무서워 움직이지 못한다. 규칙 때문에.<br><br>북소리가 울린다. 그 사람 번호. 박수가 쏟아진다. 다 같이 그 사람을 의자에 눌러 앉혔다. 보이지 않는 손들이 그 사람을 들어 올리려 했다.<br>박수가 그칠 때까지 줄다리기를 했다. 그 사람 어깨가 빠졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14, spirit:-16 } },
    { l:'② 다른 점괘를 크게 말해 버린다.', k:'bond', dc:22,
      ok:`일어서지 않고 큰 소리로 말했다. "오늘의 친구는 이미 무대에 있소."<br><br>방청석이 조용해진다. 스피커가 지직거린다. 점치는 사람의 말은 점이 된다. 무대 화면이 무대 가운데를 비춘다. 이미 서 있는 인형탈 하나를.<br>박수가 그쪽으로 쏟아졌다. 일행 쪽은 아무도 안 봤다.`,
      ng:`말했는데 목소리가 방청석에 먹힌다. 아무도 못 들었다.<br><br>북소리. 번호. 그 사람이다. 박수가 쏟아진다. 붙드느라 다들 팔이 빠질 뻔했다.<br>그 사람은 끝내 안 끌려갔다. 대신 그 뒤로 박수 소리만 나면 몸을 떨었다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A1', t:'분장실 — 방글이 운세 기계',
  x:`분장실 구석에 상자 같은 기계가 있다. 위에 방글이 얼굴 인형이 앉았다. 「방글이 운세」 코너 소품이다.<br><br>
    손잡이를 당기면 인형이 고개를 끄덕이고 밑에서 카드가 나온다.<br>
    이런 기계는 싫다. 사람을 안 보고 치는 점이다.<br><br>
    그런데 기계가 저절로 고개를 끄덕이고 있다. 이쪽을 보면서. 카드 나오는 구멍이 반쯤 열려 있다.`,
  o:[
    { l:'① 당겨서 나온 카드를 읽는다.', k:'luck', dc:23,
      doom:{ title:'방글이 운세', what:'카드에 적힌 대로 무대로 끌려갑니다', dc:18, sec:50,
        text:`손잡이를 당겼다. 인형이 고개를 끄덕인다. 카드가 나온다. 크레용 글씨다.<br><br>「오늘 너는 무대에 서요. 박수를 많이 받아요.」<br>읽는 순간 분장실 거울 전구가 다 켜진다. 문이 열린다. 하얀 장갑들이 들어와 이쪽 팔짱을 낀다. 카드에 적힌 대로 해야 한다. 무대 쪽으로 끌려간다.<br><br>미리 써 둔 점괘는 믿지 않는다. 그런데 이건 미리 쓴 게 아니다. 지금 이쪽을 보고 썼다.`,
        dieText:`분장실 운세 기계 위 인형이 고개를 끄덕인다.<br><br>밑에서 카드가 한 장 나와 있다. 「오늘 너는 무대에 섰어요. 박수를 많이 받았어요.」<br>카드 구석에 별 스티커가 붙어 있다. 참 잘했어요.` },
      ok:`당겼다. 카드가 나온다. 읽기 전에 뒤집었다. 뒷면에 적혀 있다. 「읽으면 그대로 돼요.」<br><br>읽지 않았다. 반으로 접어 구멍에 도로 밀어 넣었다. 인형이 고개를 멈춘다. 기계 속에서 톱니가 헛도는 소리가 났다.<br>기계 서랍에 다른 카드들이 수북하다. 다 읽힌 카드다. 그 옆에 꿈결 몇 알이 굴러다녔다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 톱니 소리로 기계 속을 읽는다.', k:'gaze', dc:22,
      ok:`기계에 귀를 댔다. 톱니가 돈다. 그 밑에서 크레용이 종이를 긁는 소리가 난다. 기계 안에서 누가 쓴다.<br><br>뒤판 나사를 풀었다. 안에 작은 책상과 크레용이 있다. 쓰는 사람은 없다. 크레용만 저 혼자 움직인다. 다 쓰기 전에 크레용을 빼냈다.<br>쓰다 만 카드에 「오늘 너는」까지만 적혀 있다. 뒤는 비었다. 비었으니 아무 일도 없다.`,
      ng:`귀를 댔는데 안에서 누가 귀에 속삭인다. 크레용 냄새가 난다.<br><br>「오늘 너는」 다음 말을 듣기 전에 귀를 뗐다. 인형이 이쪽으로 고개를 꺾는다. 끄덕이지 않고, 꺾는다.<br>분장실을 나오는데 귓바퀴에 크레용 가루가 묻어 있었다. 노란색.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'③ 쳐다보지 않고 지나친다.', k:'steady', dc:21,
      ok:`쳐다보지 않았다. 사람을 안 보는 점은 이쪽도 안 본다.<br><br>기계 앞을 지날 때 고개 끄덕이는 소리가 빨라진다. 딸깍딸깍. 부르는 소리다. 걸음을 늦추지 않았다.<br>문을 나서자 소리가 멈췄다. 카드 한 장이 바닥에 떨어지는 소리가 났다. 줍지 않았다.`,
      ng:`지나치는데 발밑에 카드가 미끄러져 온다. 앞면이 위로. 글씨가 눈에 들어온다.<br><br>「돌아봐.」 돌아보지 않았다. 대신 목이 뻣뻣하게 굳어 한참 고개를 못 돌렸다.<br>일행이 목을 주물러 주는 내내 등 뒤에서 딸깍 소리가 났다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A1', t:'테이프 보관실 — 내일 회차',
  x:`테이프 선반 맨 끝 칸에 테이프 하나가 따로 꽂혀 있다.<br><br>
    날짜가 내일이다. 방글 동산, 내일 회차. 아직 찍지 않은 방송이 찍혀 있다.<br>
    내일은 대개 흐릿하게 보인다. 이건 또렷할 것이다.<br><br>
    옆에 데크가 있다. 테이프 넣는 구멍이 입처럼 벌어져 있다.`,
  o:[
    { l:'① 데크에 넣지 않고 마력으로 테이프만 읽는다.', k:'gaze', dc:23, cost:{ mana:28 },
      ok:`테이프를 손에 쥐고 마력을 흘렸다. 감긴 띠에서 그림이 손바닥으로 번져 온다.<br><br>내일 방송. 방청석. 오늘의 친구. 무대 가운데 앉은 사람이 손을 흔든다. 얼굴이 흐리다. 옷만 보인다. 이쪽 일행 옷이 아니다.<br>그림 속에서 카메라 셋이 한 번도 안 비추는 자리가 있다. 무대 옆 비상문 쪽. 그 자리를 기억해 두었다.`,
      ng:`마력을 흘리는데 그림이 손바닥을 타고 팔로 번진다. 내일 방송이 눈 안에서 돈다.<br><br>무대 가운데 앉은 사람이 손을 흔든다. 얼굴이 점점 또렷해진다. 테이프를 떨어뜨렸다. 얼굴이 다 보이기 직전이었다.<br>하루 종일 그 손 흔드는 박자가 눈앞에 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 테이프 띠를 끊어 둔다.', k:'break', dc:22,
      ok:`덮개를 열고 띠를 손가락에 걸어 끊었다.<br><br>찍힌 내일이 끊겼다. 끊긴 내일은 이어서 틀 수 없다. 선반이 조금 흔들린다. 다른 테이프들이 저마다 한 칸씩 기운다.<br>내일 방송이 끊기면 오늘 방송도 끝이 흐려진다. 이쪽에 나쁠 건 없다.`,
      ng:`끊는데 띠가 질기다. 손가락에 감긴다. 감긴 띠에서 박수 소리가 작게 난다.<br><br>띠가 손가락을 조인다. 끊어지지 않고 이쪽 손가락을 녹화한다. 억지로 뜯어냈다. 손가락에 띠 자국이 붉게 감겼다.<br>테이프는 그대로다. 내일도 그대로다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A1', t:'로비 — 멎은 시계의 시',
  x:`로비 벽시계가 네 시 오십삼 분이다. 초침이 없다.<br><br>
    일행이 묻는다. 다섯 시까지 얼마나 남았느냐고. 시계는 대답을 안 한다.<br>
    시계가 멎어도 시는 흐른다. 시를 받는 게 일이다.<br><br>
    산가지를 손에 쥐었다. 손바닥 안에서 떨림이 시를 센다.`,
  o:[
    { l:'① 산가지 떨림으로 남은 시를 센다.', k:'luck', dc:22, wake:1,
      ok:`쥐고 눈을 감았다. 떨림이 한 번, 쉼, 한 번. 쉼이 조금씩 짧아진다. 다섯 시로 갈수록 짧아질 것이다.<br><br>남은 떨림을 셌다. 일곱. 일곱 번 떨면 다섯 시다. 일행에게 일곱 번에 맞춘 걸음을 일러 주었다. 어디서 쉬고 어디서 서두를지.<br>로비를 지나며 시계를 봤다. 여전히 네 시 오십삼 분이다. 그래도 이쪽은 시를 쥐고 있다.<br><br>멎은 시계 앞에서도 시가 손에 잡혔다. 앞을 재는 눈금이 이제 손바닥에 새겨졌다.`,
      ng:`세는데 떨림이 멈춘다. 쉼만 이어진다. 시가 안 흐른다.<br><br>눈을 떴다. 로비 텔레비전 속 노란 얼굴이 이쪽을 보고 있다. 시를 세는 사람을 처음 본다는 듯이.<br>입 모양이 말한다. 언제나 다섯 시 전이야. 그 말이 맞는 것 같아 한참 서 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 시계를 등지게 일행을 이끈다.', k:'fix', dc:22,
      ok:`다들 시계를 등지게 했다. 시를 모르면 서두르지 않는다. 서두르지 않으면 실수가 줄어든다.<br><br>등불 하나에 모아 같은 걸음으로 걷게 했다. 로비를 지났다. 등 뒤에서 분침이 한 칸 넘어가는 소리가 났다. 아무도 안 돌아봤다.`,
      ng:`등지게 했는데 일행 하나가 돌아본다.<br><br>분침이 그 사람 눈앞에서 한 칸 넘어간다. 네 시 오십사 분. 그 사람 얼굴이 하얘진다. 일 분을 잃었다고 한다. 무엇을 잃었는지는 말하지 못했다.<br>다들 서두르기 시작했다. 계단에서 하나가 넘어졌다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A1', t:'스튜디오 — 천장의 별자리',
  x:`스튜디오 천장에 조명이 수십 개 매달렸다. 꺼져 있다. 하나하나 아주 희미하게 붉다.<br><br>
    별이 없는 데서는 별을 짓는다. 조명들이 별자리처럼 늘어서 있다.<br>
    조명은 켜지면 무대를 비춘다. 비추는 자리가 무대가 된다.<br><br>
    발밑 바닥에 테이프로 가위표가 붙어 있다. 여기 서세요.`,
  o:[
    { l:'① 조명 별자리로 빛이 안 닿는 길을 짓는다.', k:'luck', dc:22, wake:1,
      ok:`조명 머리가 향한 데를 이었다. 국자 모양이 나온다. 국자 안쪽이 무대다. 손잡이 끝이 가리키는 데는 아무 조명도 안 닿는다.<br><br>손잡이 쪽으로 일행을 데려갔다. 조명이 하나씩 켜진다. 가위표, 무대 가운데, 방청석. 국자 안이 하얗게 탄다. 손잡이 끝은 끝까지 어둡다.<br>그 어둠 속에 비상문이 있었다.<br><br>하늘이 없어도 별을 짓는다. 이제는 그 눈이 사람 손이 단 별까지 읽는다.`,
      ng:`잇는데 조명 하나가 저절로 돌아간다. 별자리가 바뀐다. 국자가 뒤집혔다.<br><br>뒤집힌 손잡이를 따라갔다. 가위표 위였다. 조명이 켜진다. 정수리로. 박수가 쏟아진다.<br>엎드려 기어서 빛 밖으로 나왔다. 정수리가 데었다. 머리카락 타는 냄새가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 가위표에 붙은 날짜를 읽는다.', k:'gaze', dc:23,
      doom:{ title:'여기 서세요', what:'조명에 붙들려 무대 가운데로 끌려갑니다', dc:19, sec:45,
        text:`가위표를 봤다. 테이프가 여러 겹이다. 겹마다 날짜가 적혔다. 누가 설 때마다 새로 붙였다.<br><br>읽으려고 쪼그려 앉았다. 그 순간 조명 하나가 켜진다. 가위표 위로. 등 위로. 하얗다. 빛이 무겁다.<br>빛이 등을 누른다. 일어서지 못한다. 빛 둘레 바닥이 미끄러진다. 무대 가운데로. 빛이 이쪽을 끌고 간다.<br><br>표시를 읽는 사람이 표시 위에 앉으면 표시가 그 사람을 읽는다.`,
        dieText:`스튜디오 바닥 가위표 위에 테이프가 한 겹 더 붙었다. 오늘 날짜다.<br><br>천장 조명 하나가 그 위를 비춘다. 꺼지지 않는다.<br>빛 안에서 누가 손을 흔든다. 박자가 맞다.` },
      ok:`가위표 앞에서 서지 않았다. 몸을 비스듬히 하고 테이프만 봤다. 겹마다 날짜. 맨 위가 오늘이다. 아직 아무도 안 섰는데.<br><br>오늘 누가 설 자리다. 일행 누구도 그 근처로 가지 않게 했다. 테이프 끝을 손톱으로 들어 반쯤 떼어 냈다.<br>조명 하나가 켜졌다. 반쯤 떨어진 가위표 위로. 아무도 없다. 빛이 한참 바닥만 비췄다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A2', t:'종탑 — 물거울',
  x:`종탑 창가에서 물을 내려다봤다. 물이 끝까지 평평하다. 거울 같다.<br><br>
    물거울로 먼 데를 보는 법을 안다. 이 물은 맑지 않다. 그런데 비친다. 지금이 아닌 것이 비친다.<br>
    물에 비친 종탑 아래로 학교 마당이 보인다. 물이 차기 전이다. 아이들이 줄을 서 있다. 점호다.<br><br>
    줄 끝 아이 하나가 고개를 든다. 물거울 이쪽을 본다.`,
  o:[
    { l:'① 잠기기 전 학교를 읽어 길을 찾는다.', k:'luck', dc:22, wake:1,
      ok:`아이 눈을 피해 마당 가장자리를 봤다. 본관 옆에 바깥 계단이 있다. 지금은 물속이다. 계단 꼭대기 문이 종탑 아래층과 이어진다.<br><br>그 자리를 기억했다. 종탑 계단으로 내려가 벽을 더듬었다. 회칠 밑에 문틀이 있었다. 밀자 열렸다. 마른 계단이 한 층 아래로 이어진다.<br>돌아보니 물거울 속 줄 끝 아이가 아직 고개를 들고 있었다.<br><br>물거울은 앞만 보여 주지 않는다. 지난날도 길이 된다. 지난 것을 읽는 눈이 앞을 보는 눈과 같은 자리에서 뜨였다.`,
      ng:`가장자리를 보는데 줄 끝 아이 눈이 따라온다. 물거울 속에서 이쪽을 정확히 본다.<br><br>아이가 손을 든다. 출석. 이쪽 대신 대답한 것 같다. 물 위로 동그란 물결이 종탑 쪽으로 번진다.<br>창가에서 물러났다. 물결이 창틀까지 와서 한참 찰랑였다. 들어오라고.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-24 } },
    { l:'② 마력을 실어 더 깊이 들여다본다.', k:'gaze', dc:23, cost:{ mana:28 },
      doom:{ title:'물거울', what:'물거울 아래로 끌려 가라앉습니다', dc:19, sec:45,
        text:`마력을 실어 물거울에 눈을 댔다. 학교가 또렷해진다. 마당, 교실, 복도. 물이 차오르던 날이 보인다.<br><br>그날 줄 끝 아이가 이쪽을 보고 손을 내민다. 그날의 물이 이쪽으로 올라온다. 창틀을 넘는다. 손목이 젖는다. 아이 손이 손목을 잡는다.<br>당긴다. 물거울 아래로. 그날로. 몸이 창틀을 넘어 물속으로 가라앉는다. 물이 차다. 그날처럼.<br><br>지난날은 보는 것으로 그쳐야 한다. 마력을 실으면 그날이 이쪽을 본다.`,
        dieText:`종탑 창가 아래 물이 평평하다. 거울 같다.<br><br>물에 비친 마당에 아이들이 줄을 서 있다. 줄 끝에 하나가 늘었다. 키가 크다.<br>그 아이도 고개를 들고 물거울 이쪽을 본다.` },
      ok:`마력을 실어 깊이 봤다. 물이 차오르던 날이 보인다. 아이 손이 뻗어 오기 전에 눈을 물에서 뗐다. 마력은 거두지 않았다.<br><br>떼어 낸 눈에 그날 그림이 남아 있다. 물이 어디부터 찼는지. 본관 서쪽이 제일 늦게 잠겼다. 그쪽에 공기가 남는다.<br>그 그림을 지도처럼 일행에게 그려 주었다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A2', t:'교실 — 생일표',
  x:`교실 뒤 게시판에 생일표가 붙어 있다. 물이 게시판 아래까지 찼다.<br><br>
    이름과 생일. 줄마다 별 스티커. 생일을 보면 저절로 사주를 짚는다. 버릇이다.<br>
    짚다 보니 이상하다. 다 다른 날 태어났는데 끝이 같다. 같은 날 같은 시. 물이 찬 날이다.<br><br>
    맨 아래 줄에 빈칸이 있다. 이름은 비었고 생일은 적혀 있다. 이쪽 생일이다.`,
  o:[
    { l:'① 이쪽 사주를 다시 짚는다.', k:'luck', dc:22,
      ok:`이쪽 사주를 손가락으로 짚었다. 끝이 같지 않다. 이쪽 끝은 아직 안 정해졌다. 표에 붙은 생일들과 다르다.<br><br>정해지지 않은 사주는 이 표에 못 들어간다. 빈칸 생일 글씨를 손톱으로 긁었다. 쉽게 지워진다. 아직 마르지 않은 글씨다.<br>지운 자리 밑에 다른 글씨가 있다. 누가 먼저 쓰였다가 지워진 생일이다. 그 사람도 빠져나갔다.`,
      ng:`짚는데 이쪽 사주 끝이 흔들린다. 표 위 다른 사주들 끝으로 기운다. 같은 날 같은 시로.<br><br>손가락을 뗐다. 별 스티커 하나가 이쪽 빈칸에 붙어 있다. 언제 붙었는지 모른다.<br>떼려고 하니 스티커가 손톱 밑으로 파고든다. 한참 쓰렸다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 생일표를 떼어 물에 띄운다.', k:'break', dc:22,
      ok:`생일표를 통째로 떼어 물 위에 띄웠다.<br><br>표가 천천히 떠간다. 교실 뒤 의자 쪽으로. 젖은 교복들이 하나씩 표를 들여다본다. 제 생일을 찾는다. 이쪽 빈칸은 안 본다.<br>문을 나올 때 등 뒤에서 아이들이 생일 노래를 불렀다. 물속에서. 거품으로.`,
      ng:`떼는데 표 뒤에 표가 또 있다. 또. 또. 해마다 붙인 것이다.<br><br>맨 뒤 표가 제일 오래됐다. 그 표 빈칸에도 이쪽 생일이 있다. 이쪽 글씨다. 쓴 적이 없다.<br>떼다 만 표들이 물 위로 쏟아져 다리에 감긴다. 한참 떼어 내며 교실을 나왔다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A2', t:'기숙사 — 베개 밑 쪽지',
  x:`기숙사 침대마다 베개가 있다. 물 위에 떠 있는 것도 있다.<br><br>
    베개 밑에 쪽지가 하나씩 들어 있다. 아이들 점이다. 이름을 쓰고 베고 자면 그 사람이 꿈에 나온다고.<br>
    쪽지마다 이름이 같다. 사감 이름이다. 좋아서 쓴 게 아니다. 꿈에서라도 사감이 어디로 오는지 미리 보려고.<br><br>
    빈 침대 베개 밑 쪽지만 이름이 없다. 대신 「다음」이라고 적혀 있다.`,
  o:[
    { l:'① 쪽지 뒷면 꿈들을 모아 읽는다.', k:'luck', dc:22,
      ok:`쪽지 뒷면을 하나씩 봤다. 꿈을 꾸고 적어 둔 것이 있다. 「사감이 왼쪽 계단으로 왔다.」 「오른쪽 문은 안 열었다.」 「물 차기 전에 종이 울렸다.」<br><br>꿈 점도 여럿 모이면 길이 된다. 다 겹치는 데가 있다. 오른쪽 문. 사감은 오른쪽 문을 열지 않는다.<br>오른쪽 문으로 일행을 이끌었다. 문 옆 사물함 위에 아이들이 숨겨 둔 꿀 사탕 깡통이 있었다.`,
      ng:`읽는데 쪽지 하나가 방금 젖었다. 「사감이 온다. 지금.」<br><br>복도 끝에서 젖은 발소리가 난다. 다들 물속에 엎드려 숨을 참았다. 발소리가 침대 사이를 한참 돌았다.<br>올라왔을 때 쪽지들이 다 젖어 있었다. 글씨가 번져 이쪽 이름이 됐다.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-14, spirit:-16 } },
    { l:'② 「다음」 쪽지를 태운다.', k:'steady', dc:22,
      ok:`「다음」 쪽지를 등불에 댔다. 젖은 종이가 안 탄다. 한참 들고 있었다. 결국 탔다.<br><br>다음이 없으면 다음에 누울 사람도 없다. 빈 침대 매트리스가 아주 조금 올라온다. 누가 일어난 것처럼.<br>쪽지 재가 물에 녹으며 짧게 지직거렸다.`,
      ng:`대는데 쪽지는 안 타고 등불이 꺼진다.<br><br>어둠 속에서 빈 침대 매트리스가 삐걱거린다. 누가 눕는다. 다음 사람이 정해졌다는 것처럼. 등불을 다시 켤 때까지 아무도 움직이지 않았다.<br>켜고 보니 일행 하나 머리카락이 젖어 있었다. 베개를 벤 자리만.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-18, spirit:-20 } }
  ] },

{ at:'A2', t:'계단 — 물이 오르는 때',
  x:`계단 아래로 물이 찰랑인다. 내려가려면 숨을 참아야 한다.<br><br>
    물 높이가 오르내린다. 숨 쉬듯이. 오를 때는 다음 계단참까지 잠기고, 내릴 때는 천장에 손바닥 한 뼘 공기가 생긴다.<br>
    물때 읽는 법은 바닷가 노인들에게 배웠다. 달이 없어도 물에는 때가 있다.<br><br>
    물 오르는 소리가 위층 점호 소리와 겹친다. 하나, 둘, 셋.`,
  o:[
    { l:'① 거품으로 물때를 읽는다.', k:'luck', dc:22, wake:1,
      ok:`물 위로 올라오는 거품을 셌다. 물이 내릴 때는 거품이 굵고 오를 때는 가늘다. 점호 번호 열 개마다 한 번씩 뒤집힌다.<br><br>굵은 거품이 올라올 때 일행을 내려보냈다. 다음 계단참 한 뼘 공기에 다들 코를 댔다. 물이 다시 오르기 직전에 마지막 사람이 닿았다.<br>위에서 점호가 이쪽 층 번호를 불렀다. 물이 이쪽을 지나쳐 올라갔다.<br><br>달 없는 물에서 때를 읽었다. 하늘을 보던 셈이 물속에서도 그대로 섰다. 점이 닿는 데가 한 뼘 넓어졌다.`,
      ng:`세는데 거품 둘이 섞인다. 가는 거품 사이에 굵은 거품. 물 밑에서 누가 숨을 내쉰다.<br><br>때를 놓쳤다. 내려가는 중에 물이 올랐다. 공기가 사라진다. 천장에 코를 대고 버텼다. 물에 잠긴 귀에 점호 소리가 또렷했다.<br>물이 내렸을 때 다들 기침을 했다. 한 사람은 오래 말을 못 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 마력으로 공기 한 뼘을 붙든다.', k:'fix', dc:23, cost:{ mana:28 },
      ok:`계단참 천장에 손을 대고 마력을 실었다. 물이 내릴 때 생긴 한 뼘 공기를 붙들었다. 물이 다시 올라도 그 한 뼘만은 안 잠기게.<br><br>물이 오른다. 계단참이 잠긴다. 천장 한 뼘만 남는다. 일행이 차례로 거기 코를 대고 숨을 쉬었다. 다 내려갈 때까지 붙들었다.<br>손을 떼자 공기가 거품이 되어 흩어졌다. 위층 어디선가 누가 그 거품을 반겼다.`,
      ng:`붙드는데 물 밑에서도 그 공기를 붙든다. 이쪽은 마력이고 저쪽은 숨이다.<br><br>공기가 반으로 줄었다. 코끝만 내밀고 버텼다. 마력이 헐렁하게 빠져나간다. 머리가 하얗다.<br>물 밑에서 거품이 즐겁게 올라왔다. 이쪽 공기로 숨을 쉰 거품이다.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A2', t:'교무실 — 내일 출석부',
  x:`교무실 책상 위에 출석부가 펼쳐져 있다. 내일 날짜다.<br><br>
    칸이 다 채워졌다. 출석, 출석, 출석. 이백십이 명 다. 맨 아래 줄이 하나 더 있다. 이백십삼. 이름은 비었다. 출석 칸에 동그라미가 그려져 있다.<br>
    내일이 이렇게 정해져 있는 건 처음 본다.<br><br>
    붉은 펜이 출석부 옆에 놓여 있다. 뚜껑이 열려 있다.`,
  o:[
    { l:'① 동그라미의 주인을 점친다.', k:'luck', dc:22,
      ok:`산가지를 출석부 위에 던졌다. 이백십삼 줄을 짚는다. 그다음 짚는 건 일행 누구도 아니다. 교무실 문밖이다.<br><br>문밖 복도에 먼저 이 층을 지나간 누군가의 신발 한 짝이 떠 있다. 동그라미는 그 사람 것이다. 이미 정해졌다. 이쪽 일행이 아니다.<br>출석부를 덮었다. 남의 정해진 내일은 건드리지 않는다. 건드리면 그 자리가 빈다. 빈자리는 누가 채운다.`,
      ng:`던졌는데 산가지가 이백십삼 줄에서 멈추지 않는다. 미끄러져 일행 하나를 가리킨다.<br><br>그 사람 얼굴이 하얘진다. 이름 칸에 글씨가 번지기 시작한다. 덮어 버렸다. 덮인 출석부 안에서 펜 굴러가는 소리가 났다.<br>그 사람은 그날 내내 대답을 안 하려고 입을 꾹 다물었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 붉은 펜으로 동그라미를 고친다.', k:'fix', dc:23,
      doom:{ title:'이백십삼', what:'출석으로 바뀌어 물 밑 교실로 끌려갑니다', dc:19, sec:45,
        text:`붉은 펜을 들어 동그라미 위에 가위표를 그었다. 결석.<br><br>펜이 손에서 안 떨어진다. 펜 끝이 저절로 움직인다. 가위표를 동그라미로 덧그린다. 그리고 이름 칸으로 간다. 이쪽 이름을 쓴다. 이쪽 글씨로.<br>교무실 스피커에서 점호가 울린다. 이백십삼. 입이 저절로 열린다. 네. 발밑 물이 당긴다. 아래층 교실 쪽으로. 빈자리로.<br><br>내일을 고치려는 손은 내일에 이름을 남긴다. 알면서도 펜을 들었다.`,
        dieText:`교무실 책상 위 출석부가 덮여 있다.<br><br>표지에 오늘 날짜가 적혔다. 재적 이백십삼.<br>붉은 펜이 뚜껑이 닫힌 채 출석부 위에 반듯하게 놓여 있다.` },
      ok:`펜을 들되 동그라미에 대지 않았다. 동그라미 옆 빈 이름 칸에 아주 작게 적었다. 「미정」.<br><br>정해진 출석에 이름이 미정이면 부를 수가 없다. 스피커에서 점호가 울린다. 이백십이에서 멈춘다. 한참 조용하다가 끝났다.<br>펜 뚜껑을 닫아 두었다. 손바닥이 붉게 물들었다.`,
      win:{ exp:22, dream:4 } }
  ] }

]);

// ==========================================
// 🏺 수집가 (collector) · 자원 없음
// ==========================================
kJob('collector', 'A', [

{ at:'A', t:'입구 — 비워 둔 주머니',
  x:`들어갈 때는 늘 주머니를 비운다. 나올 때 무엇을 얻었는지 알려고.<br><br>
    문턱을 넘고 주머니에 손을 넣었다. 빈 줄 알았다. 손끝에 종이가 걸린다.<br>
    작은 꼬리표다. 실이 달렸다. 물건을 모으면 하나하나 다는 것과 같다. 번호, 그리고 오늘 날짜.<br><br>
    품목 칸이 비었다. 무엇에 달지 아직 안 정한 꼬리표다.`,
  o:[
    { l:'① 꼬리표 글씨로 단 사람을 가늠한다.', k:'gaze', dc:22, wake:1,
      ok:`등불에 비췄다. 번호 글씨가 반듯하다. 오래 쓴 손이다. 7에 꼭 가로줄을 긋는다. 같은 버릇의 꼬리표를 본 적이 있다. 아까 복도 액자 뒤에서.<br><br>돌아가 액자들을 뒤집었다. 셋째 액자 뒤에 같은 꼬리표가 있다. 번호가 이쪽 것 바로 앞이다. 품목 칸에 「등불 든 사람」. 액자 그림 속에 등불 든 사람이 서 있다.<br>이쪽 꼬리표를 그 액자 뒤에 같이 매달았다. 한 물건에 번호가 둘이면 하나는 무효다.<br><br>꼬리표 한 장으로 모으는 손을 알아봤다. 물건 너머에서 물건을 모으는 쪽을 읽는 눈이 생겼다.`,
      ng:`비추는데 품목 칸에 글씨가 번져 오른다. 보는 동안 쓰인다.<br><br>「주머니에 손 넣은 사람.」 손을 뺐다. 꼬리표 실이 손가락에 감겨 따라 나온다.<br>실을 끊는 데 한참 걸렸다. 손가락에 실 자국이 반지처럼 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 꼬리표를 버리고 간다.', k:'steady', dc:21,
      ok:`꼬리표를 문턱 밖으로 던졌다. 남이 단 꼬리표는 이쪽 것이 아니다.<br><br>몇 걸음 가서 주머니를 만졌다. 비었다. 다시 몇 걸음. 비었다.<br>한참 뒤에야 마음이 놓였다. 다음 층에서 주머니를 만지기 전까지는.`,
      ng:`던졌는데 다음 걸음에 주머니가 바스락거린다. 같은 꼬리표다.<br><br>세 번 던졌다. 세 번 돌아왔다. 네 번째는 쥐고 다녔다.<br>손이 내내 젖었다. 땀이 아니었는지도 모른다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'A', t:'복도 — 줄지은 신발',
  x:`복도 벽을 따라 신발이 놓여 있다. 짝을 맞춰, 앞코를 벽에 대고. 끝없이.<br><br>
    짝을 본다. 맞는지, 빠졌는지. 버릇이다.<br>
    한 켤레가 짝이 안 맞는다. 왼쪽만 있다. 오른쪽 자리가 비었다.<br><br>
    그 왼쪽 신발이 이쪽 신발과 같다. 크기도, 닳은 자리도.`,
  o:[
    { l:'① 다른 짝짝이를 찾아 빈자리를 채운다.', k:'luck', dc:22,
      ok:`줄을 따라 걸으며 봤다. 끝 쪽에 오른쪽만 있는 신발이 하나 있다. 크기가 비슷하다.<br><br>그것을 들어 빈 오른쪽 자리에 놓았다. 짝짝이끼리 한 켤레. 영 내키지 않는 짝이다. 그래도 빈자리가 없어졌다.<br>줄 끝까지 지나는 동안 신발들이 앞코를 벽에서 떼지 않았다. 빈자리가 없으면 아무도 신기지 않는다.`,
      ng:`찾아 놓았는데 크기가 다르다. 신발이 저절로 밀려난다.<br><br>빈자리가 그대로다. 오른발이 그 자리로 끌린다. 신발 속 발가락이 저절로 웅크린다. 벽을 짚고 버텼다.<br>복도를 다 지날 때까지 오른발이 무거웠다. 발목이 벽 쪽으로 꺾였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 짝 없는 왼쪽 신발을 들어 본다.', k:'gaze', dc:23,
      doom:{ title:'빈 오른쪽', what:'신발 줄 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`왼쪽 신발을 들어 바닥을 봤다. 이쪽 신발과 닳은 데가 같다. 걷는 버릇까지 같다. 누구 것인지 알 것 같다.<br><br>든 손이 무겁다. 빈 오른쪽 자리가 이쪽 발을 당긴다. 이쪽 오른쪽 신발이 저절로 벗겨진다. 빈자리에 가 놓인다. 짝이 맞았다.<br>짝이 맞으면 주인이 있어야 한다. 몸이 줄 쪽으로 당겨진다. 앞코가 닿은 벽이 물렁하다.<br><br>짝을 맞추는 걸 평생 좋아했다. 맞춰지는 쪽이 될 줄은 몰랐다.`,
        dieText:`복도 벽을 따라 신발이 놓여 있다. 짝을 맞춰, 앞코를 벽에 대고.<br><br>짝 안 맞는 신발은 이제 없다. 줄이 한 켤레만큼 길어졌다.<br>다음 짝짝이는 다음 사람이 신고 온다.` },
      ok:`들어서 바닥만 보고 곧바로 내려놓았다. 이쪽 신발과 같다. 닳은 데까지.<br><br>제 신발 끈을 두 번 더 졸라맸다. 오른쪽 자리가 끌어도 안 벗겨지게. 줄을 지나는 동안 오른발이 몇 번 끌렸다. 끈이 버텼다.<br>복도 끝에서 돌아보니 그 왼쪽 신발이 반 뼘쯤 이쪽으로 돌아앉아 있었다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 줄을 보지 않고 복도 가운데로 걷는다.', k:'evade', dc:22,
      ok:`짝을 안 봤다. 보면 맞추고 싶어진다. 복도 한가운데로, 눈을 천장에 두고 걸었다.<br><br>신발 줄은 벽 쪽에만 있다. 가운데는 비었다. 끝까지 걸었다. 아무것도 발을 당기지 않았다.`,
      ng:`천장을 보고 걷다 무엇을 걷어찼다. 가운데에도 한 짝이 놓여 있었다.<br><br>걷어찬 신발이 굴러가 빈자리에 쏙 들어간다. 줄 전체가 한 번 들썩였다. 신발들이 일제히 앞코를 이쪽으로 돌렸다.<br>뛰었다. 등 뒤에서 신발 수백 짝이 바닥을 두드렸다. 계단에서야 그쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 주운 적 없는 단추',
  x:`쉬는 자리에서 주머니를 털었다. 여기까지 주운 것들이다.<br><br>
    하나하나 기억한다. 어디서, 어떻게. 주운 것은 잊지 않는다.<br>
    하나만 기억에 없다. 하얗고 작은 단추다. 가운데 구멍이 넷.<br><br>
    버려도 다시 주머니에 들어가 있다. 벌써 두 번째다.`,
  o:[
    { l:'① 단추의 결로 온 길을 짚는다.', k:'gaze', dc:22, wake:1,
      ok:`등불에 비춰 결을 봤다. 사기가 아니다. 뼈를 깎은 것이다. 구멍 넷을 뚫은 손이 서툴다. 아이 손이다.<br><br>실밥이 하나 끼어 있다. 하늘색 실. 일행 누구 옷에도 그런 실은 없다. 아까 지나온 계단참 난간에 하늘색 실 한 가닥이 걸려 있던 게 떠오른다.<br>일어나 그 계단참에 단추를 놓고 왔다. 그 뒤로 주머니에 돌아오지 않았다.<br><br>물건이 어디서 왔는지 결로 읽는다. 주운 것의 길을 거꾸로 짚는 손이 생겼다.`,
      ng:`비추는데 구멍 넷이 눈처럼 이쪽을 본다.<br><br>가린 게 아니라 들킨 기분이다. 단추를 놓았다. 손바닥에 구멍 넷 자국이 찍혀 있다.<br>밤새 그 자국이 근질거렸다. 아침에 보니 단추가 다시 주머니에 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 반을 덜어 돌로 눌러 둔다.', k:'steady', dc:22,
      ok:`너무 많이 모았다. 주운 것 반을 덜었다. 단추도 같이.<br><br>덜어 낸 것을 한데 모아 돌로 눌러 두었다. 단추가 그 밑에 깔렸다. 일어설 때 돌이 한 번 들썩였다. 그뿐이다.<br>주머니가 가벼워졌다. 걸음도.`,
      ng:`덜어 낸 것을 두고 일어섰는데 주머니가 아까보다 무겁다.<br><br>털어 보니 버린 것이 다 돌아와 있다. 단추가 맨 위에 있다. 다른 것들을 데리고 왔다.<br>걸음이 무겁다. 무게에 지는 건 처음이다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A', t:'방 — 표본 상자',
  x:`방 벽에 유리 뚜껑 상자가 걸려 있다. 표본 상자다.<br><br>
    나방이 핀에 꽂혀 줄지어 있다. 날개마다 이름표. 표본을 보면 이름표부터 읽는다.<br>
    이름표가 나방 이름이 아니다. 사람 이름이다. 날짜도 있다.<br><br>
    맨 끝 상자는 비었다. 핀 하나가 꽂힐 자리를 기다린다. 이름표가 붙었다. 아직 글씨는 없다.`,
  o:[
    { l:'① 아직 살아 있는 나방을 찾는다.', k:'luck', dc:22,
      ok:`한 줄씩 봤다. 다 굳었다. 가루가 날개에서 떨어진다. 그중 하나만 더듬이가 떤다. 아주 작게.<br><br>그 상자 유리를 손톱으로 두드렸다. 더듬이가 방 문 옆 벽장을 가리킨다. 벽장을 열었다. 안쪽 판자가 뜯겨 옆방으로 이어진다. 누가 빠져나간 구멍이다.<br>지나며 돌아보니 그 나방 이름표 날짜가 아주 오래된 것이었다. 오래 버틴 것은 길을 안다.`,
      ng:`찾는데 모든 나방 더듬이가 동시에 떤다. 이쪽을 향해.<br><br>유리 너머에서 가루가 일어난다. 상자마다 뿌옇게. 숨이 막힌다. 코를 막고 방을 나왔다.<br>한참 기침을 했다. 뱉은 침에 나방 가루가 반짝였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-20 } },
    { l:'② 빈 상자의 핀을 뽑아 둔다.', k:'break', dc:23,
      doom:{ title:'빈 상자', what:'핀에 꿰여 빈 상자 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`빈 상자 뚜껑을 들었다. 핀을 뽑으려고 손가락을 넣었다.<br><br>핀이 손가락을 꿴다. 아프지 않다. 그게 더 무섭다. 핀이 당긴다. 손이 상자 안으로 들어간다. 상자는 손바닥만 한데 팔꿈치까지 들어간다.<br>이름표에 글씨가 쓰인다. 이쪽 이름이다. 오늘 날짜다. 유리 뚜껑이 어깨 위로 내려온다.<br><br>평생 핀을 꽂아 왔다. 꽂히는 자리가 이렇게 조용한 줄은 몰랐다.`,
        dieText:`방 벽 표본 상자가 다 찼다.<br><br>맨 끝 상자에 나방 하나가 꽂혀 있다. 날개 무늬가 사람 얼굴 같다. 이름표에 이름과 오늘 날짜.<br>그 옆에 빈 상자가 하나 새로 걸렸다. 핀이 꽂힐 자리를 기다린다.` },
      ok:`뚜껑을 들고 손가락은 넣지 않았다. 핀 머리를 손톱 끝으로만 집어 단숨에 뽑았다.<br><br>핀이 손톱 끝에서 꿈틀한다. 바닥에 던지고 밟아 휘었다. 꽂을 핀이 없으면 빈 상자는 영영 빈다.<br>빈 이름표를 떼어 주머니에 넣었다. 빈 이름표도 모은다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'계단참 — 같은 업의 함',
  x:`계단참 구석에 작은 나무함이 놓여 있다. 칸막이가 촘촘하다.<br><br>
    칸마다 물건이 하나씩. 깨진 안경알, 녹슨 호루라기, 머리핀, 반쯤 탄 성냥. 칸마다 손글씨 쪽지가 있다. 어디서 주웠는지.<br>
    같은 업이다. 뚜껑 안쪽에 적혀 있다. 하나 가져가면 하나 넣을 것.<br><br>
    맨 가운데 칸이 비었다. 쪽지에 적혀 있다. 「제일 아끼는 것.」`,
  o:[
    { l:'① 제일 아끼는 것을 넣고 하나를 고른다.', k:'luck', dc:22, wake:1,
      ok:`주머니에서 제일 아끼는 것을 꺼냈다. 첫 층에서 주운 투명한 돌. 안에 물 한 방울이 갇힌 것.<br><br>가운데 칸에 넣고 쪽지 밑에 적었다. 어디서 주웠는지. 그리고 쪽지가 제일 오래된 구석 칸을 골랐다. 납작하게 굳은 꿀 덩이다. 아직 단내가 난다.<br>뚜껑을 닫는데 함 안에서 무엇이 칸을 고쳐 앉는 소리가 났다.<br><br>아끼는 것을 내놓을 줄 알게 됐다. 모으는 일이 쥐는 일만은 아니라는 것을 손이 배웠다.`,
      ng:`넣으려는데 손이 안 펴진다. 아끼는 것은 아끼는 것이다.<br><br>망설이는 사이 가운데 칸 쪽지 글씨가 바뀐다. 「제일 아끼는 사람.」 눈이 일행 쪽으로 갔다.<br>뚜껑을 덮고 함을 벽 쪽으로 돌려놓았다. 손이 덜덜 떨렸다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 물건은 두고 쪽지만 읽는다.', k:'gaze', dc:22,
      ok:`물건은 손대지 않고 쪽지를 읽었다. 「아래층 둘째 문 앞.」 「아래층 물통 밑.」 「아래층 창틀.」<br><br>쪽지만 모아도 지도가 된다. 아래층에서 쪽지가 말한 물통 밑을 들추니 말린 고기 한 꾸러미가 있었다. 먼저 간 이가 두고 간 것이다.<br>함 주인은 물건보다 쪽지를 더 아꼈을 것이다.`,
      ng:`읽는데 쪽지 글씨가 뒤로 갈수록 짧아지고 떨린다. 마지막 쪽지는 한 글자다. 「뒤」.<br><br>돌아봤다. 아무도 없다. 다시 보니 「뒤」가 「앞」이 되어 있다.<br>앞을 보지 못하고 한참 서 있었다. 계단을 내려갈 때 다리가 후들거렸다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ mind:-17, spirit:-20 } }
  ] },

{ at:'A', t:'잠긴 문 — 늘어나는 열쇠',
  x:`잠긴 문 옆 못에 열쇠 꾸러미가 걸려 있다.<br><br>
    세어 보니 열둘. 다시 세니 열셋. 열쇠를 셀 때는 틀리지 않는다. 다시 셌다. 열셋이다.<br>
    새로 생긴 하나는 반짝인다. 한 번도 안 쓴 열쇠다.<br><br>
    맞는 열쇠는 닳은 데가 다르다. 늘 그렇다.`,
  o:[
    { l:'① 제일 닳은 열쇠를 고른다.', k:'gaze', dc:22,
      ok:`하나씩 등불에 비췄다. 이 끝이 뭉툭한 것이 하나 있다. 자주 쓴 열쇠다. 넣었다. 돌았다.<br><br>안쪽은 창고다. 선반에 말린 버섯 자루가 있다.<br>나오며 문을 닫을 때 못에 걸린 꾸러미가 짤랑였다. 세지 않았다.`,
      ng:`비추는데 다 닳았다. 반짝이는 하나만 빼고.<br><br>하나씩 넣었다. 열두 번 다 안 맞는다. 그사이 등 뒤 복도가 조용해진다. 조용한 것이 다가오는 소리다.<br>열쇠를 놓고 물러났다. 문 아래 틈에서 빛이 한 번 깜빡였다.`,
      win:{ exp:18, dream:3, item:'야생 버섯' }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 새로 생긴 열쇠를 넣어 본다.', k:'luck', dc:23,
      doom:{ title:'열셋째 열쇠', what:'열린 문 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`반짝이는 열쇠를 넣었다. 부드럽게 들어간다. 돈다. 너무 쉽다.<br><br>문이 안쪽으로 열린다. 안은 이 복도다. 이 문 앞에 이쪽이 서 있다. 등을 보이고.<br>안쪽의 이쪽이 돌아선다. 열쇠 쥔 손을 잡는다. 당긴다. 문턱을 넘는다. 등 뒤에서 문이 닫힌다. 못에 꾸러미가 짤랑인다.<br><br>새 열쇠는 새 문을 연다. 알면서도 처음 보는 열쇠는 못 지나친다.`,
        dieText:`잠긴 문 옆 못에 열쇠 꾸러미가 걸려 있다.<br><br>세어 보면 열넷이다. 다시 세면 열다섯.<br>새로 생긴 열쇠 손잡이에 손때가 묻어 있다. 따뜻하다.` },
      ok:`반짝이는 열쇠를 넣고 돌리지 않았다. 문에 귀를 댔다. 문 너머에서 누가 이쪽 숨에 맞춰 숨을 쉰다.<br><br>열쇠를 빼서 이로 깨물어 휘었다. 다시는 안 들어가게. 휜 열쇠를 꾸러미에 도로 걸었다.<br>문을 돌아가는 길이 있었다. 꾸러미는 열세 개 그대로다. 휜 것도 하나로 친다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 열쇠는 두고 경첩을 뽑는다.', k:'break', dc:22,
      ok:`경첩을 봤다. 녹슬었다. 못이 헐겁다. 칼끝으로 못을 뽑았다. 문이 통째로 떨어졌다.<br><br>문 뒤는 계단이다. 문짝을 밟고 내려갔다. 못에 걸린 꾸러미는 그대로 두었다. 처음으로 열쇠를 안 모았다.`,
      ng:`못을 뽑는데 문이 이쪽으로 넘어온다. 어깨로 받았다. 무겁다.<br><br>문짝 뒷면에 손자국이 빼곡하다. 안쪽에서 민 자국이다. 내려놓고 보니 문 뒤는 벽이었다.<br>처음부터 열 데가 없는 문이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'창고 — 먼지의 켜',
  x:`창고 선반마다 물건이 쌓였다. 먼지가 두껍다.<br><br>
    먼지는 읽힌다. 켜가 몇 겹인지 보면 언제부터 그 자리에 있었는지 안다.<br>
    다 고르게 두껍다. 하나만 먼지가 없다. 가운데 선반 사기 그릇이다. 방금 누가 닦은 것처럼 깨끗하다.<br><br>
    그릇 안에 소금 덩이가 하나 담겼다. 하얗다.`,
  o:[
    { l:'① 먼지 두꺼운 쪽에서 찾는다.', k:'luck', dc:22,
      ok:`깨끗한 그릇은 건드리지 않았다. 깨끗한 것은 누가 지금도 쓰는 것이다.<br><br>먼지 두꺼운 상자들을 손끝으로 쓸어 이름표를 읽었다. 맨 아래 상자에 소금. 열었다. 굳은 소금 덩이가 기름종이에 싸여 있다. 아무도 오래 안 찾았다.<br>나오며 보니 깨끗한 그릇 소금이 하나 줄어 있었다. 누가 방금 집어 갔다. 이쪽이 아니다.`,
      ng:`상자를 쓸다 먼지가 확 일었다.<br><br>먼지 속에 발자국이 떠 있다. 공중에. 먼지가 내려앉는 데마다 발자국 모양이 생긴다. 이쪽으로 걸어온다.<br>창고 문을 닫고 등으로 막았다. 문틈으로 먼지가 한참 새어 나왔다. 기침이 오래 갔다.`,
      win:{ exp:18, dream:3, item:'소금 덩이' }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 깨끗한 그릇을 조금 틀어 놓는다.', k:'steady', dc:23,
      ok:`깨끗한 그릇을 들었다. 손때가 묻어 있다. 따뜻하다. 소금은 집지 않고 그릇째 선반에 도로 놓았다. 조금 틀어서.<br><br>누가 닦아 둔 자리에 남의 손이 탔다는 표시다. 쓰는 사람에게 그건 기분 나쁜 일이다. 그 사람은 이제 그 그릇을 안 쓴다.<br>나올 때 등 뒤에서 그릇이 바닥에 떨어져 깨지는 소리가 났다. 화가 난 소리다. 쫓아오지는 않았다.`,
      ng:`들었는데 그릇 밑에 손이 받쳐져 있다. 안 보이는 손이다.<br><br>그릇을 놓았다. 손이 그릇을 다시 올리고 이쪽 손을 쥐었다. 닦아 주려는 것처럼 손등을 문지른다.<br>뿌리치고 나왔다. 손등이 붉게 벗겨졌다. 너무 깨끗하게 닦였다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A', t:'방 — 사진첩',
  x:`탁자 위에 사진첩이 펼쳐져 있다. 낡았다.<br><br>
    사진마다 사람들이 웃으며 서 있다. 장마다 같은 자리, 같은 배경. 사람만 다르다.<br>
    마지막 장 사진 속에 일행이 서 있다. 이 방이다. 웃고 있다. 아무도 사진을 찍은 적이 없다.<br><br>
    그 사진 맨 뒷줄, 일행 사이에 모르는 얼굴이 하나 끼어 있다.`,
  o:[
    { l:'① 일행 사진을 떼어 낸다.', k:'hide', dc:22,
      ok:`모서리 풀칠을 손톱으로 조심스레 일으켰다. 떼어 냈다. 뒷면 날짜 칸이 비었다.<br><br>날짜가 없으면 아직 다 찍힌 게 아니다. 사진을 품에 넣고 사진첩을 덮었다. 덮는 순간 방 어디서 셔터 소리가 났다. 찰칵.<br>떼어 낸 자리를 찍은 것이다. 빈자리 사진이 한 장 남았다.`,
      ng:`떼어 내는데 사진 속 모르는 얼굴이 고개를 돌린다. 사진 밖, 이쪽을 본다.<br><br>손이 굳었다. 그 얼굴이 손가락 하나를 입에 댄다. 쉿. 사진을 놓았다. 사진첩이 저절로 덮였다.<br>방을 나오는 동안 일행이 하나 더 많은 것 같았다. 몇 번을 세도.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 제일 오래된 사진부터 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`앞장으로 넘겼다. 첫 사진은 누렇다. 사람들이 같은 자리에 서 있다. 맨 뒷줄에 그 모르는 얼굴이 있다. 똑같다. 늙지 않았다.<br><br>사진마다 그 얼굴만 그대로다. 그 얼굴이 사진첩 주인이다. 손님들 사이에 끼어 찍히는 것이 그의 수집이다.<br>마지막 장 사진 그 얼굴 위에 손톱으로 금을 그었다. 남의 수집에 남길 수 있는 제일 큰 흠이다. 사진 속 일행이 웃음을 멈추고 평소 얼굴로 돌아왔다.<br><br>무엇을 모았는지보다 누가 모았는지가 먼저 보인다. 모은 것들 사이에서 모은 손을 찾아내는 눈이 생겼다.`,
      ng:`넘기는데 앞장으로 갈수록 사진 속 사람이 줄어든다. 맨 앞장엔 그 얼굴 하나뿐이다. 이쪽을 보고 있다.<br><br>덮으려는데 손이 페이지에 붙는다. 사진 속 얼굴이 손을 뻗어 손가락 끝을 잡는다. 종이 손이다. 차다.<br>찢어 내듯 손을 뗐다. 손가락 끝 살갗이 사진에 붙어 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 주인 없는 손거울',
  x:`쉬는 자리에서 짐을 풀어 늘어놓았다. 일행 것이 한데 섞였다.<br><br>
    물건만 봐도 주인을 안다. 닳은 데, 묶은 버릇, 냄새. 하나씩 주인 앞에 밀어 주었다.<br>
    하나가 남는다. 작은 손거울이다. 일행 누구도 자기 것이 아니라고 한다.<br><br>
    거울 뒷면에 이름이 긁혀 있었다. 지금은 지워졌다.`,
  o:[
    { l:'① 닳은 자리로 주인을 짚는다.', k:'luck', dc:22, wake:1,
      ok:`거울을 손바닥에 올려 닳은 데를 봤다. 왼쪽 귀퉁이만 반들반들하다. 왼손잡이가 오래 쥐었다. 일행에 왼손잡이는 없다.<br><br>거울 면을 봤다. 입김 자국이 둥글게 굳었다. 아이 얼굴 높이다. 이 거울로 늘 등 뒤를 봤다.<br>쉬는 자리 문턱에 거울을 엎어 놓고 떠났다. 엎어 둔 거울은 아무도 비추지 않는다. 주인이 찾으러 와도 이쪽을 비추지 못한다.<br><br>물건 하나로 쥔 손, 쥔 버릇, 쥔 까닭까지 읽었다. 손바닥에 올려 놓으면 이제 물건이 먼저 말한다.`,
      ng:`짚는데 거울에 이쪽 등 뒤가 비친다. 일행이 앉아 있다. 하나가 더 있다. 등을 보이고.<br><br>거울을 엎었다. 돌아보지 않았다. 일행은 제 수 그대로다. 그런데 다들 등이 시리다고 했다.<br>엎어 둔 거울이 아침에 바로 놓여 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 주인 모를 물건이니 두고 간다.', k:'steady', dc:21,
      ok:`주인 모를 물건은 가져가지 않는다. 몇 안 되는 규칙이다.<br><br>거울을 바닥 가운데 놓고 짐을 쌌다. 떠날 때 돌아보니 거울이 조금 기울어 있다. 누가 집어 보다 놓은 것처럼.<br>거울은 따라오지 않았다.`,
      ng:`두고 일어섰는데 짐 속에서 달그락 소리가 난다. 거울이다.<br><br>세 번 꺼내 놓았다. 세 번 돌아왔다. 네 번째는 깨뜨렸다. 깨진 조각마다 이쪽 등 뒤가 비쳤다.<br>조각을 쓸어 담는 동안 손바닥을 여러 번 베었다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'A', t:'내려가는 길 — 두고 가는 선반',
  x:`계단 앞에 낮은 선반이 놓였다. 위에 물건이 하나씩. 신발 끈, 단추, 반지, 머리핀.<br><br>
    팻말이 있다. 「내려가는 사람은 하나를 두고 가세요.」<br>
    두고 간 것들이 하나같이 그 사람이 제일 아끼던 것으로 보인다. 다 보인다. 이건 손때가 많고, 이건 고친 자국이 있다.<br><br>
    주머니를 만졌다. 여기까지 모은 것들이 있다. 하나를 두고 가야 한다.`,
  o:[
    { l:'① 제일 좋은 것을 두고 간다.', k:'steady', dc:22, wake:1,
      ok:`주머니에서 제일 좋은 것을 꺼냈다. 여기서 주운 것 중 진짜 중의 진짜. 선반 빈자리에 놓았다.<br><br>아깝다. 손끝이 아리다. 계단을 내려가는데 발밑이 단단하다. 좋은 것을 두고 간 사람에게 계단은 짧다.<br>아래층에서 주머니를 털었다. 빈 자리에 다른 것이 들어 있다. 진짜는 아니다. 그런데 손에 익다. 처음 모은 조약돌이다. 오래전에 잃은 것이다.<br><br>모으는 것만큼 내려놓는 법을 아는 손이 됐다. 손에서 떠난 것도 목록에 남는다.`,
      ng:`꺼냈는데 손이 안 펴진다. 진짜는 놓기가 어렵다.<br><br>겨우 놓았다. 너무 오래 걸렸다. 선반이 그 망설임까지 받아 간다. 내려가는 동안 무엇을 두고 왔는지 자꾸 잊는다.<br>아래층에서 주머니를 털었다. 무엇이 비었는지 끝내 생각나지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 흉내 하나를 진짜처럼 두고 간다.', k:'luck', dc:23,
      ok:`칠한 금반지를 골랐다. 손바닥에 올려 한참 아끼는 척했다. 그리고 놓았다.<br><br>선반은 물건을 안 본다. 놓는 손을 본다. 놓는 손이 아까워하면 받는다. 이쪽 손은 아까워하는 척을 잘했다.<br>계단을 내려갔다. 아무 일도 없었다. 조금 미안했다.`,
      ng:`놓았는데 반지가 저절로 굴러 떨어진다. 안 받는다는 것이다.<br><br>다시 놓았다. 또 떨어진다. 계단 첫 칸이 한 칸 깊이 아래로 꺼진다. 두고 갈 것을 안 두면 계단이 대신 받아 간다.<br>결국 진짜를 놓았다. 손이 덜덜 떨렸다. 선반은 반지도 같이 가져갔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'기념품 창고 — 같은 인형 백 개',
  x:`기념품 창고 선반에 방글이 인형이 빼곡하다. 노란 해 얼굴, 그려 넣은 입. 백 개쯤.<br><br>
    다 같은 틀로 찍었다. 바느질 땀 수도 같다. 공장에서 나온 것이다.<br>
    같은 것들 사이에서 다른 하나를 찾는 게 평생 해 온 일이다.<br><br>
    하나가 다르다. 어디가 다른지는 아직 모른다. 그런데 손이 그쪽으로 간다.`,
  o:[
    { l:'① 다른 하나를 가려낸다.', k:'gaze', dc:22, wake:1,
      ok:`손이 멈춘 인형을 들었다. 손바느질이다. 땀이 고르지 않다. 공장 것이 아니다. 처음 만든 견본이다.<br><br>견본 등에 실밥 하나가 풀려 있다. 당기니 등이 열린다. 솜 대신 종이가 들었다. 처음 만들 때 쓴 도안이다. 한쪽에 층마다 창고 위치가 적혀 있다. 소품 담당 글씨다.<br>견본을 도로 닫아 맨 뒤에 놓았다. 나머지 백 개가 동시에 고개를 아주 조금 숙였다.<br><br>찍어 낸 것과 처음 만든 것을 손이 가른다. 같은 것 백 개 사이에서도 이제 하나가 먼저 손에 와 닿는다.`,
      ng:`들었는데 인형이 따뜻하다. 다른 것들은 차다. 안에 무엇이 들었다.<br><br>그려 넣은 입이 움직인다. 손가락을 문다. 이가 없는데 꽉 문다. 떼어 내는 데 한참 걸렸다.<br>내려놓자 인형 백 개가 동시에 이쪽을 향해 돌아앉았다. 창고를 나올 때까지.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 테이프 안 뜯긴 상자를 찾는다.', k:'luck', dc:22,
      ok:`선반 말고 바닥 상자를 봤다. 테이프가 안 뜯긴 상자가 하나 있다. 미개봉은 아무도 안 만졌다.<br><br>뜯었다. 인형이 아니다. 방청객 선물로 쓰던 간식 꾸러미다. 말린 고기 육포가 들었다. 포장 날짜 칸이 비었다.<br>선반 인형들은 이쪽을 안 봤다. 상자 쪽은 저들 몫이 아니다.`,
      ng:`뜯는데 안에서 인형 하나가 튀어나온다. 용수철 장난감이다. 웃는 얼굴이 코앞에서 흔들린다.<br><br>뒤로 넘어지며 선반에 등을 찧었다. 인형 열 개가 쏟아져 덮쳤다. 가볍다. 그런데 하나하나 팔을 벌려 안는다.<br>털어 내며 일어섰다. 옷에 노란 털이 잔뜩 붙었다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A1', t:'분장실 — 사인 수첩',
  x:`분장실 화장대 서랍에 수첩이 있다. 사인 수첩이다.<br><br>
    장마다 사인이 하나씩. 크레용 글씨, 볼펜 글씨. 아이들이 출연자에게 받은 게 아니다. 반대다. 출연자들이 아이들에게 받았다.<br>
    장마다 날짜와 이름. 그리고 작은 글씨로 「오늘의 친구」.<br><br>
    마지막 장이 비었다. 볼펜이 끼워져 있다.`,
  o:[
    { l:'① 제일 오래된 첫 장을 뜯어 간다.', k:'luck', dc:22,
      ok:`첫 장 날짜가 첫 방송 날이다. 첫 오늘의 친구. 첫 장은 언제나 제일 귀하다.<br><br>조심스레 뜯었다. 뜯긴 자리에서 수첩이 한숨 같은 소리를 낸다. 첫 장 뒷면에 방송국 지도가 연필로 그려져 있다. 아이가 그렸다. 어디로 도망치려 했는지.<br>지도 끝 동그라미가 비상계단이다. 그 아이는 거기까지 못 갔다. 이쪽은 갈 것이다.`,
      ng:`뜯는데 철이 단단하다. 힘을 주자 첫 장 크레용 사인이 번져 손가락에 묻는다.<br><br>문지를수록 손가락에 글씨가 된다. 첫 아이 이름이다.<br>그 이름이 하루 종일 손가락에 남았다. 이따금 손가락이 저절로 그 이름을 썼다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 마지막 장에 사인한다.', k:'bond', dc:23,
      doom:{ title:'사인 수첩', what:'오늘의 친구로 무대에 끌려 나갑니다', dc:18, sec:50,
        text:`볼펜을 쥐었다. 남의 수첩에 사인하는 건 처음이다. 이름을 썼다.<br><br>쓰자마자 거울 전구가 하나씩 켜진다. 스피커에서 언니 목소리가 난다. 사인해 줘서 고마워요. 이제 무대로 가요.<br>의자가 저절로 뒤로 밀린다. 하얀 장갑이 어깨를 잡는다. 손가락이 넷. 문 쪽으로 끈다. 다리가 따라간다.<br><br>사인은 그 자리에 있었다는 증거다. 평생 그런 증거를 모아 왔다. 이번엔 증거가 이쪽을 모은다.`,
        dieText:`분장실 서랍 속 사인 수첩이 한 장 늘었다.<br><br>마지막 장에 이름이 있다. 그 밑에 작은 글씨. 오늘의 친구.<br>그 뒤에 빈 장이 하나 새로 생겼다. 볼펜이 끼워져 있다.` },
      ok:`볼펜을 쥐었다. 이름 대신 물건에 다는 꼬리표를 그렸다. 번호와 날짜. 품목 칸에 「수첩」.<br><br>사인이 아니라 꼬리표다. 수첩을 모은 셈이다. 전구 하나가 켜지려다 꺼진다. 스피커가 지직거린다. 무엇을 불러야 할지 모른다.<br>수첩을 덮어 서랍 깊이 넣었다. 꼬리표가 붙은 수첩은 이제 이쪽 것이다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 수첩을 열지 않고 서랍째 닫는다.', k:'steady', dc:21,
      ok:`서랍을 닫았다. 열지 않은 수첩은 아무 장도 비지 않는다.<br><br>닫힌 서랍 안에서 볼펜 굴러가는 소리가 한 번 났다. 아무도 안 썼다. 분장실을 나왔다.`,
      ng:`닫는데 서랍이 저절로 다시 열린다. 수첩이 마지막 장으로 펼쳐져 있다.<br><br>다시 닫았다. 또 열린다. 몸으로 서랍을 막고 섰다. 서랍이 등을 밀었다.<br>일행이 끌어낼 때까지 서랍과 씨름했다. 허리가 결렸다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'A1', t:'소품 창고 — 1회 방송 탈',
  x:`소품 창고 맨 안쪽, 유리 상자 안에 방글이 탈 머리가 있다. 다른 탈들보다 색이 바랬다.<br><br>
    상자에 쪽지가 붙어 있다. 1회 방송 사용. 보존.<br>
    첫 회 물건을 보면 숨이 멎는다. 평생 이런 것을 찾아다녔다.<br><br>
    탈 눈구멍 안쪽이 아주 어둡다. 무엇이 안에서 이쪽을 보고 있는 것 같다.`,
  o:[
    { l:'① 눈구멍을 들여다본다.', k:'gaze', dc:23,
      doom:{ title:'1회 방송', what:'탈이 머리에 씌워져 숨이 막힙니다', dc:19, sec:45,
        text:`유리에 얼굴을 대고 눈구멍을 들여다봤다. 안이 어둡다. 아니다. 안에 눈이 있다. 이쪽을 본다.<br><br>뚜껑이 저절로 들린다. 탈이 떠오른다. 머리 위로. 내려온다. 씌워진다. 안쪽이 축축하고 따뜻하다. 오래 누가 쓰고 있던 탈이다.<br>숨이 막힌다. 눈구멍으로 창고가 보인다. 그려 넣은 입이 이쪽 입 대신 웃는다.<br><br>첫 회 물건은 첫 회 주인을 기억한다. 주인 자리가 비면 다음 머리를 찾는다.`,
        dieText:`소품 창고 유리 상자에 방글이 탈 머리가 들어 있다. 색이 조금 덜 바랬다.<br><br>쪽지가 붙어 있다. 1회 방송 사용. 보존.<br>그 밑에 한 줄이 더 붙었다. 착용자 교체.` },
      ok:`얼굴을 대기 전에 등불을 상자 뒤로 돌렸다. 빛이 탈 뒤에서 비친다. 눈구멍 안이 밝아진다.<br><br>안은 비었다. 대신 안쪽 천에 손글씨가 있다. 1회 출연자 이름. 그 밑으로 줄줄이 이름이 이어진다. 다 이 탈을 썼다.<br>상자를 열지 않고 돌아섰다. 첫 회 물건 앞에서 돌아선 건 처음이다. 손이 한참 떨렸다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 보존 목록에서 반출구를 찾는다.', k:'luck', dc:22,
      ok:`쪽지 밑에 소품 목록이 붙어 있다. 회차마다 쓴 소품. 마지막 회차는 아직 안 끝났다. 매일 늘어난다.<br><br>목록 귀퉁이에 출입 표가 있다. 「비상 반출구 — 선반 뒤.」 선반을 밀자 화물 승강기 문이 나온다. 고장 났지만 문틈으로 계단이 보인다.<br>선반 뒤 바닥에 굳은 꿀 단지가 있었다. 촬영용이 아니다. 누가 먹던 것이다.`,
      ng:`읽는데 목록 마지막 줄이 지금 늘어난다. 「소품 — 등불 든 사람.」<br><br>등불을 내려놓았다. 줄이 멈춘다. 등불 없이 창고를 나왔다. 어둠 속에서 몇 번이나 부딪혔다.<br>돌아보니 등불이 유리 상자 옆 선반에 올라가 있었다. 보존.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A1', t:'방청석 — 의자 밑 물건들',
  x:`방청석 의자 밑에 물건이 떨어져 있다. 의자마다 하나씩.<br><br>
    머리끈, 크레용, 사탕 껍질, 실내화 한 짝, 이름표. 아이들이 흘린 것이다.<br>
    손이 근질거린다. 다 모으면 한 줄이 된다.<br><br>
    방청석 입구에 분실물 상자가 있다. 비었다. 상자에 적혀 있다. 찾아가세요.`,
  o:[
    { l:'① 하나씩 주워 분실물 상자에 넣는다.', k:'bond', dc:22, wake:1,
      ok:`의자를 따라 허리를 숙였다. 하나씩 주웠다. 한 개도 주머니에 안 넣었다. 다 분실물 상자에 넣었다. 이름표는 이름이 위로 가게.<br><br>마지막 하나를 넣자 빈 의자들이 아주 조금 들썩인다. 찾으러 온 것이다. 보이지 않는 손들이 상자를 뒤진다. 저마다 하나씩.<br>상자가 다 비었을 때 바닥에 꿀 사탕 한 봉이 남았다. 고맙다는 것이다.<br><br>모으는 손이 돌려주는 손이 됐다. 물건을 제자리에 보내는 일도 모으는 일이라는 걸 그날 알았다.`,
      ng:`줍는데 이름표 하나가 손에 붙는다. 이름 자리에 이쪽 이름이 적혀 있다.<br><br>상자에 넣었다. 빈 의자 하나가 들썩인다. 이쪽 자리라는 듯이. 보이지 않는 손이 소매를 잡아 그 의자로 이끈다.<br>뿌리치고 나왔다. 소매 단추가 떨어졌다. 그 단추는 의자 밑에 남았다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 값나가는 것 하나만 챙긴다.', k:'luck', dc:22,
      ok:`대부분 잡것이다. 한 의자 밑 동전만 다르다. 옛날 은이다. 깨물어 보니 이가 들어간다.<br><br>주웠다. 은은 주인을 안 탄다. 빈 의자들이 아무도 안 움직였다.<br>동전 뒷면에 웃는 해가 새겨져 있다. 방송국 기념 주화다. 가장자리에 아주 작게 적혀 있다. 재입장권. 주머니 제일 깊은 데 넣었다. 쓸 일은 없을 것이다.`,
      ng:`주웠는데 차갑다. 은이 아니다. 손바닥에서 동전이 녹아 물이 된다.<br><br>물이 손금을 따라 흐른다. 손바닥에 동그란 도장이 남는다. 웃는 해.<br>문질러도 안 지워진다. 손이 하루 종일 차가웠다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A1', t:'테이프 보관실 — 빠진 회차',
  x:`테이프 보관실 선반에 회차 번호대로 테이프가 꽂혀 있다. 일 회부터. 빠짐없이.<br><br>
    빠진 칸은 못 견딘다. 눈이 저절로 번호를 훑는다.<br>
    한 칸이 빈다. 사백십이 회. 앞뒤는 다 있다.<br><br>
    배낭이 이상하게 무겁다. 끈을 풀어 보니 맨 위에 테이프 하나가 들어 있다. 사백십이.`,
  o:[
    { l:'① 목록과 맞춰 결번으로 막는다.', k:'gaze', dc:22,
      ok:`벽 목록을 봤다. 사백십이 회. 제목 칸이 비었다. 방송 안 된 회차다.<br><br>테이프 딱지에 「녹화 중지」. 찍다가 멈춘 회차는 끝나지 않은 회차다.<br>꽂지 않았다. 빈칸에 쪽지를 끼웠다. 「결번」. 결번은 채우지 않는 번호다. 테이프는 쪽지 옆 바닥에 내려놓았다. 배낭이 가벼워졌다.`,
      ng:`맞추는데 목록 사백십이 칸에 제목이 지금 쓰인다. 「오늘의 친구 — 보관실 편.」<br><br>천장 스피커에서 박수가 난다. 녹화가 다시 시작됐다. 테이프를 던지고 나왔다.<br>배낭이 무겁다. 다시 열어 보니 테이프가 또 들어 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 빈칸에 끝까지 밀어 꽂는다.', k:'luck', dc:22, wake:1,
      ok:`빈칸에 꽂았다. 끝까지 밀어 넣었다. 선반 줄이 빈틈없어진다.<br><br>빠진 게 없으면 찾으러 오는 것도 없다. 보관실 공기가 가라앉는다. 선반 끝에서 무엇이 길게 숨을 내쉬었다. 다 모였다는 듯이.<br>배낭 밑에 언제 들어갔는지 모를 말린 버섯 봉지가 있었다. 테이프를 데려다준 값이다.<br><br>빈칸을 채워 남의 수집을 끝내 주었다. 모으는 일에는 끝을 맺어 주는 손도 있어야 한다는 걸 손이 알았다.`,
      ng:`꽂는데 안 들어간다. 앞뒤 테이프가 칸을 막는다.<br><br>억지로 밀었다. 선반이 기울며 테이프 수백 개가 머리 위로 쏟아진다. 풀린 띠가 팔에 감긴다.<br>빠져나오는 데 한참 걸렸다. 손목에 띠 자국이 감겼다. 띠에서 박수 소리가 작게 났다.`,
      win:{ exp:22, dream:3, item:'야생 버섯' }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A2', t:'분실물함 — 명찰 무더기',
  x:`복도 끝 분실물함이 반쯤 물에 잠겼다. 뚜껑이 열려 있다.<br><br>
    안에 명찰이 수북하다. 다 같은 모양이다. 학년, 반, 이름. 수놓은 실이 물에 불었다.<br>
    같은 것 무더기를 보면 손이 들어간다. 이 중 하나는 다르다. 늘 그렇다.<br><br>
    분실물함 옆 벽에 적혀 있다. 주인 없는 명찰은 점호 때 불러 줍니다.`,
  o:[
    { l:'① 다른 하나를 가려낸다.', k:'gaze', dc:22, wake:1,
      ok:`손을 넣어 실의 결을 짚었다. 다 같은 손이 수놓았다. 사감 손이다. 하나만 다르다. 땀이 크고 서툴다. 아이가 제 손으로 수놓았다.<br><br>제 이름을 제가 수놓은 아이는 학교가 단 명찰을 떼어 냈다. 그 명찰 뒷면에 바늘로 긁은 글씨가 있다. 「서쪽 창은 안 잠김.」<br>그 명찰만 물에 띄워 서쪽으로 보내고 나머지는 그대로 두었다. 서쪽 창은 정말 안 잠겨 있었다.<br><br>남이 단 이름과 제가 단 이름을 손끝이 가른다. 무더기 속에서 하나를 집는 손이 이제 망설이지 않는다.`,
      ng:`짚는데 명찰 실이 풀려 손가락마다 감긴다. 이름이 손가락에 수놓아진다.<br><br>손을 뺐다. 실이 길게 딸려 나온다. 끊는 데 한참 걸렸다. 손가락마다 실 자국이 반지처럼 남았다.<br>위층에서 점호가 시작됐다. 손가락이 저절로 움찔거렸다. 대답하려는 것처럼.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 명찰 밑을 더듬어 숨긴 것을 찾는다.', k:'luck', dc:22,
      ok:`무더기 밑을 더듬었다. 분실물함엔 늘 명찰 말고 다른 것도 있다. 깡통이 걸린다. 뚜껑이 꼭 닫혔다.<br><br>말린 생선포가 들었다. 누가 숨겨 둔 간식이다. 잃어버린 게 아니다. 숨긴 것이다.<br>분실물함은 숨기기 좋은 데다. 남의 분실물은 아무도 안 뒤진다. 모으는 사람 말고는.`,
      ng:`더듬다 손이 무엇을 잡았다. 손이다. 작다. 차다. 바닥에서 이쪽 손을 잡는다.<br><br>찾았다는 듯이 꽉 쥔다. 잃어버린 것이 이쪽 손인 것처럼. 일행이 팔을 붙들고 당겼다.<br>손을 빼냈다. 손등에 작은 손자국이 시퍼렇다.`,
      win:{ exp:18, dream:3, item:'민물고기' }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A2', t:'과학실 — 표본병',
  x:`과학실 선반에 유리병이 줄지어 있다. 뿌연 물에 물고기, 개구리, 도롱뇽이 떠 있다.<br><br>
    병마다 이름표. 이름과 채집 날짜. 표본병 이름표는 하나하나 읽게 된다.<br>
    과학실도 물에 잠겼다. 병 밖 물과 병 안 물이 같은 높이다.<br><br>
    맨 위 칸 큰 병 하나에 이름표가 없다. 병 안이 어둡다. 뚜껑이 반쯤 돌아가 있다.`,
  o:[
    { l:'① 살아 있는 것을 가려낸다.', k:'luck', dc:22,
      ok:`병을 하나씩 들여다봤다. 다 굳었다. 하나만 아가미가 움직인다. 붕어다. 이름표 날짜가 지난주다. 누가 최근에 넣었다.<br><br>병을 열어 꺼냈다. 살아 있다. 표본이 아니라 저장이었다. 누가 먹으려고 넣어 둔 것이다.<br>병을 닫아 제자리에 두고 이름표는 떼어 가졌다. 채집자 칸 이름은 아직 점호에 안 불린 이름이다.`,
      ng:`들여다보는데 모든 병 속 눈이 동시에 이쪽으로 돈다.<br><br>병들이 선반에서 조금씩 미끄러진다. 하나가 떨어져 깨졌다. 뿌연 물이 손에 튄다. 손등이 화끈하다.<br>과학실을 나와 한참 손을 씻었다. 냄새가 안 빠졌다.`,
      win:{ exp:18, dream:3, item:'민물고기' }, lose:{ hp:-24, spirit:-20 } },
    { l:'② 이름표 없는 큰 병 뚜껑을 마저 연다.', k:'gaze', dc:23,
      doom:{ title:'이름표 없는 병', what:'표본병 속으로 끌려 들어갑니다', dc:19, sec:45,
        text:`뚜껑을 마저 돌렸다. 이름표 없는 표본은 제일 못 참는 것이다. 무엇인지 알아야 한다.<br><br>병 안 어둠이 움직인다. 손이 나온다. 병보다 크다. 손목을 잡는다. 병 입구가 넓어진다. 팔이 들어간다. 어깨가 들어간다.<br>병 안 물은 바깥 물보다 차다. 몸이 병 안으로 끌려 들어간다. 병 안이 과학실보다 넓다.<br><br>이름표 없는 병은 이름을 기다리는 병이다. 이제 이름이 생긴다.`,
        dieText:`과학실 맨 위 칸 큰 병에 이름표가 붙었다. 낯익은 이름이다. 채집 날짜 오늘.<br><br>병 안이 어둡다. 뚜껑이 꼭 닫혔다.<br>그 옆에 이름표 없는 병이 하나 새로 놓였다. 뚜껑이 반쯤 돌아가 있다.` },
      ok:`뚜껑을 돌리지 않았다. 병 둘레를 손바닥으로 쓸어 무게를 쟀다. 무겁다. 쓸 때마다 안에서 무엇이 손바닥 자리를 따라온다.<br><br>뚜껑을 반대로 돌려 꽉 잠갔다. 안에서 무엇이 뚜껑을 두드린다. 똑똑. 이름표 자리에 손으로 적었다. 「열지 말 것.」<br>이름표를 다는 것은 그 물건을 제자리에 앉히는 일이다. 병이 조용해졌다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 병은 두고 선반 밑 채집 상자를 뒤진다.', k:'sense', dc:22,
      ok:`선반 밑 채집 상자에 그물, 핀셋, 기름종이 봉투가 있다. 봉투마다 마른 풀이 들었다. 식물 표본이다. 말린 산나물이다. 먹을 수 있다.<br><br>표본도 굶주린 데서는 반찬이 된다. 이름표째 챙겼다.`,
      ng:`끌어내는데 상자 밑에 해파리처럼 투명한 것이 붙어 있다.<br><br>손바닥에 달라붙었다. 떼어 낼수록 늘어난다. 한참 문질러 떼어 냈다.<br>손바닥이 쓰라리고 붉게 부풀었다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A2', t:'사물함 — 병뚜껑 모으던 아이',
  x:`복도 사물함 하나가 열려 있다. 물에 반쯤 잠겼다.<br><br>
    안에 깡통이 줄지어 있다. 병뚜껑, 우표, 구슬, 매미 껍질. 칸마다 나눠 두었다. 한눈에 안다. 이 사물함 주인도 모으는 사람이다.<br>
    문 안쪽에 목록이 붙어 있다. 아이 글씨다. 「아직 없는 것.」 줄이 길다.<br><br>
    사물함 앞 물속에 작은 그림자가 서 있다. 지켜보고 있다.`,
  o:[
    { l:'① 목록의 빈칸 하나를 채워 준다.', k:'luck', dc:22, wake:1,
      ok:`목록을 읽었다. 「파란 병뚜껑. 외국 우표. 은 단추.」 주머니에 은 단추가 있다. 아까 주운 진짜다.<br><br>칸에 넣고 목록에서 은 단추 줄을 손톱으로 그어 지웠다. 그림자가 가까이 와서 사물함을 오래 들여다본다.<br>물러나며 그림자가 맨 아래 깡통을 이쪽으로 민다. 꿀 사탕이 반쯤 들었다. 모으는 사람끼리의 답례다.<br><br>남의 목록을 읽고 그 빈칸을 채웠다. 그 손이 이제 제 목록보다 남의 목록에 먼저 간다.`,
      ng:`넣으려는데 그림자가 손을 뻗는다. 단추 말고 손목을 잡는다. 목록 맨 아래 줄을 가리킨다.<br><br>「어른 손.」 손목을 비틀어 뺐다. 단추가 물속으로 떨어진다. 그림자가 단추를 주워 들고 이쪽을 오래 봤다.<br>손목에 작은 손가락 자국 다섯 개가 남았다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 그림자가 안 볼 때 가져간다.', k:'hide', dc:23,
      ok:`그림자가 고개를 돌릴 때를 기다렸다. 위층에서 점호가 울린다. 그림자가 위를 본다.<br><br>그 틈에 맨 아래 깡통을 집었다. 꿀 사탕이 반쯤 들었다. 사물함 문을 조용히 닫았다.<br>모으는 사람이 모으는 사람의 것을 훔쳤다. 이 업에서 제일 부끄러운 일이다. 깡통이 내내 무거웠다.`,
      ng:`집는데 그림자가 돌아본다. 물속에서 눈이 하얗다.<br><br>사물함 문이 쾅 닫히며 손가락을 찧었다. 그림자가 문에 등을 대고 선다. 지킨다.<br>손톱 둘이 검게 죽었다. 깡통은 못 가져왔다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A2', t:'사감실 — 열쇠함',
  x:`사감실 벽에 열쇠함이 걸려 있다. 호실마다 열쇠가 고리에 걸렸다.<br><br>
    일 호실부터 다 걸려 있다. 고리 하나만 비었다. 이십일 호실.<br>
    빈 고리를 보면 그 열쇠가 어디 있는지 궁금해 못 견딘다.<br><br>
    열쇠함 밑 물속에서 짤랑 소리가 난다. 누가 열쇠를 흔든다.`,
  o:[
    { l:'① 제일 닳은 열쇠로 다른 길을 연다.', k:'gaze', dc:22,
      ok:`빈 고리는 두고 걸린 열쇠들을 봤다. 제일 닳은 것이 사감실 쪽문 열쇠다. 사감이 제일 자주 쓴 문.<br><br>그 열쇠로 사감실 뒤 쪽문을 열었다. 좁은 계단이 아래로 이어진다. 사감만 다니던 길이다. 물이 덜 찼다.<br>내려가며 들었다. 짤랑 소리가 사감실 안을 한참 돌았다. 이십일 호실 열쇠를 들고.`,
      ng:`고르는데 열쇠들이 고리에서 저절로 흔들린다. 물속 소리와 박자가 맞는다.<br><br>사감실 문이 열린다. 젖은 발소리가 들어온다. 다들 책상 밑에 숨었다.<br>발소리가 열쇠함 앞에서 오래 섰다. 열쇠를 세는 소리. 하나 모자란다고 중얼거리는 소리. 떠날 때까지 숨을 참았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-14, spirit:-16 } },
    { l:'② 물속 짤랑 소리를 더듬어 빈 열쇠를 찾는다.', k:'luck', dc:22,
      ok:`물속에 손을 넣어 소리를 더듬었다. 열쇠 하나가 손가락에 걸린다. 이십일. 뺐다. 물속에서 손 하나가 같이 놓았다. 순순히.<br><br>빈 고리에 걸었다. 열쇠함이 다 찼다. 사감실 공기가 바뀐다. 사감이 늘 확인하던 것이 확인됐다.<br>열쇠함 밑 서랍이 저절로 한 칸 열렸다. 압수한 말린 고기 꾸러미가 들어 있었다. 상이다.`,
      ng:`더듬는데 열쇠 대신 손을 잡았다. 열쇠를 쥔 손이다. 놓지 않는다.<br><br>당긴다. 팔이 물속으로 들어간다. 반대 손으로 열쇠함을 잡고 버텼다. 열쇠함이 벽에서 반쯤 뜯겼다.<br>손이 놓았다. 열쇠는 안 주고 갔다. 팔이 어깨까지 저렸다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'A2', t:'수영장 — 바닥의 동전',
  x:`수영장 바닥에 동전이 깔려 있다. 물이 맑아 다 보인다.<br><br>
    아이들이 소원을 빌며 던진 동전이다. 수백 닢. 대부분 흔한 동전이다.<br>
    눈에 하나가 들어온다. 맨 깊은 쪽 배수구 옆. 옛날 은전이다. 진짜다.<br><br>
    배수구 쇠살 너머가 어둡다. 물이 아주 천천히 그쪽으로 빨려 든다.`,
  o:[
    { l:'① 얕은 쪽 동전 중에서 진짜를 고른다.', k:'luck', dc:22,
      ok:`깊은 쪽은 접었다. 얕은 쪽 동전을 훑었다. 흔한 것들 사이에 무게가 다른 게 하나 있다. 놋이다. 오래된 기념 주화다.<br><br>집어 왔다. 은전만큼은 아니다. 대신 숨이 남았다.<br>동전 밑에 깔려 있던 것도 하나 딸려 왔다. 비닐에 싼 소금 한 덩이. 아이들이 소원 값으로 같이 넣은 것이다.`,
      ng:`훑다가 얕은 쪽이 생각보다 깊다. 발이 안 닿는다.<br><br>물을 먹었다. 허우적대는데 바닥 동전들이 떠오른다. 얼굴 쪽으로. 소원들이 떠오른다.<br>일행이 끌어올렸다. 입안에 동전 하나가 들어 있었다. 뱉었다. 이가 시렸다.`,
      win:{ exp:18, dream:3, item:'소금 덩이' }, lose:{ hp:-26, mind:-14 } },
    { l:'② 깊은 쪽 은전을 건진다.', k:'gaze', dc:23,
      doom:{ title:'배수구 은전', what:'배수구 쪽으로 빨려 끌려갑니다', dc:19, sec:45,
        text:`숨을 크게 쉬고 깊은 쪽으로 내려갔다. 은전이 반짝인다. 손을 뻗었다. 집었다.<br><br>집는 순간 배수구 물살이 세진다. 은전 쥔 손이 쇠살 쪽으로 끌린다. 쇠살 틈에서 손가락들이 나와 이쪽 손을 감싼다. 은전을 같이 쥔다.<br>소원 값을 가져가는 손이다. 놓지 않는다. 몸이 쇠살에 붙는다. 숨이 줄어든다. 위가 멀다.<br><br>진짜를 보면 손이 먼저 간다. 그 손이 진짜를 쥔 채 놓지 못한다.`,
        dieText:`수영장 바닥에 동전이 깔려 있다. 물이 맑아 다 보인다.<br><br>배수구 옆에 은전이 하나 반짝인다. 그 옆에 한 닢이 더 있다. 흔한 동전이다.<br>쇠살 너머에서 물이 아주 천천히 빨려 든다.` },
      ok:`내려가며 은전을 정면으로 안 봤다. 배수구 물살이 부르는 쪽을 비켜 옆으로 다가갔다.<br><br>손가락 하나로 은전을 튕겨 쇠살 반대쪽으로 굴렸다. 집지 않았다. 굴러간 은전을 물살 밖에서 주웠다. 쇠살 틈 손가락들이 빈 데를 쥐었다 폈다.<br>올라와 숨을 몰아쉬며 은전을 봤다. 진짜다. 손바닥이 아직 떨린다.`,
      win:{ exp:22, dream:4 } }
  ] }

]);

// ==========================================
// 🥣 거지 (beggar) · 내공
// ==========================================
kJob('beggar', 'A', [

{ at:'A', t:'입구 — 그릇 속 긁힌 표식',
  x:`문턱 안쪽에 그릇을 내려놓았다. 이 빠진 사기 그릇. 들어가는 데마다 하는 버릇이다.<br><br>
    잠깐 기다리는데 그릇 속에서 사각 소리가 난다. 아무도 없다.<br>
    들여다보니 그릇 바닥에 긁힌 자국이 생겼다. 방금. 동그라미 하나, 그 안에 가위표.<br><br>
    같은 업끼리 쓰는 표식이다. 「여기 주인 있음. 얻어먹지 말 것.」`,
  o:[
    { l:'① 표식을 끝까지 읽는다.', k:'luck', dc:22, wake:1,
      ok:`그릇을 등불에 기울였다. 가위표 끝 한 줄이 길다. 길게 끈 줄은 「그래도 지나갈 길은 있음」이다. 끝이 왼쪽으로 휘었다.<br><br>왼쪽 벽을 따라 걸었다. 벽 밑 돌에 같은 표식이 있다. 그다음 돌에도. 먼저 간 같은 업이 길을 그어 두었다. 끝에서 바위틈 물병 하나를 찾았다. 표식 그은 이가 남긴 몫이다.<br><br>얼굴 모르는 손이 여기까지 닿아 있었다. 흩어진 표식들이 한 줄로 읽히기 시작했다. 바닥을 보던 눈이 길을 잇는 눈이 됐다.`,
      ng:`기울이는데 표식이 바뀐다. 가위표 하나가 더 그어진다. 그릇 바닥이 금 가는 소리가 난다.<br><br>가위표 둘은 「주인이 보고 있음」이다. 그릇을 집어 품에 넣었다. 등 뒤에서 누가 혀를 찼다.<br>평생 들고 다닌 그릇에 금이 하나 늘었다. 마음이 오래 서늘했다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 내공을 끌어올려 주인의 기척을 더듬는다.', k:'sense', dc:22, cost:{ qi:25 },
      ok:`숨을 가라앉히고 내공을 귀와 코끝으로 끌어올렸다. 먼지 냄새, 돌 냄새. 그 밑에 아주 엷게 오래된 사람 냄새. 문턱 바로 위 천장이다.<br><br>천장에 무엇이 거꾸로 붙어 있다. 이쪽을 내려다본다. 고개를 들지 않았다. 기척만 쟀다. 그것은 그릇만 본다.<br>그릇을 문턱에 두고 지나갔다. 주인 있는 데서는 그릇을 내준다. 천장의 것이 그릇 쪽으로 천천히 내려왔다.`,
      ng:`끌어올리는데 천장에서 무엇이 이쪽 내공을 마신다. 숨이 거꾸로 빨려 올라간다.<br><br>기를 끊고 엎드렸다. 가슴이 결렸다. 고개를 들자 천장은 비어 있다. 그릇도 비었다.<br>그릇 바닥에 손가락 자국 하나가 찍혀 있었다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 눈 마주치지 않는 법',
  x:`복도 저쪽에서 무엇이 걸어온다. 키가 천장에 닿는다. 걸음마다 멈춰 고개를 숙인다. 벽 쪽 사람 얼굴을 하나씩 들여다본다.<br><br>
    일행이 떤다. 숨을 데가 없다.<br>
    평생 사람들이 이쪽을 안 보고 지나가는 걸 봤다. 안 보이는 법은 숨는 게 아니다. 볼 것 없어 보이는 것이다.<br><br>
    그것이 세 걸음 앞까지 왔다.`,
  o:[
    { l:'① 그릇을 내밀고 고개를 숙인다.', k:'hide', dc:22, wake:1,
      ok:`벽에 등을 대고 쪼그려 앉았다. 그릇을 내밀었다. 고개를 숙였다. 일행에게도 손짓했다. 다들 쪼그렸다.<br><br>그것이 멈춘다. 고개를 숙인다. 그릇이 보인다. 그릇만 보인다. 동냥하는 얼굴은 아무도 들여다보지 않는다. 그것도 그랬다. 잠시 머물다 지나갔다.<br>그릇 안에 꿈결 몇 알이 떨어져 있다. 그것이 넣고 갔다.<br><br>안 보이는 법이 처음으로 기술이 됐다. 몸을 낮추는 게 아니라 눈길을 비키게 하는 법이 몸에 들었다.`,
      ng:`쪼그렸는데 일행 하나가 너무 떤다. 이가 딱딱 맞부딪친다.<br><br>그것이 그 소리에 멈춘다. 고개를 숙여 그 사람을 오래 들여다본다. 그 사람이 눈을 감고 버텼다.<br>그것이 지나간 뒤 그 사람 눈썹이 하얗게 셌다. 다들 한동안 말이 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-24 } },
    { l:'② 내공으로 숨을 죽이고 돌처럼 버틴다.', k:'steady', dc:23, cost:{ qi:28 },
      ok:`내공을 아랫배에 모으고 숨을 아주 길게 늘였다. 맥이 느려진다. 몸이 식는다. 돌처럼.<br><br>그것이 앞에서 고개를 숙인다. 숨이 없는 것은 얼굴이 아니다. 지나간다. 일행 하나하나 앞에서도 멈췄다. 다들 숨을 참았다.<br>숨을 되찾는 데 한참 걸렸다. 손끝이 하얗게 식어 있었다.`,
      ng:`늘이는데 배가 꼬르륵 운다. 빈속이다.<br><br>그것이 앞에서 멈춘다. 배 쪽으로 고개를 숙인다. 소리 나는 데를 오래 본다. 기가 흩어진다.<br>그것이 지나간 뒤에도 배가 차가웠다. 그 뒤로 한참 허기가 안 느껴졌다. 그게 더 무서웠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 고개를 들어 얼굴을 확인한다.', k:'gaze', dc:23,
      doom:{ title:'들여다보는 것', what:'눈이 마주쳐 복도 끝으로 끌려갑니다', dc:18, sec:50,
        text:`고개를 들었다. 무엇인지 알아야 피한다. 그것이 고개를 숙인 채 내려다본다. 얼굴이 없다. 얼굴 자리에 눈만 있다. 수십 개.<br><br>눈이 마주쳤다. 한꺼번에. 그것이 반가워한다. 긴 팔이 내려와 턱을 받친다. 얼굴을 더 잘 보려고. 들어 올린다. 발이 바닥에서 뜬다.<br>복도 끝 쪽으로 데려간다. 벽마다 얼굴이 붙어 있다. 다 눈을 뜨고 있다.<br><br>평생 남이 안 봐 주는 쪽에 살았다. 처음으로 무엇이 이쪽을 정성껏 봤다.`,
        dieText:`복도 벽에 얼굴이 줄지어 붙어 있다.<br><br>새 얼굴 하나가 눈을 뜨고 있다. 수염이 덥수룩하다.<br>저쪽에서 키 큰 것이 걸어온다. 걸음마다 멈춰 고개를 숙인다.` },
      ok:`고개를 들되 눈은 그것의 발에 두었다. 눈을 내리깔고도 다 볼 줄 안다. 발이 셋이다. 셋째 발은 늘 왼쪽으로 돈다.<br><br>그것이 왼쪽으로 돌 때 오른쪽으로 빠졌다. 일행을 하나씩 끌고. 그것이 고개를 숙인 채 빈 벽을 들여다봤다.<br>끝까지 얼굴은 안 봤다. 볼 필요가 없었다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'쉬는 자리 — 고수레',
  x:`쉬는 자리에서 먹을 것을 꺼냈다. 일행이 허겁지겁 손을 뻗는다.<br><br>
    먹기 전에는 늘 한 점을 떼어 어둠 쪽으로 던진다. 고수레. 길에서 굶어 죽은 것들 몫이다. 배운 적은 없다. 길에서 저절로 익혔다.<br>
    오늘은 어둠 쪽에 기척이 많다. 등불 밖에서 무엇들이 먹는 소리를 듣는다.<br><br>
    일행은 고수레를 모른다.`,
  o:[
    { l:'① 다 같이 한 점씩 고수레를 한다.', k:'luck', dc:22,
      ok:`"먹기 전에 한 점." 각자 한 점씩 떼어 어둠에 던지게 했다. 이쪽이 먼저.<br><br>떨어진 데마다 받아 가는 소리가 난다. 조용히. 고맙다는 소리는 없다. 원래 없다. 그런데 등불 밖 기척이 하나씩 물러간다.<br>먹고 나서 보니 문턱에 말린 고기 한 줄이 놓여 있다. 받은 쪽이 돌려준 몫이다. 길에서 굶어 죽은 것들도 염치는 있다.`,
      ng:`던지게 했는데 일행 하나가 제 몫을 안 뗀다. 배가 고프다고.<br><br>그 사람이 먹는 동안 기척이 그 사람 등 뒤로 모인다. 숟가락이 떨린다. 먹은 것이 목에 걸린다.<br>등을 두드려 뱉게 하고 뱉은 것을 어둠에 던졌다. 기척이 그걸 받아 갔다. 그 사람은 밤새 체했다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-16 } },
    { l:'② 등불을 키우고 빨리 먹는다.', k:'steady', dc:22,
      ok:`고수레는 하지 않았다. 등불 심지를 높이고 다들 바짝 붙게 했다. 빨리 먹고 빨리 싸게.<br><br>기척이 불빛 안으로 들어오지 못하고 맴돈다. 먹는 소리를 듣기만 한다. 다 먹고 일어설 때까지 등불이 버텼다.<br>나오며 혼자 남은 빵 껍질을 어둠에 던졌다. 버릇이다.`,
      ng:`심지를 높였는데 기름이 빨리 닳는다. 먹는 중에 불빛이 줄어든다.<br><br>기척이 줄어든 불빛만큼 한 걸음씩 들어온다. 다들 먹던 것을 쥔 채 굳었다.<br>먹은 것보다 남긴 것이 많았다. 남긴 것은 다 없어져 있었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A', t:'빈방 — 따뜻한 자리',
  x:`잘 곳을 찾았다. 빈방이다. 바닥이 차다.<br><br>
    한구석만 바닥이 따뜻하다. 사람 하나 누울 만큼. 누가 방금 일어난 자리처럼.<br>
    평생 남의 처마 밑에서 잤다. 처마 밑에도 주인이 있다. 따뜻한 자리는 대개 남의 자리다.<br><br>
    일행이 그 자리로 간다. 춥다고.`,
  o:[
    { l:'① 아무도 안 쓰는 찬 자리를 찾는다.', k:'sense', dc:22,
      ok:`일행을 붙들었다. 방을 한 바퀴 돌며 바닥에 손을 댔다. 제일 차고 먼지 많은 자리. 아무도 안 쓴 자리다.<br><br>거기 짚을 깔고 등을 맞대게 했다. 춥다. 그래도 남의 자리는 아니다.<br>새벽에 따뜻한 자리 쪽에서 누가 눕는 소리가 났다. 길게 숨을 내쉬는 소리. 제자리에 돌아온 소리다.`,
      ng:`찾는데 방 전체가 따뜻해진다. 자리 주인이 방 전체를 쓴다.<br><br>어디 누워도 남의 자리다. 다들 앉은 채로 밤을 샜다. 졸 때마다 누가 등을 밀었다. 비켜 달라는 듯이.<br>아침에 다들 등에 손자국이 찍혀 있었다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 문가 찬 바닥에서 내공을 돌려 버틴다.', k:'steady', dc:23, cost:{ qi:30 },
      ok:`문가 찬 바닥에 가부좌를 틀고 내공을 돌렸다. 배꼽 밑에서 열이 인다. 손발 끝까지 데웠다.<br><br>옆에 일행을 하나씩 붙여 앉혔다. 등에서 나오는 열을 다들 나눠 쬐었다. 따뜻한 자리는 아무도 안 썼다.<br>새벽에 그 자리 쪽에서 누가 일어나 이쪽을 한참 내려다봤다. 남의 자리를 탐하지 않는 손님을 보는 눈이었다.`,
      ng:`돌리는데 기가 찬 바닥으로 새어 나간다. 바닥이 기를 마신다.<br><br>몸이 더 식는다. 결국 따뜻한 자리를 곁눈질했다. 그 순간 자리 위 공기가 일렁였다. 누가 이쪽을 보고 웃는다.<br>밤새 기침을 했다. 가슴이 결렸다.`,
      win:{ exp:20, dream:3, hp:8 }, lose:{ hp:-24, mind:-16 } },
    { l:'③ 따뜻한 자리에 먼저 눕는다.', k:'luck', dc:23,
      doom:{ title:'따뜻한 자리', what:'자리 주인에게 바닥 밑으로 끌려 들어갑니다', dc:18, sec:50,
        text:`일행보다 먼저 누웠다. 따뜻한 자리를 먼저 차지해 본 건 처음이다. 따뜻하다. 정말 따뜻하다.<br><br>등 밑에서 무엇이 꿈틀한다. 바닥이 아니다. 누군가의 가슴이다. 그 위에 누운 것이다. 밑에서 팔이 올라와 이쪽을 안는다. 따뜻하게.<br>바닥이 물러진다. 몸이 가라앉는다. 안은 팔이 바닥 밑으로 당긴다. 제자리로.<br><br>남의 처마 밑에서 평생 잤다. 남의 품에서 잔 적은 없다. 처음이자 마지막이다.`,
        dieText:`빈방 한구석만 바닥이 따뜻하다.<br><br>사람 둘이 누울 만큼 넓어졌다.<br>바닥에서 숨소리가 난다. 둘이다. 박자가 맞다.` },
      ok:`누웠다가 바로 굴러 나왔다. 등 밑에서 무엇이 꿈틀하는 걸 느끼자마자.<br><br>누웠던 자리에서 팔 하나가 올라와 허공을 안는다. 한참 안고 있다가 내려간다.<br>그 자리 위에 그릇을 엎어 두었다. 「주인 있음」. 일행은 그쪽을 안 보고 잤다. 그릇 밑이 밤새 따뜻했다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'계단 — 막대기 끝',
  x:`계단이 아래로 끝없이 어둡다. 등불이 세 칸밖에 못 비춘다.<br><br>
    막대기를 들었다. 앞을 툭툭 친다. 눈먼 거지들이 길을 걷는 법이다. 같이 빌어먹던 노인에게 배웠다.<br>
    끝이 돌에 닿는 소리, 나무에 닿는 소리, 비어 있는 소리. 다 다르다.<br><br>
    넷째 칸에서 막대기 끝이 무엇 물렁한 것에 닿는다. 소리가 안 난다.`,
  o:[
    { l:'① 막대기 소리로 계단을 읽는다.', k:'luck', dc:22, wake:1,
      ok:`물렁한 칸은 건너뛰었다. 다음 칸, 다음 칸을 쳤다. 돌 소리, 돌 소리, 빈 소리. 빈 소리 칸도 건넜다.<br><br>일행을 막대기 뒤에 한 줄로 세웠다. 막대기가 디딘 데만 디디게. 계단 밑에 닿았다. 등 뒤 넷째 칸에서 무엇이 막대기 끝 닿은 자리를 핥는 소리가 났다.<br><br>막대기 끝이 눈이 됐다. 손바닥에 닿는 떨림으로 어둠을 읽는다. 노인의 걸음이 이제 손에 들었다.`,
      ng:`건너뛰는데 다음 칸도 물렁하다. 그다음도. 물렁한 것이 따라 내려온다.<br><br>막대기 끝을 문다. 당긴다. 놓쳤다. 막대기가 어둠 속으로 끌려 들어갔다.<br>손으로 더듬어 내려갔다. 손바닥이 계단 모서리에 다 까졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 막대기에 내공을 실어 친다.', k:'break', dc:23, cost:{ qi:28 },
      ok:`막대기에 내공을 실었다. 끝이 무거워진다. 넷째 칸 물렁한 것을 내리쳤다.<br><br>물렁한 것이 움츠러들어 계단 틈으로 빨려 들어간다. 막대기 끝이 돌에 닿는다. 딱. 제대로 된 소리다.<br>소리가 안 나는 데마다 내리쳤다. 계단 밑에 닿을 때까지 열두 번.`,
      ng:`내리쳤는데 막대기가 물렁한 것에 박혀 안 빠진다. 내공이 막대기를 타고 빨려 나간다.<br><br>막대기를 놓았다. 손바닥이 얼얼하다. 기가 반은 빠졌다.<br>물렁한 것이 막대기를 삼키고 계단 틈으로 들어갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A', t:'어둠 — 한 푼만',
  x:`어둠 속에서 목소리가 난다. 한 푼만. 한 푼만 주세요.<br><br>
    동냥하는 소리다. 평생 그 소리를 냈다. 그런데 박자가 틀렸다. 동냥은 고개를 숙이고 낮게 한다. 이 소리는 위에서 내려온다.<br>
    등불 끝에 손 하나가 나와 있다. 손바닥을 위로.<br><br>
    손이 하나 더 나온다. 또 하나. 다 손바닥을 위로.`,
  o:[
    { l:'① 이쪽도 빈손을 내민다.', k:'bond', dc:22,
      ok:`이쪽도 손바닥을 내밀었다. 위로. "나도 빈손이오."<br><br>빌어먹는 사람은 빌어먹는 사람에게 동냥하지 않는다. 손들이 잠깐 멈춘다. 그러다 하나씩 거둬진다. 마지막 손이 거둬지기 전에 이쪽 손바닥에 마른 약초 한 줌을 떨구고 간다.<br>같은 업끼리는 빈손을 보면 조금 얹어 준다. 저쪽도 한때 그랬을 것이다.`,
      ng:`내밀었는데 손들이 이쪽 손바닥을 잡는다. 빈손이면 손이라도 달라는 것이다.<br><br>비틀어 뺐다. 손톱이 손바닥을 긁고 지나간다.<br>손바닥에 긁힌 줄이 생겼다. 손금 같다. 원래 없던 손금이다.`,
      win:{ exp:18, dream:3, item:'약초 뭉치' }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 한 푼을 쥐여 준다.', k:'luck', dc:23,
      doom:{ title:'한 푼', what:'동냥하던 손들에게 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`품에서 한 푼을 꺼내 첫 손바닥에 쥐여 줬다. 받아 봤으니 줄 줄도 안다.<br><br>손이 동전을 쥔다. 동전을 쥔 채 손목도 쥔다. 다른 손들이 다가온다. 한 푼만. 한 푼만. 팔을, 어깨를, 옷깃을 쥔다.<br>당긴다. 어둠 속으로. 한 푼씩 받으려고. 이쪽 몸을 한 푼씩.<br><br>받는 손이 얼마나 끈질긴지 안다. 제 손이 그랬다.`,
        dieText:`어둠 속에서 목소리가 난다. 한 푼만. 한 푼만 주세요.<br><br>목소리가 하나 늘었다. 낮게, 고개를 숙이고. 제대로 된 동냥 소리다.<br>등불 끝에 손이 나와 있다. 손바닥이 거칠다. 오래 빌어먹은 손이다.` },
      ok:`한 푼을 손가락 끝으로 튕겨 손바닥에 떨어뜨렸다. 손이 닿지 않게.<br><br>첫 손이 동전을 쥐고 어둠으로 거둬진다. 다른 손들이 그 손을 쫓아간다. 한 푼을 서로 뺏으러.<br>손들이 다 그쪽으로 몰린 사이 지나갔다. 한 푼으로 길을 샀다. 비싸지 않았다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A', t:'구석 — 같은 업의 마지막 자리',
  x:`복도 구석에 거적이 깔려 있다. 그 위에 그릇 하나, 자루 하나, 지팡이 하나.<br><br>
    거지 자리다. 사람은 없다. 거적이 아직 눌려 있다. 무릎을 끌어안고 앉은 모양으로.<br>
    벽에 표식이 줄지어 그어져 있다. 날마다 하나씩. 끝으로 갈수록 획이 떨린다.<br><br>
    마지막 표식은 끝까지 안 그어졌다.`,
  o:[
    { l:'① 표식을 처음부터 읽는다.', k:'gaze', dc:22,
      ok:`처음 표식은 「먹을 것 없음」, 「물 있음」. 평범하다. 중간부터 「밤에 누가 옴」, 「얼굴 보지 말 것」, 「대답하지 말 것」.<br><br>마지막 표식은 「대답」에서 멈췄다. 하지 말라는 걸 다 쓰기 전에 대답한 것이다.<br>남은 획을 마저 그어 주었다. 「대답하지 말 것.」 그리고 자루를 열었다. 소금 한 덩이와 마른 나물. 다음에 올 이의 몫이다. 반만 가져갔다.`,
      ng:`읽는데 맨 끝에 표식이 하나 늘어난다. 지금.<br><br>「뒤에 있음.」 돌아보지 않았다. 거적이 들썩인다. 무릎을 끌어안은 모양이 일어서는 모양이 된다.<br>복도 끝까지 뛰었다. 돌아보지 않았다. 그날 밤 내내 등이 시렸다.`,
      win:{ exp:18, dream:3, item:'소금 덩이' }, lose:{ mind:-17, spirit:-22 } },
    { l:'② 그릇과 자루를 거둔다.', k:'luck', dc:22,
      ok:`같은 업의 마지막 물건은 같은 업이 거둔다. 그릇과 자루를 품었다.<br><br>자루에 마른 나물이 들었다. 그릇 바닥에 꿈결 몇 알. 마지막까지 안 먹고 아껴 둔 것이다.<br>지팡이는 거적 위에 눕혀 두었다. 지팡이는 주인과 같이 둔다. 같은 업끼리의 예의다.`,
      ng:`그릇을 들자 거적 위 눌린 자국이 깊어진다. 누가 다시 앉는다.<br><br>내려놓으라는 것이다. 내려놓았다. 손이 떨려 그릇을 반쯤 엎었다. 엎은 그릇은 「빈 데」다.<br>거적 위 자국이 이쪽을 향해 고개를 든 모양이 됐다. 한참 그 앞에서 움직이지 못했다.`,
      win:{ exp:18, dream:3, item:'산나물' }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 내공을 나눈다',
  x:`쉬는 자리에서 일행 하나가 덜덜 떤다. 입술이 파랗다. 어둠 속에서 무엇에 손을 잡혔다고 한다.<br><br>
    잡힌 손이 얼음장이다. 손목에 자국이 감겼다. 자국이 조금씩 팔꿈치 쪽으로 올라온다.<br>
    내공은 혼자 쓰며 살았다. 배고플 때, 추울 때. 남에게 흘려 본 적은 없다.<br><br>
    자국이 팔꿈치에 닿았다.`,
  o:[
    { l:'① 손바닥으로 내공을 흘려 넣는다.', k:'bond', dc:23, wake:1, cost:{ qi:30 },
      ok:`그 사람 손을 맞잡았다. 배꼽 밑에서 기를 끌어올려 팔을 타고 손바닥으로 밀었다. 남의 몸에 기를 넣는 건 처음이다. 어디로 가는지 모른다. 그냥 밀었다.<br><br>자국이 멈춘다. 기가 닿는 데서 자국이 녹는다. 팔꿈치에서 손목으로, 손목에서 손끝으로. 손끝에서 검은 것이 한 방울 떨어져 바닥에서 지직거린다.<br>그 사람 입술에 핏기가 돌았다.<br><br>제 배를 채우던 기가 처음으로 남의 몸으로 흘렀다. 흘린 만큼 가벼워졌는데 비지 않았다. 기가 도는 길이 몸 밖까지 이어졌다.`,
      ng:`밀었는데 기가 그 사람 몸에서 튕겨 나온다. 차가운 것이 먼저 자리를 잡았다.<br><br>튕긴 기가 이쪽 팔로 되돌아오며 차가운 것을 묻혀 온다. 이쪽 손목에도 자국이 감긴다. 둘이 같이 떨었다.<br>새벽에야 자국이 옅어졌다. 둘 다 손이 오래 시렸다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 손목을 동여매고 불가에 둔다.', k:'steady', dc:22,
      ok:`자국 위를 천으로 단단히 동여맸다. 더 못 올라오게. 불가에 앉혀 밤새 손을 쬐게 했다.<br><br>천 밑에서 자국이 꿈틀거렸다. 매듭이 버텼다. 새벽에 풀자 자국이 손목에 고여 멈춰 있었다.<br>묶는 법은 안다. 끊어진 신발도 그렇게 묶어 신었다.`,
      ng:`동여맸는데 자국이 천을 타고 넘는다. 천에도 번진다.<br><br>천을 잘라 불에 던졌다. 연기가 사람 손 모양으로 올라갔다.<br>그 사람은 밤새 팔을 끌어안고 울었다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A', t:'처마 밑 — 떨어지는 물방울',
  x:`무너진 처마 같은 데 밑에서 잤다. 처마 밑이 집이다.<br><br>
    똑. 물방울이 이마에 떨어진다. 미지근하다. 비는 안 온다.<br>
    똑. 또. 같은 자리에. 위는 어둡다. 처마 끝에 무엇이 매달려 있다. 내려다보며 침을 흘린다.<br><br>
    침 흘리는 얼굴은 안다. 배고픈 얼굴이다.`,
  o:[
    { l:'① 잠든 척 실눈으로 기척을 잰다.', k:'sense', dc:22,
      ok:`눈을 감은 채 실눈만 떴다. 잠든 척하는 법은 안다. 잠든 빈털터리는 아무도 안 건드린다.<br><br>물방울 간격이 길어진다. 처마 끝의 것이 지루해한다. 잠든 것은 맛이 없다. 한참 만에 위로 기어 올라갔다.<br>새벽에 처마 밑을 빠져나왔다. 이마를 닦았다. 끈적했다.`,
      ng:`실눈을 떴는데 처마 끝의 것도 실눈을 뜨고 있다. 이쪽 실눈을 본다.<br><br>잠든 척인 걸 안다. 물방울이 굵어진다. 이마에서 눈두덩으로 흐른다. 눈을 못 뜨게.<br>굴러서 빠져나왔다. 눈이 따가워 한참 못 떴다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-16, spirit:-16 } },
    { l:'② 굴러 나와 위가 막힌 처마로 옮긴다.', k:'evade', dc:22,
      ok:`다음 물방울이 떨어지기 직전 옆으로 굴렀다. 물방울이 빈 바닥에 떨어진다. 지직.<br><br>일어나지 않고 낮게 기어 처마 밖으로 나왔다. 처마 끝의 것이 고개를 갸웃한다. 빈자리를 오래 본다.<br>다른 처마를 찾았다. 처마는 고를 줄 안다. 위가 막힌 처마.`,
      ng:`구르는데 처마 기둥에 어깨를 찧었다. 쿵.<br><br>처마 끝의 것이 등 위로 떨어진다. 가볍다. 차다. 등에 매달려 목덜미에 침을 흘린다.<br>벽에 등을 찧어 떨어냈다. 몇 번이고. 떨어진 것이 어둠으로 기어갔다. 목덜미가 화끈거렸다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'A', t:'내려가는 길 — 남기는 표식',
  x:`계단 앞이다. 떠나는 자리마다 표식을 남긴다. 뒤에 올 같은 업을 위해.<br><br>
    돌을 주워 벽에 댔다. 여기서 본 것을 다 그으려면 벽이 모자란다.<br>
    벽에 이미 표식이 많다. 먼저 지나간 같은 업들 것이다. 다 아래층을 가리키며 같은 말을 한다. 「내려가지 말 것」.<br><br>
    그런데 다들 내려갔다. 다른 길이 없었다.`,
  o:[
    { l:'① 내려가서 살아남는 법을 남긴다.', k:'bond', dc:22, wake:1,
      ok:`「내려가지 말 것」 밑에 새 표식을 그었다. 「내려가면 대답하지 말 것. 고개 숙일 것. 그릇 내밀 것.」<br><br>여기서 살아남은 법이다. 벽 표식에 그런 글은 없었다. 다들 피하라고만 했다. 피할 수 없을 때를 적은 건 처음이다.<br>긋고 나니 오래된 획 하나가 이쪽 표식 끝에 닿아 있다. 누가 같은 말을 쓰다 만 것이다. 이어졌다.<br><br>받기만 하던 길에서 처음으로 길을 남겼다. 혼자 빌어먹던 손이 얼굴 모를 뒷사람을 위해 획을 긋는다.`,
      ng:`긋는데 돌이 부러진다. 획이 반쯤에서 끊겼다. 「대답할 것」.<br><br>고칠 돌이 없다. 손톱으로 긁었다. 손톱이 들렸다. 「대답하지」의 「지」가 끝내 희미했다.<br>내려가는 내내 그 희미한 획이 마음에 걸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 손가락에 내공을 실어 표식을 깊이 판다.', k:'fix', dc:22, cost:{ qi:25 },
      ok:`손가락에 내공을 모아 벽에 댔다. 돌이 손가락 끝에서 물러난다. 표식이 깊이 패인다. 「고개 숙일 것.」<br><br>깊이 판 표식은 어둠 속에서도 손으로 읽힌다. 눈먼 이도 읽는다.<br>긋고 나서 손가락 끝이 뜨거웠다. 벽 표식들이 등불 아래서 한 줄로 반짝였다.`,
      ng:`모으는데 벽이 기를 먹는다. 손가락 끝이 벽에 붙는다.<br><br>떼어 냈다. 손가락 끝 살갗이 벽에 남았다. 표식 대신 손가락 자국이 찍혔다.<br>뒤에 오는 이가 그걸 무엇으로 읽을지 모르겠다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A1', t:'정문 — 문 앞 동냥 자리',
  x:`방송국 정문 안쪽 계단에 앉았다. 버릇이다. 사람 드나드는 문 앞이 제일 목이 좋다.<br><br>
    로비 텔레비전 속 노란 얼굴이 말한다. 어서 와, 친구들. 친구들은 줄을 서서 들어가는 것이다. 문 앞에 앉은 거지는 친구가 아니다.<br>
    접수처 커튼이 걷히고 갈색 털 난 것이 나온다. 단추 눈. 좀약 냄새. 들어오는 친구를 안아 들이는 것이다.<br><br>
    그것이 문 쪽으로 걸어온다. 계단에 앉은 이쪽으로.`,
  o:[
    { l:'① 그릇을 내밀고 고개를 숙인다.', k:'luck', dc:22, wake:1,
      ok:`그릇을 앞에 놓고 고개를 숙였다. 동냥하는 얼굴. 평생 그 얼굴로 살았다.<br><br>털 난 발이 앞에 멈춘다. 숙인 고개 위로 그림자가 진다. 한참. 그러다 그릇에 무엇이 떨어진다. 꿀 사탕 한 알. 손님에게 주는 사탕이 아니다. 동냥 그릇에 넣는 사탕이다.<br>발이 돌아선다. 안아 들일 친구가 아니다. 지나가는 거지다. 그것은 다시 커튼 안으로 들어갔다.<br><br>문 앞에 앉은 사람은 손님이 아니다. 손님이 아니면 이 집 규칙이 안 닿는다. 그 틈에 앉는 법을 몸이 알았다.`,
      ng:`숙였는데 사탕이 아니라 털 난 손이 그릇에 들어온다. 그릇째 이쪽 손을 잡는다.<br><br>안아 들이려는 것이다. 그릇을 놓고 손을 뺐다. 그릇이 그것의 손에 남았다. 평생 들고 다닌 그릇이다.<br>그것이 그릇을 들고 커튼 안으로 들어갔다. 커튼 밑으로 그릇 구르는 소리가 났다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-17, spirit:-24 } },
    { l:'② 문틀 밑까지 비켜 앉는다.', k:'steady', dc:22,
      ok:`계단 맨 끝, 문틀 바로 밑까지 물러나 앉았다. 문 안도 밖도 아닌 데. 빌어먹는 사람들이 늘 앉는 데다.<br><br>털 난 것이 문 앞까지 와서 두리번거린다. 문 밖은 안 본다. 손님은 문 안에 있으니까.<br>한참 뒤 그것이 돌아갔다. 그 틈에 일행을 불러 접수처 옆으로 지나갔다.`,
      ng:`물러나는데 문이 등 뒤에서 닫힌다. 문틀 밑도 문 안이 됐다.<br><br>털 난 것이 이쪽을 본다. 친구가 하나 더 왔다는 듯이 팔을 벌린다. 계단을 굴러 피했다.<br>무릎이 계단 모서리에 찍혔다. 좀약 냄새가 오래 따라왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'③ 고개를 들어 단추 눈을 본다.', k:'gaze', dc:23,
      doom:{ title:'문 앞 거지', what:'뭉치에게 안겨 커튼 안으로 끌려갑니다', dc:18, sec:50,
        text:`고개를 들었다. 단추 눈을 봤다. 동냥하는 사람은 고개를 드는 순간 손님이 된다.<br><br>단추 눈이 반짝인다. 반갑다. 친구다. 팔이 벌어진다. 털이 얼굴을 덮는다. 좀약 냄새가 숨을 막는다. 안긴다.<br>발이 계단에서 뜬다. 커튼 쪽으로. 털 사이로 숨이 겨우 쉬어진다. 커튼이 뒤에서 닫힌다.<br><br>평생 문 앞에 앉아 살았다. 문 안으로 들어가는 건 처음이다. 안아서 들여 준 것도.`,
        dieText:`방송국 정문 안쪽 계단이 비었다.<br><br>접수처 커튼 밑으로 큰 발 두 개가 보인다. 그 사이에 이 빠진 사기 그릇 하나가 놓였다.<br>명단 맨 아래 칸에 새 이름이 크레용으로 적혔다. 보호자 칸에는 뭉치.` },
      ok:`고개를 들되 눈은 그릇에 둔 채 들었다. 단추 눈은 시야 끝으로만 봤다.<br><br>단추 눈이 이쪽 눈을 찾는다. 못 찾는다. 이쪽 눈은 그릇에 있다. 그릇만 보는 사람은 손님이 아니다.<br>털 난 것이 그릇 앞에 쪼그려 같이 그릇을 들여다본다. 한참. 그러다 일어서 돌아갔다. 그릇에 말린 고기 한 조각이 들어 있었다.`,
      win:{ exp:22, dream:4, item:'말린 고기' } }
  ] },

{ at:'A1', t:'방청석 — 의자 밑 부스러기',
  x:`방청석 의자 밑에 과자 부스러기가 흩어져 있다. 사탕 껍질, 반쯤 먹은 비스킷.<br><br>
    일행은 쳐다보지도 않는다. 이쪽은 의자 밑부터 본다. 남이 흘린 데에 늘 먹을 것이 있다.<br>
    의자 밑에 손을 넣으려면 자리에 앉아야 한다. 규칙이다. 자리에서 일어나지 않기.<br><br>
    의자마다 부스러기가 한 줌씩. 한 의자 밑 비스킷만 새것처럼 바삭하다.`,
  o:[
    { l:'① 앉아서 묵은 부스러기만 줍는다.', k:'luck', dc:22,
      ok:`자리에 앉아 손만 의자 밑으로 넣었다. 새것 같은 비스킷은 건너뛰었다. 새것은 누가 방금 놓은 미끼다.<br><br>묵은 부스러기를 모았다. 눅눅하다. 그 사이에 꿀 바른 비스킷 반쪽이 묻혀 있었다. 아이가 먹다 흘린 것이다.<br>남이 흘린 것은 남 것이 아니라 길이 준 것이다.`,
      ng:`줍는데 손가락에 무엇이 감긴다. 리본이다. 의자 밑에서 나온다.<br><br>무대 쪽으로 당긴다. 리본을 이로 끊었다. 이가 시렸다.<br>손에 쥔 부스러기를 다 흘렸다. 의자 밑에서 작은 손들이 그걸 주워 갔다.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 내공을 모아 냄새로 미끼를 가린다.', k:'sense', dc:22, cost:{ qi:28 },
      ok:`숨을 가라앉히고 내공을 코끝으로 모았다. 바삭한 비스킷에서 단내 밑에 좀약 냄새가 난다. 먹으면 안 된다.<br><br>나머지 의자들을 냄새로 훑었다. 맨 뒷줄 의자 밑 상자에서 진짜 단내가 난다. 방청객 선물 꾸러미다. 육포가 들었다.<br>배고픔이 기른 코다. 내공이 그 코를 한 뼘 늘렸다.`,
      ng:`모으는데 좀약 냄새가 코를 찌른다. 기가 흩어진다. 재채기가 터졌다.<br><br>방청석이 조용해진다. 스피커가 이쪽을 향해 지직거린다. 조용히 해 주세요. 녹화 중.<br>입을 막고 한참 엎드려 있었다. 숨을 참느라 가슴이 결렸다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A1', t:'세트 뒤 — 배고픈 거지 역',
  x:`무대 세트가 동화 마을이다. 오늘 꼭지는 「착한 어린이는 나눠 줘요」. 대본이 세트 뒤 책상에 펼쳐져 있다.<br><br>
    배역 칸이 있다. 착한 어린이 — 오늘의 친구. 배고픈 거지 — 빈칸.<br>
    빈칸 옆에 소품이 놓였다. 이 빠진 그릇. 이쪽 그릇과 똑같다.<br><br>
    스피커에서 언니 목소리가 난다. 거지 아저씨, 준비해 주세요. 무대를 지나야 반대편 문이 있다.`,
  o:[
    { l:'① 세트 그림자에 섞여 지나간다.', k:'hide', dc:22, wake:1,
      ok:`그릇을 품에 넣었다. 등을 굽히고 세트 판자 앞 그림자로 걸었다. 빌어먹는 사람은 어디서든 배경이다. 아무도 배경은 안 본다.<br><br>조명이 무대 가운데를 비춘다. 오늘의 친구 자리, 거지 역 자리. 둘 다 비었다. 이쪽은 판자 그림 속 굴뚝 옆을 지난다. 굴뚝 연기처럼.<br>반대편 문에 닿았다. 스피커가 한 번 더 불렀다. 거지 아저씨. 대답하지 않았다.<br><br>안 보이는 몸이 무대 위에서도 통했다. 빛이 닿는 데서도 눈길이 비켜 가는 걸음이 생겼다.`,
      ng:`섞이는데 판자가 한 칸 옆으로 밀린다. 그림자가 사라졌다. 조명 아래 이쪽만 남았다.<br><br>스피커가 웃는다. 거지 아저씨 나왔어요. 박수가 쏟아진다. 보이지 않는 손들이 그릇을 내밀라고 팔을 당긴다.<br>판자를 넘어뜨리며 무대 밖으로 굴러 나왔다. 어깨가 빠질 뻔했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 내공으로 몸을 가볍게 해 조명 다리를 건넌다.', k:'evade', dc:23, cost:{ qi:30 },
      ok:`숨을 끌어올려 몸을 가볍게 했다. 세트 뒤 사다리를 타고 조명 다리에 올랐다. 발끝으로.<br><br>밑에서 무대가 밝아진다. 조명이 빈 배역 자리를 비춘다. 이쪽은 조명 위다. 빛은 위를 안 비춘다.<br>다리 끝에서 내려섰다. 반대편 문 바로 앞이다. 발소리가 한 번도 안 났다.`,
      ng:`오르는데 조명 다리가 흔들린다. 기가 발끝에서 새어 나간다.<br><br>조명 하나가 이쪽으로 돌아간다. 빛이 얼굴을 비춘다. 위에서 거지 아저씨를 찾았다. 박수가 쏟아진다.<br>다리에서 뛰어내렸다. 발목을 접질렸다. 절뚝이며 문까지 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 거지 역을 맡아 그릇을 내민다.', k:'bond', dc:23,
      doom:{ title:'배고픈 거지', what:'배역에 묶여 무대 가운데로 끌려갑니다', dc:18, sec:50,
        text:`소품 그릇을 들고 무대에 섰다. 거지 역이라면 평생 해 온 일이다.<br><br>조명이 쏟아진다. 오늘의 친구 자리에 인형탈이 앉아 있다. 착한 어린이 역이다. 그것이 일어나 그릇에 무엇을 넣는다. 넣고 또 넣는다. 그릇이 무거워진다.<br>그릇이 손에서 안 떨어진다. 대본에 적혀 있다. 거지는 고맙다고 말하고 끝까지 받는다. 받는 동안 무대 바닥이 천천히 돈다. 가운데로 끌려간다. 막이 내려온다.<br><br>평생 받으며 살았다. 받는 것이 이렇게 무거운 줄은 몰랐다.`,
        dieText:`동화 마을 세트에 조명이 꺼졌다.<br><br>대본 배역 칸이 채워졌다. 배고픈 거지 — 이름 하나.<br>세트 책상 위에 소품 그릇이 놓여 있다. 이가 하나 더 빠졌다.` },
      ok:`무대에 섰다. 그릇을 내밀었다. 인형탈이 무엇을 넣으려 할 때 그릇을 엎었다.<br><br>엎은 그릇은 「빈 데 — 지나감」이다. 같은 업끼리의 표식이다. 대본에는 없다. 인형탈이 넣을 데를 잃고 서 있다.<br>배역이 대본을 벗어나면 무대가 멈춘다. 조명이 깜빡이는 사이 반대편 문으로 걸어 나갔다. 박수가 어색하게 끊겼다.`,
      win:{ exp:22, dream:4 } }
  ] },

{ at:'A1', t:'사무실 복도 — 쓰레기통 셋',
  x:`사무실 복도 끝에 쓰레기통이 셋 있다. 뚜껑이 닫혔다.<br><br>
    일행은 지나친다. 이쪽은 안 지나친다. 쓰레기통은 그 집 사람들이 무엇을 먹고 무엇을 버렸는지 다 말해 준다.<br>
    첫째 통에서 볼펜 소리가 난다. 둘째 통은 조용하다. 셋째 통은 뚜껑이 조금 들려 있다. 안에서 누가 내다본다.<br><br>
    뚜껑 들린 통부터 피하는 게 순서다.`,
  o:[
    { l:'① 조용한 통을 뒤진다.', k:'luck', dc:22,
      ok:`둘째 통을 열었다. 구겨진 종이, 빈 도시락, 귤껍질. 직원들이 버린 것이다. 오래됐다.<br><br>도시락 밑에 뜯지 않은 육포 봉지가 있다. 먹으려다 못 먹고 버렸다.<br>구겨진 종이 하나를 폈다. 직원 공지다. 「5시 이후 7층 출입 금지.」 그 밑에 누가 볼펜으로 적었다. 「비상계단은 열려 있음.」`,
      ng:`여는데 안에서 무엇이 손목을 문다. 이가 작다. 사탕 껍질 사이에서.<br><br>뿌리쳤다. 통이 넘어지며 쓰레기가 쏟아진다. 쓰레기 사이에서 작은 것들이 흩어져 달아난다.<br>손목에 작은 잇자국이 줄지어 났다. 오래 쓰렸다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 볼펜 소리 나는 통의 종이를 읽는다.', k:'gaze', dc:22,
      ok:`첫째 통을 열었다. 볼펜 한 자루가 종이 위에서 저 혼자 쓴다. 같은 줄을. 「오늘도 방송 나감.」<br><br>쓰는 종이를 빼고 밑에 깔린 종이들을 읽었다. 일지다. 날짜가 거꾸로 간다. 맨 밑 장에 적혀 있다. 「송출 스위치는 맨 위. 다섯 시 전에.」<br>볼펜은 놔두고 뚜껑을 닫았다. 쓰는 일을 막을 까닭은 없다.`,
      ng:`여는데 볼펜이 멈추고 이쪽을 향한다. 촉이 손등에 글씨를 쓴다. 「오늘도.」<br><br>손을 뺐다. 잉크가 번진다. 문질러도 안 지워진다.<br>그 손등이 밤새 저렸다. 글씨가 한 글자씩 늘어나는 느낌이 났다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-17, spirit:-22 } }
  ] },

{ at:'A1', t:'대기실 — 데운 도시락',
  x:`출연자 대기실 탁자에 도시락이 놓여 있다. 뚜껑이 열렸다. 김이 오른다. 방금 데웠다.<br><br>
    옆 도시락들은 차다. 오래 식었다. 하나만 따뜻하다.<br>
    남이 남긴 밥을 평생 먹었다. 식은 밥은 주인이 떠난 밥이다. 따뜻한 밥은 주인이 곧 돌아올 밥이다.<br><br>
    대기실 옷걸이에 인형탈 몸통이 걸려 있다. 머리가 없다.`,
  o:[
    { l:'① 식은 도시락만 먹는다.', k:'luck', dc:22,
      ok:`따뜻한 도시락은 건드리지 않았다. 식은 것을 하나 열었다. 밥이 굳었다. 반찬은 짠 나물이다. 먹을 만하다.<br><br>먹는 동안 옷걸이 몸통이 따뜻한 도시락 쪽으로 조금 기운다. 이쪽은 안 본다.<br>먹고 나서 빈 도시락을 깨끗이 닦아 제자리에 두었다. 남의 그릇은 더럽혀 두지 않는다. 남은 나물은 싸 왔다.`,
      ng:`식은 것을 열었는데 밥 위에 노란 털이 길게 얹혀 있다.<br><br>집어 내려는데 털이 손가락에 감긴다. 옷걸이 쪽으로 당긴다. 몸통이 팔을 든다.<br>털을 끊고 도시락을 놓고 나왔다. 배는 더 고팠다.`,
      win:{ exp:18, dream:3, item:'산나물' }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 주인을 기다렸다 얻어먹는다.', k:'bond', dc:22,
      ok:`대기실 구석에 쪼그려 앉았다. 그릇을 앞에 놓고. 기다리는 것도 일이다.<br><br>문이 열린다. 방글이 머리가 들어와 옷걸이 몸통에 얹힌다. 그것이 따뜻한 도시락 앞에 앉는다. 먹지 않는다. 그려 넣은 입은 먹지 못한다.<br>한참 앉아 있다가 도시락을 이쪽 그릇에 덜어 준다. 먹지 못하는 것이 먹을 사람에게 준다. 짐승 고기 볶음이다. 데운 지 얼마 안 됐다.`,
      ng:`기다렸는데 문이 열리고 머리만 들어온다. 몸통 없이. 공중에 떠서.<br><br>머리가 그릇을 들여다본다. 비었다. 동냥 그릇을 처음 본다는 듯이 입을 크게 벌린다. 웃는 입이 그릇 쪽으로 내려온다.<br>그릇을 안고 뛰었다. 등 뒤에서 머리가 몸통 위로 털썩 얹히는 소리가 났다.`,
      win:{ exp:20, dream:3, item:'짐승 고기' }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A2', t:'식당 — 배식 줄 맨 끝',
  x:`식당에 줄이 서 있다. 가슴까지 찬 물속에서. 식판을 든 교복들이 한 줄로.<br><br>
    배식대 뒤에서 국자가 움직인다. 식판에 하나씩 퍼 준다. 물속인데 국에서 김이 오른다.<br>
    줄 맨 끝에 서는 법은 안다. 맨 끝에 서면 남는 것을 받는다. 앞에 끼면 매를 맞는다.<br><br>
    줄 맨 끝 바로 앞자리가 비었다. 식판 하나가 물 위에 떠 있다.`,
  o:[
    { l:'① 맨 끝에 서서 남는 것을 받는다.', k:'luck', dc:22, wake:1,
      ok:`빈자리를 건너뛰고 맨 끝에 섰다. 식판 없이. 그릇을 들고.<br><br>줄이 앞으로 간다. 빈자리 식판도 물살에 떠서 간다. 배식대 앞에서 국자가 빈 식판에 국을 붓는다. 받을 사람 없는 국이 물에 풀린다.<br>맨 끝 차례. 국자가 그릇을 보고 잠깐 멈춘다. 그러다 남은 것을 다 쏟아 준다. 국이 아니라 말린 고기와 나물이다. 배식대 밑에 아껴 둔 것이다.<br><br>줄 끝에 서는 버릇이 여기서도 통했다. 맨 뒤에서 받는 법이 기다림이 아니라 기술이 됐다.`,
      ng:`맨 끝에 섰는데 뒤에 누가 또 선다. 또. 줄이 이쪽 뒤로 길어진다. 이제 맨 끝이 아니다.<br><br>앞으로 밀린다. 배식대 앞이다. 국자가 그릇에 국을 붓는다. 물에 풀린 국이 차다. 손이 저린다.<br>그릇을 엎고 줄을 빠져나왔다. 뒤에 선 것들이 고개를 돌려 이쪽을 오래 봤다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-14, spirit:-16 } },
    { l:'② 배식대 밑을 노린다.', k:'fix', dc:22,
      ok:`줄에 서지 않았다. 배식대 옆으로 돌아가 쪼그렸다. 배식대 밑은 안다. 흘린 것, 남긴 것, 덜어 둔 것.<br><br>밑 칸에 뚜껑 덮인 통이 있다. 소금에 절인 생선이다. 받을 사람이 다 오지 않아 남은 몫이다.<br>한 마리만 꺼냈다. 나머지는 다음에 올 이의 몫이다.`,
      ng:`쪼그렸는데 배식대 위에서 국자가 내려온다. 머리를 툭 친다. 줄 서라는 것이다.<br><br>세게. 다시. 머리를 감싸고 물러났다. 정수리에 혹이 났다.<br>국자가 배식대 위로 올라갔다. 계속 퍼 주는 소리가 났다.`,
      win:{ exp:18, dream:3, item:'민물고기' }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 빈자리 식판을 집어 줄에 낀다.', k:'hide', dc:23,
      doom:{ title:'빈 식판', what:'배식 줄에 끼어 물 밑 식당으로 끌려갑니다', dc:19, sec:45,
        text:`빈 식판을 집어 빈자리에 섰다. 앞에 끼는 건 처음이다. 배가 고팠다.<br><br>앞뒤 교복이 이쪽을 본다. 반갑다는 얼굴이다. 빈자리가 채워졌다. 뒤에서 누가 어깨에 손을 얹는다. 줄을 맞추라고.<br>줄이 앞으로 간다. 이쪽도 간다. 바닥이 올라온다. 아니, 줄 전체가 물 밑으로 내려간다. 아래층 식당으로. 다들 식판을 들고.<br><br>줄에 낀 사람은 끝까지 줄에 있어야 한다. 그래서 평생 끼지 않았다.`,
        dieText:`식당에 줄이 서 있다. 식판을 든 교복들이 한 줄로.<br><br>빈자리가 없다. 수염이 덥수룩한 하나가 줄 중간에 서 있다. 식판을 들고.<br>배식대 국자가 그 식판에 국을 붓는다. 김이 오른다.` },
      ok:`빈 식판을 집었다. 줄에 끼지 않았다. 식판을 맨 끝 교복에게 건넸다.<br><br>맨 끝 교복이 식판을 받아 빈자리로 한 칸 당겨 선다. 이제 맨 끝이 빈다. 그 자리에 섰다. 거지 자리다.<br>줄이 다 받고 남은 것을 받았다. 식판 없이, 그릇으로. 생선 한 토막이었다.`,
      win:{ exp:22, dream:4, item:'민물고기' } }
  ] },

{ at:'A2', t:'보일러실 — 재 속 온기',
  x:`보일러실 화구 앞에 재가 쌓였다. 물이 무릎까지 찼는데 재 더미 위는 말라 있다.<br><br>
    겨울마다 재 속에서 잤다. 재는 오래 따뜻하다. 감자를 묻어 두면 익는다.<br>
    재 더미 한쪽이 불룩하다. 누가 묻어 둔 것이 있다.<br><br>
    화구 안에서 불이 탄다. 작업복 입은 그림자가 그 앞에 쪼그려 앉아 있다. 이쪽을 안 본다.`,
  o:[
    { l:'① 재를 헤쳐 묻어 둔 것을 꺼낸다.', k:'luck', dc:22,
      ok:`손바닥으로 재를 살살 헤쳤다. 세게 헤치면 불씨가 튄다.<br><br>불룩한 데서 깡통이 나왔다. 열어 보니 버섯과 나물이 익어 있다. 화부가 묻어 둔 끼니다.<br>반만 덜고 깡통을 도로 묻었다. 화부 그림자가 고개를 아주 조금 끄덕였다. 재 속 끼니를 아는 사람끼리는 반을 나눈다.`,
      ng:`헤치는데 재 속에서 손이 나온다. 재투성이 손이다. 깡통을 쥐고 놓지 않는다.<br><br>화부 그림자가 처음으로 돌아본다. 얼굴이 불빛에 가려 안 보인다. 놓으라는 것이다. 놓았다.<br>손바닥이 재에 데었다. 물에 담가도 한참 화끈했다.`,
      win:{ exp:18, dream:3, item:'야생 버섯' }, lose:{ hp:-24, spirit:-20 } },
    { l:'② 재 위에 앉아 내공을 돌려 몸을 말린다.', k:'steady', dc:22, cost:{ qi:28 },
      ok:`마른 재 위에 가부좌를 틀고 내공을 돌렸다. 재의 온기와 몸의 열이 만난다. 젖은 옷에서 김이 오른다.<br><br>일행을 재 위로 불러 등을 붙여 앉혔다. 등에서 나는 열이 다들 등을 말렸다.<br>화부 그림자는 끝까지 불만 봤다. 재 위에 앉은 사람은 불 앞의 손님이 아니다. 재 주인과 같은 편이다.`,
      ng:`돌리는데 재 속 불씨가 기를 따라 올라온다. 엉덩이가 뜨겁다.<br><br>옷이 탄다. 물에 주저앉았다. 김이 확 올랐다. 기가 다 흩어졌다.<br>화부 그림자가 돌아보며 웃는 것 같았다. 화상이 남았다.`,
      win:{ exp:20, dream:3, hp:8 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A2', t:'기숙사 — 침대 아닌 데',
  x:`기숙사 방에 침대가 열두 개. 다 물에 반쯤 잠겼다. 하나만 물 위로 높이 떠 있다. 이불이 말라 있다.<br><br>
    일행이 지쳤다. 그 침대를 본다.<br>
    침대에서 자 본 적이 거의 없다. 바닥, 처마 밑, 다리 밑. 침대는 주인이 정해진 자리다. 주인 정해진 자리에는 점호가 온다.<br><br>
    복도 스피커가 지직거린다. 밤 아홉 시 점호가 곧이다.`,
  o:[
    { l:'① 침대를 두고 사물함 위에서 웅크려 잔다.', k:'steady', dc:22, wake:1,
      ok:`침대는 쳐다보지 않았다. 사물함 위로 올라가 무릎을 끌어안고 웅크렸다. 일행도 하나씩 사물함과 창틀 위로 올렸다.<br><br>점호가 시작된다. 침대마다 대답이 난다. 거품으로. 마른 침대에서도 대답이 난다. 거기 누가 누워 있다. 아까부터.<br>사물함 위에는 번호가 없다. 부를 수 없는 데서 자는 사람은 셀 수가 없다. 점호가 지나갔다.<br><br>평생 셈 밖에서 잤다. 그게 여기서는 살 길이다. 셀 수 없는 자리를 고르는 눈이 잠자리마다 먼저 간다.`,
      ng:`웅크렸는데 사물함 문이 안에서 열린다. 안에 교복이 웅크려 있다. 이쪽처럼.<br><br>점호가 이 사물함 번호를 부른다. 안에서 대답한다. 네. 그리고 이쪽 몫까지 대답한다. 네.<br>뛰어내려 물에 빠졌다. 점호가 끝날 때까지 물속에 숨었다. 숨이 끊어질 뻔했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 마른 침대에서 한숨만 잔다.', k:'luck', dc:23,
      doom:{ title:'마른 침대', what:'점호에 대답하고 침대째 물 밑으로 가라앉습니다', dc:19, sec:45,
        text:`마른 침대에 누웠다. 이불이 보송하다. 이런 이불을 덮어 본 건 오래전이다. 눈이 감긴다.<br><br>점호가 시작된다. 번호. 대답. 번호. 대답. 이 침대 번호. 입이 저절로 열린다. 네.<br>대답하자 침대가 천천히 가라앉는다. 이불이 젖는다. 몸이 이불에 감긴다. 이불이 놓지 않는다. 침대째 물 밑으로 끌려 내려간다. 점호는 계속된다.<br><br>주인 정해진 자리에 누우면 주인이 된다. 그걸 알아서 평생 바닥에서 잤다.`,
        dieText:`기숙사 방에 침대가 열두 개. 다 물에 잠겼다.<br><br>물속 침대 하나에 누가 누워 있다. 이불을 목까지 덮고. 수염이 물결에 흔들린다.<br>점호 때마다 그 침대에서 대답이 난다. 거품으로.` },
      ok:`누웠다. 이불은 덮지 않았다. 신을 신은 채 등만 댔다. 그릇은 가슴 위에 엎어 두었다.<br><br>점호가 이 침대 번호를 부른다. 입을 다물었다. 가슴 위 엎은 그릇이 대신 말한다. 「빈 데.」 점호가 잠깐 멈춘다. 다음 번호로 넘어갔다.<br>한숨 푹 잤다. 깨어 보니 그릇 바닥에 물방울이 동그랗게 맺혀 있었다.`,
      win:{ exp:22, dream:4, hp:8 } }
  ] },

{ at:'A2', t:'세면장 — 훌쩍이는 수도꼭지',
  x:`세면장 수도꼭지에서 물이 똑똑 떨어진다. 사방이 물인데 마실 물이 없다. 고인 물은 다 탁하다.<br><br>
    일행이 목이 탄다. 평생 더러운 물을 마셨다. 마셔도 되는 더러운 물과 안 되는 더러운 물이 있다.<br>
    수도꼭지 물은 맑다. 그런데 떨어질 때마다 소리가 난다. 아이가 훌쩍이는 소리.<br><br>
    세면대 거울에 김이 서려 있다. 누가 방금 세수를 했다.`,
  o:[
    { l:'① 그릇에 받아 옷자락으로 거른다.', k:'luck', dc:22,
      ok:`그릇을 수도꼭지 밑에 댔다. 받은 물을 옷자락 네 겹으로 다시 걸렀다.<br><br>천에 긴 머리카락 한 올이 남는다. 버리고 다시 걸렀다. 맑아졌다. 훌쩍이는 소리도 그쳤다.<br>한 모금 마시고 일행에게 돌렸다. 차다. 쇠 맛이 조금 난다. 마셔도 되는 물이다.`,
      ng:`받는데 훌쩍이는 소리가 그릇 안에서 난다. 그릇 물 위에 얼굴이 비친다. 이쪽 얼굴이 아니다.<br><br>그릇을 엎었다. 엎은 물이 바닥에서 얼굴 모양으로 고인다. 한참 고여 있다가 배수구로 빨려 들었다.<br>목은 끝까지 말랐다. 입술이 갈라졌다.`,
      win:{ exp:18, dream:3, item:'맑은 물' }, lose:{ hp:-22, mind:-16 } },
    { l:'② 내공으로 물을 데워 탁기를 걷는다.', k:'heal', dc:22, cost:{ qi:28 },
      ok:`그릇에 물을 받아 두 손으로 감쌌다. 내공을 손바닥으로 흘려 끓기 직전까지 데웠다.<br><br>물 위로 뿌연 것이 떠오른다. 작은 손톱 같은 것들. 걷어 냈다. 물이 맑아진다. 식혀서 돌렸다. 다들 살아난 얼굴이다.<br>내공은 불 없을 때의 불이다.`,
      ng:`데우는데 물이 손바닥 기를 빨아들인다. 그릇이 거꾸로 차가워진다.<br><br>그릇이 얼음장이 됐다. 손바닥이 그릇에 붙었다. 한참 입김을 불어 떼어 냈다.<br>손바닥 살갗이 얼어 벗겨졌다.`,
      win:{ exp:18, dream:3, hp:8 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A2', t:'종탑 계단 — 물에서 올라오는 손',
  x:`종탑 계단이 물속으로 내려간다. 내려가야 한다.<br><br>
    계단 양옆 물속에서 손이 올라온다. 하나, 둘, 열. 지나가는 발목을 잡으려고 기다린다. 손바닥이 위를 본다.<br>
    막대기를 쥐었다. 길에서 늘 쥐고 다니던 막대기다. 휘두르지 않고 앞을 툭툭 쳐서 물러서게 하는 법을 안다.<br><br>
    손들이 막대기 끝을 본다.`,
  o:[
    { l:'① 막대기에 내공을 실어 손들을 물린다.', k:'break', dc:23, wake:1, cost:{ qi:30 },
      ok:`막대기 끝에 내공을 실었다. 휘두르지 않았다. 앞을 툭툭 쳤다. 물 위를, 손 바로 앞을. 쳐야 할 데는 손이 아니라 손이 나오려는 자리다.<br><br>막대기 끝이 물을 칠 때마다 손들이 움츠린다. 어디로 올지 모르는 끝이 제일 무섭다. 한 칸씩 물리며 내려갔다. 일행이 막대기 뒤를 따랐다. 한 번도 안 잡혔다.<br><br>내공이 실리자 막대기 끝이 길을 연다. 길에서 쥐고 다니던 막대기 쓰는 손에 처음으로 한 수가 더해졌다.`,
      ng:`치는데 손 하나가 막대기 끝을 쥔다.<br><br>당긴다. 기가 막대기를 타고 빨려 나간다. 막대기를 놓쳤다. 손들이 막대기를 물 밑으로 끌고 갔다.<br>맨손으로 벽을 짚고 내려갔다. 발목을 두 번 잡혔다. 두 번 다 뿌리쳤다. 발목에 시퍼런 손자국이 감겼다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 손이 들어가는 박자에 건너뛴다.', k:'evade', dc:22,
      ok:`손들을 봤다. 올라왔다가 물 밑으로 들어간다. 숨 쉬듯이. 들어갈 때 한 칸이 빈다.<br><br>빈 칸만 골라 건너뛰었다. 몸이 가볍다. 늘 덜 먹어서. 계단 밑까지 손 하나 안 닿았다.<br>뒤돌아보니 손들이 이쪽이 디딘 칸을 늦게 쥐고 있었다.`,
      ng:`건너뛰는데 손들이 박자를 바꾼다. 빈 칸에서 손이 올라온다.<br><br>발목을 잡혀 물속으로 반쯤 끌려 들어갔다. 일행이 옷깃을 잡고 당겼다. 손이 신발만 가져갔다.<br>맨발로 계단을 내려갔다. 발바닥이 차서 감각이 없었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, mind:-14 } }
  ] }

]);
